-- ShamanPower zhCN — full string table (5493 entries).
--
-- Not limited to the keys locale/enUS.lua has: every string the addon shows is
-- here, keyed by the English text exactly as it appears in the source. Wrap a
-- string in L[] and its Chinese is already in this table; nothing else needed.
--
-- Only strings that still appear somewhere in the current source are included,
-- so nothing here points at text that has been removed. Fragments that are
-- concatenated at runtime (leading or trailing spaces) are kept as their own
-- entries, because that is the form L[] would see them in.
--
-- Generated from the translation memory of the project at
-- https://github.com/ray929/ShamanPower_zhCN — wording fixes are welcome.
local L = LibStub("AceLocale-3.0"):NewLocale("ShamanPower", "zhCN")
