L[" In a fight on WoW: Forever only the shield's time counts: the game hides its charges there (its number still turns red on the last one)."] = " 在 WoW: Forever 的战斗中只计算护盾时间：游戏会在那里隐藏层数（最后一层时数字仍会变红）。"
L[" In a fight on WoW: Forever the game draws it, so it is exact to the second."] = " 在 WoW: Forever 的战斗中由游戏绘制，因此精确到秒。"
L[" In a fight on WoW: Forever the game's Cooldown Manager tells the moment: keep it enabled with your shield in it."] = " 在 WoW: Forever 的战斗中，由游戏的冷却管理器提示这一时刻：请保持其启用，并将你的护盾加入其中。"
L[" In a fight on WoW: Forever the shield's glow sits under the game's shield icon, so it shows the moment the icon goes (at 100% Cooldown Bar opacity)."] = " 在 WoW: Forever 的战斗中，护盾的发光位于游戏护盾图标之下，因此图标一消失就会显示（冷却条不透明度为 100% 时）。"
L[" In a fight on WoW: Forever the shield's red sits under the game's shield icon, so it shows the moment the icon goes (at 100% Cooldown Bar opacity)."] = " 在 WoW: Forever 的战斗中，护盾的红色位于游戏护盾图标之下，因此图标一消失就会显示（冷却条不透明度为 100% 时）。"
L[" In a fight the game draws it, so it is exact to the second."] = " 战斗中由游戏绘制，因此精确到秒。"
L[" In a fight the game draws the alert."] = " 战斗中游戏会绘制该提醒。"
L[" In a fight the game draws these alerts: a key you change during a fight shows after it."] = " 战斗中游戏会绘制这些提醒：战斗中更改的按键会在战斗结束后显示。"
