L[", the Blizzard Totem Sets switches on."] = "，并开启“暴雪图腾组”。"
L[", the Windfury Companion"] = ", 风怒助手"
L[", warn them shortly before it is back, and answer when someone asks for it in chat. Everything here is off until you turn it on."] = "，在其即将就绪前提醒他们，并在有人在聊天中请求时回应。此处所有功能默认关闭，开启后才生效。"
L[", with the time it has left"] = "，并显示剩余时间"
L["- Bar Gradient, Outline Gradient and Charge Bar Gradient: Flat, with their directions and colors\n"] = "- 条渐变、描边渐变与层数条渐变：纯色，以及它们的方向和颜色\n"
L["- Bar Texture and Shield Charge Bars: Default\n"] = "- 条材质与护盾层数条：默认\n"
L["- Dot Shape: Round, Gem Dot Finish off\n"] = "- 圆点形状：圆形，宝石圆点质感关闭\n"
L["- Duration Bar Background on\n"] = "- 持续时间条背景：开启\n"
L["- Frame Edge: Plain\n"] = "- 框体边缘：朴素\n"
L["- Glow Shape: Square\n"] = "- 光晕形状：方形\n"
L["- Icon Shape on the totem bar, cooldown bar and Ready Reminders: Square, Keep Borders Square off\n"] = "- 图腾条、冷却条与就绪提醒的图标形状：方形，保持直角边框关闭\n"
L["- Never: your name, realm, guild, who you group with, or chat"] = "- 绝不包含：你的名字、服务器、公会、你与谁组队，或聊天内容"
L["- The settings you changed from the default\n"] = "- 你从默认值更改过的设置\n"
L["- Whether you are in combat and what ShamanPower can show right now\n"] = "- 你是否在战斗中，以及 ShamanPower 当前能显示什么\n"
L["- Which ShamanPower features loaded, any problems loading them, and when your settings were last saved\n"] = "- 哪些 ShamanPower 功能已加载、加载时的任何问题，以及你的设置上次保存的时间\n"
L["- Your game, language, ShamanPower version, class, spec and level range\n"] = "- 你的游戏、语言、ShamanPower 版本、职业、专精和等级范围\n"
L["- Your recent ShamanPower errors (BugSack's too), the spells you know, your addon list, screen size and key bindings\n"] = "- 你最近的 ShamanPower 错误（以及 BugSack 的错误）、你已知的法术、插件列表、屏幕尺寸和按键绑定\n"
L["- each shield's charges: the Bar\n\n"] = "- 每个护盾的层数：条\n\n"
L["- every color option on every page: Cooldown Text, Pulse Bar and Pulse Flash, Compact outline, Mana Tint,"] = "- 每个页面上的所有颜色选项：冷却文字、脉冲条与脉冲闪烁、紧凑描边、法力色调、"
L["- everything Reset Theme and All Colors does: the Standard theme with nothing changed, and every color option on every page\n"] = "- “重置主题及所有颜色”所做的全部内容：未经更改的标准主题，以及每个页面上的所有颜色选项\n"
L["- the Standard theme, with no separate choices for individual features, color edits or element-colored borders\n"] = "- 标准主题，不单独设置各功能、颜色编辑或元素色边框\n"
L["- the default Element Colors and Status Colors\n"] = "- 默认的元素颜色与状态颜色\n"
L["-Click Casts Your Other Shield"] = "-点击施放另一种护盾"
L["."] = "。"
L[". Along the Bar follows each bar: left to right, or bottom to top on a vertical bar."] = " 上的起始位置。沿条方向会跟随各条的走向：水平条从左到右，垂直条从下到上。"
L[". Along the Bar follows each bar: left to right, or bottom to top on a vertical bar. Shown when Bar Gradient (Totem Bar > Duration Bars or Appearance > Themes) is not Flat."] = "。“沿条”会跟随每个条：从左到右，垂直条则从下到上。当“条渐变”（图腾条 > 持续时间条或外观 > 主题）不为“扁平”时显示。"
L[". Change each totem's size in Settings > Group Tools > Party Buff Tracker > Coverage."] = "。可在“设置 > 团队工具 > 小队增益追踪器 > 覆盖”中更改每个图腾的大小。"
L[". Click to use this name."] = "。点击使用此名称。"
L[". Delete a macro you don't use (Esc > Macros), then "] = "。请删除一个你不用的宏（Esc > 宏），然后 "
L[". Don't Switch: your profile stays as it is."] = "时使用的配置。「不切换」表示保持当前配置不变。"
L[". Hover a style to see it in the live preview (the arrow tab on the right)."] = "。将鼠标悬停在某种样式上，可在实时预览中查看（右侧的箭头标签）。"
L[". It is in use. Right-click it any time to change its totems or icon."] = "。它正在使用中。随时右键点击它可更改其图腾或图标。"
L[". It shows beside the row here and on its box in Unlock UI."] = " 起一个新名称。它会显示在此行旁边，以及解锁界面中其框体上。"
L[". Pick another card and they wait here until you save or discard them."] = "。选择其他卡片后，它们会留在这里，直到你保存或放弃。"
L[". Pick how under Show The Buff."] = "。在“显示增益”下选择显示方式。"
L[". Picking a button that is already placed swaps the two."] = " 个位置。选择已放置的按钮会交换两者。"
L[". Right-click a spell above to move it or send it back to the shared spot."] = "。右键点击上方的法术可移动它，或将其送回共享位置。"
L[". Saving replaces it with this look."] = " 的主题。保存后将以当前外观替换它。"
L[". Signal: "] = "。信号："
L[". The first one is the loadout you switch to when you enter."] = "。第一个是你在进入时切换到的配装。"
L[". The other ShamanPower macros were made or updated"] = "。其他 ShamanPower 宏已创建或更新"
L[". You can include Shift, Ctrl or Alt. Esc over a button clears its key."] = "。可以包含 Shift、Ctrl 或 Alt。在按钮上按 Esc 会清除其按键。"
L[". Your totem bar and cooldown bar start low in the middle of the screen: move them with |cffffffff/sp unlock|r."] = "。你的图腾条和冷却条初始位于屏幕中下方：使用 |cffffffff/sp unlock|r 移动它们。"
L["0: sized to the icon. Its font and outline: Appearance > Fonts & Textures > Windfury Proc."] = "0：按图标大小自适应。字体与描边见 外观 > 字体与材质 > 风怒触发。"
L["1 OUT"] = "1 人超出"
L["100% is Blizzard's original bar size. Your chosen size returns after Edit Mode."] = "100% 为 Blizzard 的原始图腾条尺寸。退出编辑模式后会恢复你选择的尺寸。"
L["1st Position"] = "第 1 位"
L["2. Its rules: Appearance > Visibility (Hide Out of Combat, Out Of The Way).\n"] = "2. 它的规则：“外观 > 可见性”（战斗外隐藏、避让）。\n"
L["2nd Position"] = "第 2 位"
L["3. Center Both Bars, then Unlock UI to put it where you want."] = "3. “两条均居中”，然后用“解锁界面”把它放到你想要的位置。"
L["3rd Position"] = "第 3 位"
L["4th Position"] = "第 4 位"
L[": ShamanPower only takes it while you hold "] = "：只有在你按住时 ShamanPower 才会占用它 "
L[": Square, Flat (the picture's border removed), Rounded or Circle."] = "：方形、扁平（去掉图片的边框）、圆角或圆形。"
L[": a glow, a pulse, both, or nothing."] = "：发光、脉冲、两者兼有，或什么都不做。"
L[": at the end of your totem bar (its Bar setting). Right-click it for its settings, the same"] = "：位于图腾条末端（其“条”设置）。右键点击可打开其设置，与"
L[": casts it on your assigned target."] = "：对你指定的目标施放。"
L[": change it in either place."] = "：在任一位置修改均可。"
L[": click to put your bar on it. Your four buttons switch to its totems."] = "：点击可把你的条放上去。你的四个按钮会切换到它的图腾。"
L[": how its flat boxes show which totem it is. Use Theme's follows Show Icons As at the top."] = "：其扁平方块如何表示对应的图腾。“使用主题的”会跟随顶部的图标显示方式。"
L[": its totems are this line. To put your bar on it, turn on Call Flyout on Drop All"] = "：它的图腾就是这一行。要把你的条放上去，请开启“全部插放时弹出召唤菜单”"
L[": switching when combat ends"] = "：战斗结束后切换"
L[": the class colors its dots use. Use Theme's follows Class Colors at the top."] = "：其圆点使用的职业颜色。“使用主题的”会跟随顶部的职业颜色。"
L[": the color this part uses. Use Theme's: the theme's own."] = "：此部分使用的颜色。“使用主题的”：使用主题自身的颜色。"
L[": the element colors this part uses. Use Theme's follows Element Colors at the top"] = "：此部分使用的元素颜色。“使用主题的”会跟随顶部的元素颜色"
L[": the game plays it, so the page's Volume doesn't change it."] = "：由游戏播放，因此本页的音量不会影响它。"
L[": the raid gets one of the two, not both"] = " 冲突：团队只能获得其中之一，不会同时获得"
L[": the shield colors this part uses. Use Theme's follows Shield Colors at the top."] = "：此部分使用的护盾颜色。“使用主题的”会跟随顶部的护盾颜色。"
L[": the theme this part uses. Use Selected Theme follows the theme picked at the top of this page."] = "：此部分使用的主题。“使用所选主题”会跟随本页顶部选择的主题。"
L[": while the controller look is on, it only holds ShamanPower's buttons."] = "：手柄外观开启时，它只承载 ShamanPower 的按钮。"
L[": you haven't learned it yet"] = "：你尚未学会它"
L[": you haven't learned it yet."] = "：你尚未学会它。"
L[": your bar is on this Call. Its totems are your four buttons."] = "：你的条就在这个召唤上。它的图腾就是你的四个按钮。"
L[":|r Cast totem"] = "：|r 施放图腾"
L["; while that can't be told yet, it always shows."] = "；暂时无法判定时，它始终显示。"
L["? Its loadouts go back to Everywhere; no loadout is deleted."] = "？其中的配装会回到“所有区域”，不会删除任何配装。"
L["A 3-segment line at the start of the bar showing your Lightning or Water Shield charges. Click it to recast."] = "图腾条起始处的 3 段线条，显示你的闪电之盾或水之盾层数。点击可重新施放。"
L["A Shield"] = "一面盾牌"
L["A WeakAura so your shaman can see your Windfury (melee)."] = "一个 WeakAura，让你的萨满能看到你的风怒（近战）。"
L["A bar along the bottom of the button, one piece per charge."] = "按钮底部的一条，每层一段。"
L["A bar along the bottom of the shield button with one segment per charge, filled to the charges left: the same look as the Shield Charges display's charge bar."] = "护盾按钮底部的一条，每层一段，填充至剩余层数：与护盾层数显示的层数条外观一致。"
L["A bar inside the icon along its bottom, one piece per charge, as on the cooldown bar."] = "图标内底部的一条，每层一段，与冷却条一致。"
L["A bar under the display with one segment per charge, filled to the charges left."] = "显示区域下方的一条，每层一段，填充至剩余层数。"
L["A bar with one piece per charge ("] = "每层一段的条（"
L["A big totem icon when you or your group is feared, poisoned or diseased. Right-click an alert for its settings."] = "当你或你的队伍被恐惧、中毒或患病时，显示大图腾图标。右键点击提醒可打开其设置。"
L["A buff that lasts longer than this counts as long."] = "持续时间超过此值的增益视为长时增益。"
L["A buff's time left on every Ready Reminders icon. An icon's own Time Left Size (its right-click menu) wins."] = "每个就绪提醒图标上增益的剩余时间。图标自身的“剩余时间大小”（右键菜单中）优先。"
L["A buff's time left on its Ready Reminder (the same switch as Ready Reminders > Color the Buff Timers)."] = "增益在其就绪提醒上的剩余时间（与 就绪提醒 > 为增益计时着色 是同一开关）。"
L["A buff's time left on its icon changes color as it runs out: the Buff Timers colors on Appearance > Colors & Borders"] = "图标上增益的剩余时间会随耗尽而变色：外观 > 颜色与边框中的“增益计时器”颜色"
L["A button whose totem is not down fades to the opacity below. The elements you have down stay as they are."] = "图腾未插下的按钮会淡出到下方的透明度。已插下的元素保持不变。"
L["A class, or for paladins, shamans and druids the specs that matter. Picking anything here sets Watch to Custom."] = "选择职业；对圣骑士、萨满和德鲁伊则是相关专精。在此选择任何内容都会将“监视”设为“自定义”。"
L["A code holds a whole profile and your saved themes. Export yours to back it up; import someone's to try it. Importing makes a new profile; this one stays."] = "代码包含整套配置和你保存的主题。导出你的代码以备份；导入别人的代码来试用。导入会创建新配置，当前配置保持不变。"
L["A colored bar beside the button that runs down with the time left."] = "按钮旁一条彩色进度条，随剩余时间递减。"
L["A complete setup with bars, sizes, colors, positions and all features ready to use. Preview it before applying it. Your totem choices and raid assignments stay as they are."] = "包含动作条、大小、颜色、位置及所有功能的完整方案，可直接使用。应用前可先预览。你的图腾选择和团队分配保持不变。"
L["A cooldown on the bar that is ready again plays this, in gold."] = "条上的冷却再次就绪时播放此效果，以金色呈现。"
L["A cooldown's number on the bar changes color as it runs: the Cooldown Numbers colors on Appearance > Colors & Borders"] = "条上的冷却数字会随冷却进行而变色：即“外观 > 颜色与边框”中的“冷却数字”颜色"
L["A cooldown's number on the cooldown bar (the same switch as Cooldown Bar > Color the Cooldown Numbers). Only a number ShamanPower draws."] = "冷却条上的冷却数字（与 冷却条 > 为冷却数字着色 是同一开关）。仅限 ShamanPower 绘制的数字。"
L["A corner dot for each party member: class color when they have your totem's buff, red when they don't."] = "每个小队成员一个角落圆点：拥有你图腾增益时为职业色，没有时为红色。"
L["A countdown on the icon shows how long the Windfury buff has left - white, then yellow, then red."] = "图标上的倒计时显示风怒增益剩余时间——白色、黄色，再到红色。"
L["A darker rim and a soft highlight on every party dot and Totem Coverage dot, cut to the Dot Shape (Ring has none). The same setting as on Appearance > Themes."] = "为每个小队圆点与图腾覆盖圆点添加更深的边缘和柔和的高光，并按“圆点形状”裁切（“环形”没有）。与“外观 > 主题”中的设置相同。"
L["A dot in class color only for party members WITHOUT the totem's buff. Anyone who has it shows no dot, so no dots means everyone is covered."] = "仅对未获得该图腾增益的小队成员显示职业色圆点。拥有该增益者不显示圆点，因此没有圆点就表示所有人都已覆盖。"
L["A dot in class color only for party members WITHOUT the totem's buff. Anyone who has it shows no dot. In fights on WoW: Forever the game hides buffs, so this then goes by estimated range: no dots means everyone looks close enough to your totem, not that their buffs were checked. Turn this off for dots that stay exact in fights."] = "仅对未获得该图腾增益的小队成员显示职业色圆点。拥有该增益者不显示圆点。在 WoW: Forever 的战斗中游戏会隐藏增益，因此此时改为按估算范围判断：没有圆点表示所有人看起来都离你的图腾足够近，并不代表已检查他们的增益。若希望战斗中圆点保持精确，请关闭此项。"
L["A dot in class color only for party members WITHOUT the totem's buff; anyone who has it shows no dot."] = "仅为没有该图腾增益的小队成员显示职业色圆点；拥有增益的人不显示圆点。"
L["A dot per party member instead of the names, like the totem bar's dots: class color with the buff, red without."] = "用每个小队成员一个圆点代替名字，与图腾条的圆点一致：有增益为职业色，无增益为红色。"
L["A dropped box lines up with the grid. One or the other: turning this on turns Snap to Boxes off."] = "松开的框体会与网格对齐。两者只能选一：开启此项会关闭“吸附框体”。"
L["A faint ring where a used charge was, so you always see how many the shield had."] = "在消耗过的层数位置留下淡色圆环，让你始终看得清护盾原本有多少层。"
L["A flat element box at the start of each Compact line (ShamanPower Minimal)."] = "每条紧凑线条开头的扁平元素方块（ShamanPower Minimal）。"
L["A flyout on the Earth Shield button to choose its target. How flyouts open is on Totem Bar > Clicks."] = "大地之盾按钮上的弹出菜单，用于选择目标。弹出菜单的打开方式见“图腾条 > 点击方式”。"
L["A glow round the icon while it shows"] = "显示期间图标周围的光晕"
L["A grayed-out setting shows its tooltip anywhere over it, not only at its edge."] = "变灰的设置在其任意位置都会显示提示，而不仅限于边缘。"
L["A group for a zone (The Molten Core) or a kind of place (Any Raid, Any Dungeon, Any Battleground or Arena,"] = "为一个区域（熔火之心）或一类场所（任意团队、任意地下城、任意战场或竞技场、"
L["A group is for a raid or another place, like The Molten Core. Drag your MC loadouts onto its row: they show"] = "分组用于团队或其他场所，例如熔火之心。把 MC 的配装拖到该行上：它们会显示"
L["A heads-up to drop Tremor Totem the moment you target a mob that is known to fear - before anyone in your group gets feared."] = "当你选中已知会施放恐惧的怪物时，第一时间提醒你插下战栗图腾——在小队任何人被恐惧之前。"
L["A key you bound keeps casting after you turn its icon off: turn the shield off on the Cooldown Bar and its"] = "你绑定的按键在关闭其图标后仍会施放：在冷却条上关闭护盾，其"
L["A line in your own chat window. Only you see it."] = "在你自己的聊天窗口显示一行。只有你能看到。"
L["A line like Put Windfury back in the Expiring Alerts text,"] = "在“到期提醒”文字中显示类似“放回风怒”的一行，"
L["A line like Put Windfury back in the Expiring Alerts text, at its spot and size. No sound."] = "在“到期提醒”文字中的对应位置与字号显示一行“放回风怒”。无音效。"
L["A line like Searing Totem Destroyed! at the alerts' spot, with this element's sound. Off: nothing at all when one is destroyed."] = "在提醒位置显示一行“灼热图腾被摧毁！”之类的文字，并播放此元素的音效。关闭：被摧毁时完全不提示。"
L["A line like Searing Totem Expired when one runs out by itself. This may show frequent alerts."] = "图腾自行耗尽时显示一行“灼热图腾到期”。这可能会频繁提醒。"
L["A line on your screen when a shield or weapon imbue fades or a totem is destroyed. Right-click an alert for its settings."] = "护盾或武器附魔消失、图腾被摧毁时，在屏幕上显示一行提示。右键点击提醒可打开其设置。"
L["A list of the loadouts that show here, with their four totems: click one to switch to it, outside a fight."] = "此处显示的配装列表及其四个图腾：在非战斗时点击即可切换。"
L["A loadout tied to Blizzard's Call of the Ancestors set, with the four totems the set holds now, first in Everywhere."] = "与暴雪“先祖的召唤”套装绑定的配装，使用该套装当前的四个图腾，并优先出现在“所有地点”。"
L["A loadout tied to Blizzard's Call of the Spirits set, with the four totems the set holds now, first in Everywhere."] = "与暴雪“灵魂的召唤”套装绑定的配装，使用该套装当前的四个图腾，并优先出现在“所有地点”。"
L["A mob killed your Tremor Totem"] = "一只怪物摧毁了你的战栗图腾"
L["A new empty row under the others. Put spells on it in the Spells row above (click a spell on Not On A Row, or drag it); right-click the row's name for its spacing, direction and spot."] = "在其他行下方新增一个空行。在上方“法术”行中将法术放上去（点击“不在行中”的法术，或拖动它）；右键点击行名可设置其间距、方向和位置。"
L["A new empty row under the others. Put spells on it: drag them onto it, or pick it in a spell's On Row."] = "在其他行下方新增空行。把技能放上去：拖动技能，或在技能的“行”中选择它。"
L["A new look, if you want one"] = "全新外观，随心选用"
L["A new name for "] = "为 "
L["A panel of its own for the totems that reach the whole raid, apart from Party Coverage. In a raid, each raid-wide totem"] = "为覆盖全团范围的图腾单独设一个面板，独立于小队覆盖。在团队中，每个全团图腾"
L["A preset: applies exactly this look to everything on this tab. Your unsaved changes wait on the Custom card."] = "预设：将完全一样的外观应用到本标签页的所有内容。你未保存的修改会留在“自定义”卡片上。"
L["A profile holds every setting. Each character can use its own, or share one."] = "配置包含所有设置。每个角色可以使用自己的配置，也可以共用一个。"
L["A pulsing glow round the alert."] = "提醒周围脉动的发光。"
L["A quick look at what ShamanPower does for your class, then you are done."] = "快速了解 ShamanPower 为你的职业提供了什么，然后就完成了。"
L["A range ring round your "] = "围绕你的 "
L["A red X on the button until you put an imbue on again (5 seconds at most). Its own switch: with Weapon Imbue Gone off,"] = "按钮上显示红叉，直到你重新附魔（最多 5 秒）。独立开关：关闭“武器附魔消失”时，"
L["A red X on the button when a totem is destroyed, until you drop that element again (5 seconds at most). Its own switch:"] = "图腾被摧毁时按钮上显示红叉，直到你再次插下该元素（最多 5 秒）。独立开关："
L["A red X on the button when it's destroyed, until you drop that element again (5 seconds at most)."] = "图腾被摧毁时在按钮上显示红叉，直到你再次插下该元素（最多 5 秒）。"
L["A red X on the imbue button when the imbue drops off, until you put one on again (5 seconds at most). Its own switch:"] = "附魔消失时附魔按钮上显示红叉，直到你重新附上（最多 5 秒）。独立开关："
L["A row runs right; a column runs down."] = "行向右排列；列向下排列。"
L["A segmented line at the end of the bar showing your Earth Shield charges (one segment per charge). Click it to recast. This is the Earth Shield button in Compact style, so it is the same setting as Totem Bar > Items > Show Earth Shield."] = "图腾条末尾的分段线条，显示你的大地之盾层数（每层一段）。点击可重新施放。这就是紧凑样式下的大地之盾按钮，因此与“图腾条 > 物品 > 显示大地之盾”是同一项设置。"
L["A separate bar that tracks your big cooldowns so you never lose one in a crowded action bar."] = "单独的一条冷却条，追踪你的重要冷却，免得它们在拥挤的动作条里被忽略。"
L["A shield vanishes the moment it drops off, so you can see who needs one back."] = "护盾消失的瞬间即从显示中移除，让你看出谁需要补盾。"
L["A short animation on a cooldown bar button when something happens to it, so you notice it mid-fight."] = "冷却条按钮发生状况时会播放短暂动画，让你在战斗中也能察觉。"
L["A short animation on a totem button when something happens to its totem, so you notice it mid-fight."] = "图腾发生状况时，图腾按钮上会播放短暂动画，让你在战斗中也能察觉。"
L["A slot with no totem picked (WoW: Forever). ShamanPower Minimal shows a dark box with a dash."] = "未选择图腾的栏位（WoW: Forever）。ShamanPower Minimal 显示为带横线的深色方块。"
L["A small button at the corner of the "] = "位于"
L["A small list with icons. It goes away when the ready check ends or once you have fixed everything. Move it with Unlock UI."] = "带图标的小列表。就绪检查结束或你完成所有修正后消失。可用“解锁界面”移动。"
L["A small strip with one marker for each party member, for each totem buff you pick. It stays on"] = "为每个你选择的图腾增益显示一条小队条，每位队员一个标记。它会始终显示"
L["A spot you place"] = "你放置的位置"
L["A thin bar that drains as it runs."] = "一条随倒计时缩短的细条。"
L["A thin dark ring under each dot so it shows on bright icons like Windfury."] = "每个圆点下加一圈细暗色描边，使其在风怒这类亮色图标上也能看清。"
L["A totem killed before its time plays this, in red. Your own dismiss, Totemic Call and dying do not count."] = "图腾在时限前被击杀时播放此效果，以红色呈现。你自己取消、图腾召唤和死亡不计入。"
L["A totem that runs out plays this, in white."] = "图腾到期结束时播放此效果，以白色呈现。"
L["A totem you took out of its flyout (Totem Bar > Bar > Totems in the Flyouts) that has a key from Keybind Mode."] = "从弹出菜单中取出的图腾（图腾条 > 条 > 弹出菜单中的图腾），且已在按键绑定模式中设置了按键。"
L["A totem's cooldown number on its button (the same switch as Totem Bar > Duration Bars > Color the Cooldown Numbers)."] = "图腾按钮上的冷却数字（与 图腾条 > 持续时间条 > 为冷却数字着色 是同一开关）。"
L["A totem's cooldown number on its button changes color as the cooldown runs: the Cooldown Numbers colors on Appearance"] = "图腾按钮上的冷却数字随冷却推进而变色：即外观中的“冷却数字”颜色"
L["A totem's line shows only while you have that totem down, and goes when it is not. Off: the line"] = "仅当你插下该图腾时才显示其行，消失时隐藏。关闭：该行"
L["A totem's time left on its button (the same switch as Totem Bar > Duration Bars > Color the Time Left)."] = "图腾按钮上的剩余时间（与 图腾条 > 持续时间条 > 为剩余时间着色 是同一开关）。"
L["A totem's time left on its button changes color as it runs out: the Buff Timers colors on Appearance > Colors & Borders"] = "图腾按钮上的剩余时间随流逝而变色：即外观 > 颜色与边框中的“增益计时器”颜色"
L["A weapon imbue running out."] = "武器附魔即将结束。"
L["A weapon imbue that drops off (it ran out, or the weapon was swapped) plays this on the imbue button, in blue."] = "武器附魔消失（到期结束或更换武器）时，在附魔按钮上播放此效果，以蓝色呈现。"
L["A zone on the game's map. Click to use this name."] = "游戏地图上的区域。点击使用此名称。"
L["ALERT WHEN THESE FADE"] = "以下效果消退时提醒"
L["ALSO NEW IN "] = "同时新增于 "
L["ALT+Drag to move"] = "ALT+拖动以移动"
L["ALT+drag moves the loadout button while Lock Position is off. Move works either way."] = "关闭“锁定位置”时可用 ALT+拖动移动配装按钮。“移动”在任何情况下都有效。"
L["ALT+drag to move"] = "ALT+拖动可移动"
L["ALT+drag to move | Right-click for options"] = "ALT+拖动可移动 | 右键点击可打开选项"
L["AUTO_DROP_TOOLTIP"] = "自动插放已分配的图腾"
