L["Add a dark rim and soft highlight to party dots and Totem Coverage dots. Follows Dot Shape. Does not apply to Ring. Also on Party Buff Tracker."] = "为小队圆点与图腾覆盖圆点添加暗色边缘与柔和高光。跟随圆点形状。不适用于圆环。也应用于小队增益追踪。"
L["Add a name"] = "添加名字"
L["Add a shadow, raised edge or thick border to the Totem Bar, Cooldown Bar and ShamanPower's panels. The same setting as Frame Edge on Appearance > Themes."] = "为图腾条、冷却条和 ShamanPower 面板添加阴影、凸起边缘或粗边框。与外观 > 主题中的“框体边缘”为同一设置。"
L["Add a shadow, raised edge or thick border to the totem bar's and the cooldown bar's panels and to ShamanPower's other panels. The same setting as Frame Edge on Appearance > Themes and on the Cooldown Bar page."] = "为图腾条与冷却条的面板以及 ShamanPower 的其他面板添加阴影、凸起边缘或粗边框。与外观 > 主题页和冷却条页面中的“边框边缘”为同一设置。"
L["Add a theme someone shared with you (a code that starts with SPT1:)."] = "添加他人分享给你的主题（以 SPT1: 开头的代码）。"
L["Add or remove fear-casting mobs in Settings > Alerts & Reminders > Tremor Reminder"] = "在“设置 > 提醒与警告 > 战栗图腾提醒”中添加或移除施放恐惧的怪物"
L["Add or remove the enemies that trigger Tremor Reminder."] = "添加或移除会触发战栗图腾提醒的敌人。"
L["Add outline to text for better visibility"] = "为文字添加描边，提高可读性"
L["Add outline to the text for better visibility"] = "为文字添加描边，提高可读性"
L["Add target"] = "添加目标"
L["Adds an Empty choice to each totem flyout, as on Blizzard's totem bar. Pick it, in or out of combat, to leave that element with no totem: Call of the Elements and Drop All skip it, and the button casts nothing until you pick a totem again."] = "为每个图腾弹出菜单添加“空”选项，与暴雪图腾条相同。战斗内外均可选择，使该元素不插图腾：“元素的召唤”与“全部插放”会跳过它，在你重新选择图腾之前该按钮不会施放任何技能。"
