L["Always: every tracked totem shows, gray while no one has put it down and red while you are out of its range. Not While It's Missing: a totem no one has put down is hidden until someone does. Only While I'm in Range: a totem shows only while you have its buff."] = "始终：显示所有被追踪的图腾，无人插下时为灰色，当你不在其范围内时为红色。缺失时不显示：无人插下的图腾会被隐藏，直到有人插下。仅在我的范围内：只有当你拥有其增益时才显示该图腾。"
L["Always: it shows the whole time. While Totem Is Down: hidden while no one has it down. Only While I'm in Range: it shows only while you have its buff."] = "始终：全程显示。图腾插下期间：无人插下时隐藏。仅当我在范围内：仅当你拥有其增益时显示。"
L["Always: the icon stays put, dimmed with a countdown, and lights up when ready."] = "始终：图标常驻，变暗并带倒计时，就绪时亮起。"
L["An alert on your screen each time Windfury procs on you, from your weapon's Windfury Weapon or a Windfury Totem."] = "每次风怒在你身上触发时，屏幕上弹出提醒——来自武器的风怒武器附魔或风怒图腾。"
L["An alert pops up the moment someone in your group gets feared, poisoned or diseased, and disappears when it is cleared or the right totem is already down."] = "队伍中有人被恐惧、中毒或患病时，立即弹出提醒；解除后或正确图腾已插下时消失。"
L["An alert pops up the moment you get feared, or someone in your group gets poisoned or diseased, and disappears when it is cleared or the right totem is already down."] = "你被恐惧，或队伍中有人中毒或患病时，立即弹出提醒；解除后或正确图腾已插下时消失。"
