L["Any class can use |cffE6EAF0Totem Range Tracker|r to see whether they are in range of their shaman's totems. Keep it on to track other shamans' totems in your group."] = "任何职业都可以用 |cffE6EAF0图腾范围追踪|r 查看自己是否处于队伍萨满图腾的范围内。保持开启即可追踪队伍中其他萨满的图腾。"
L["Any shaman running ShamanPower, or the raid leader or an assistant, can tick this."] = "任何安装了 ShamanPower 的萨满，或团队领袖/助理，都可以勾选此项。"
