L["Automatic: shows while Blizzard's controller mode (Gamepad UI) is on. Always: shows whenever the Controller switch is on. It shows, hides, moves and changes size out of a fight only."] = "自动：仅当 Blizzard 手柄模式（Gamepad UI）开启时显示。始终：只要手柄开关开启就显示。其显示、隐藏、移动与缩放仅在非战斗时生效。"
