L["Choose how the lines look. Each uses its element's color. Flat is a solid color."] = "选择线条的外观。每种都使用所属元素的颜色。扁平为纯色。"
L["Choose how to display party member range information"] = "选择小队成员范围信息的显示方式"
L["Choose how visible the buttons are, then whether active buttons become fully visible."] = "选择按钮的可见程度，以及激活的按钮是否变为完全可见。"
L["Choose the Cooldown Bar effects' look. Standard: the original look. Elemental: a ring and glow in the element's color. Signal: a thin border and a bar along the bottom."] = "选择冷却条特效的外观。标准：原始外观。元素：以元素颜色呈现的环形与发光。信号：细边框和底部横条。"
L["Choose the Cooldown Bar's button order. Only spells available in this version of the game are listed. Hidden and unlearned spells keep their place for when you use them."] = "选择冷却条的按钮顺序。仅列出当前游戏版本可用的技能。隐藏和未学会的技能会保留其位置，以便你日后使用。"
L["Choose the Cooldown Bar's direction, separately from the Totem Bar."] = "单独于图腾条选择冷却条的朝向。"
L["Choose the Totem Bar effects' look. Standard: the original look. Elemental: a ring and glow in the element's color, with cracked stone for destroyed totems. Signal: a thin border and a bar along the bottom, with a red slash and corner flag for destroyed totems."] = "选择图腾条特效的外观。标准：原始外观。元素：以元素颜色呈现的环形与发光，图腾被摧毁时显示碎石。信号：细边框和底部横条，图腾被摧毁时显示红色斜线和角标。"
L["Choose the Totem Bar's direction."] = "选择图腾条的方向。"
L["Choose the bar's direction, overall size and the space between buttons."] = "选择条的方向、整体大小以及按钮之间的间距。"
L["Choose the colors of ShamanPower's bars, panels and effects. This changes how they look, not what they do."] = "选择 ShamanPower 的条、面板与特效颜色。这只会改变外观，不改变功能。"
L["Choose the element colors used across ShamanPower."] = "选择 ShamanPower 中使用的元素颜色。"
L["Choose the font for timers, charges, alerts, names and labels. Default keeps each part's usual font."] = "选择计时器、层数、提醒、名称和标签的字体。“默认”保持各部分原有的字体。"
L["Choose the look, animation and sound for each kind of alert."] = "为每种提醒选择外观、动画和音效。"
L["Choose the order of totem buttons on the mini totem bar."] = "选择迷你图腾条上图腾按钮的顺序。"
L["Choose the sound for when your shield drops. Shield Charges and Expiring Alerts share this setting."] = "选择护盾消失时播放的音效。“护盾层数”与“到期提醒”共用此设置。"
L["Choose the texture for the bars ShamanPower draws: totem duration bars, cooldown bar progress bars and pulse sweeps."] = "选择 ShamanPower 所绘制条形的材质：图腾持续时间条、冷却条进度条和脉动扫描。"
L["Choose this shield's texture separately from Bar Texture."] = "为此护盾单独选择材质，而不用“条材质”。"
L["Choose what to turn on or off in a place or against an enemy. For example, turn on Purge Reminder against Shazzrah in Molten Core. Example: in Molten Core, fighting"] = "选择在某处或针对某敌人开启或关闭哪些功能。例如，在熔火之心对阵沙斯拉尔时开启净化提醒。示例：在熔火之心，与"
