L["Choose when the totem bar hides or fades. Each bar has its own rules."] = "选择图腾条何时隐藏或淡出。每条都有各自的规则。"
L["Choose where the separate dropped-totem indicator appears. This also places the Earth Shield indicator when there is one."] = "选择单独的已插下图腾指示器的显示位置。若存在大地之盾指示器，也会一并放置。"
L["Choose whether the icon appears in combat, out of combat, or both. Show In can still keep it off in a kind of place."] = "选择图标在战斗中、战斗外还是两者都显示。“显示于”仍可让它在某类场所中保持关闭。"
L["Choose which buttons appear on the mini totem bar."] = "选择迷你图腾条上显示哪些按钮。"
L["Choose which displays follow Out Of The Way. Turn off a display here to keep using its own show and hide settings."] = "选择哪些显示器跟随“让路”。在此关闭某个显示器即可继续使用其自身的显示与隐藏设置。"
