L["During a Fight"] = "战斗中"
L["During a fight, WoW hides your Lightning Shield and Water Shield from addons, so ShamanPower can't tell when one falls off. WoW's own Cooldown Manager can still see them, so ShamanPower can watch them through it and warn you the moment your shield is gone, even mid-fight."] = "战斗中，WoW 会对插件隐藏你的闪电之盾和水之盾，因此 ShamanPower 无法判断它们何时消失。WoW 自带的冷却管理器仍能看到它们，所以 ShamanPower 可以借此监视，并在护盾消失的瞬间提醒你，即使在战斗中途。"
L["During a fight, WoW hides your Lightning Shield and Water Shield from addons. "] = "战斗中，WoW 会对插件隐藏你的闪电之盾和水之盾。 "
L["During a fight, WoW hides your Maelstrom Weapon stacks from addons, so ShamanPower can't tell when you reach 5 and play your sound. WoW's own Cooldown Manager can still see them, so ShamanPower can count them through it and play your sound at 5 stacks, even mid-fight."] = "战斗中 WoW 会对插件隐藏你的漩涡武器层数，ShamanPower 无法得知你何时叠到 5 层并播放音效。WoW 自带的冷却管理器仍能看到层数，因此 ShamanPower 通过它来计数，在 5 层时播放音效，战斗中同样有效。"
