L["Dynamic Mode is on: whatever you drop becomes the assigned totem,"] = "动态模式已开启：你插下的任何图腾都会成为已分配图腾，"
L["Dynamic Mode is on: whatever you drop becomes the assigned totem, so the dropped and assigned totems are never different and this display never appears."] = "动态模式已开启：你插下的任何图腾都会成为已分配图腾，因此已插下与已分配的图腾永远不会不同，此显示也永远不会出现。"
