L["EARTH_SHIELD_TOOLTIP"] = "点击选择大地之盾目标\\n右击清除"
L["ES Tracker"] = "大地之盾追踪"
L["Each alert can be dragged to its own spot later."] = "之后可将每个提醒拖到各自的位置。"
L["Each button shows a cooldown sweep, a colored progress bar and the time left."] = "每个按钮显示冷却扫过、彩色进度条和剩余时间。"
L["Each button shows the totem that is down. Clicking drops your assigned totem. The button shows your assigned totem again when the dropped one is gone. Great for PvP."] = "每个按钮显示当前插下的图腾。点击则插下你分配的图腾。插下的图腾消失后，按钮会重新显示你分配的图腾。非常适合 PvP。"
L["Each cooldown effect uses the look's own move. Turning it off puts your Effects styles back."] = "每个冷却效果使用该样式的专属动效。关闭后恢复你的效果样式。"
L["Each effect plays the look's own animation (Elemental: Crumble,"] = "每个效果播放该外观自带的动画（元素：碎裂、"
L["Each icon is running a pretend cooldown. In play they sit wherever you put them:"] = "每个图标都在演示一段模拟冷却。实际游戏中它们会待在你放置的位置："
L["Each makes a loadout tied to that Blizzard totem set, with the four totems the set holds now, first in"] = "每一项都会创建一个与该暴雪图腾组关联的配装，包含该组目前保存的四个图腾，并排在最前"
L["Each of your debuffs on your target, with the time it has left."] = "你目标身上的每个减益，以及其剩余时间。"
L["Each party member's name, in their class color, next to their marker (once, by the first totem)."] = "每位队员的名字以其职业颜色显示在标记旁（仅一次，位于第一个图腾处）。"
L["Each quick totem's key in its corner: the key you set on it in Keybind Mode, or its spell's key on your"] = "在每个快捷图腾的角落显示按键：你在按键模式里为它设的键，或该法术在你动作条上的键"
L["Each shield as it looks on your screen, with its own settings: it changes as you change them."] = "每个护盾在屏幕上的实际外观，并使用其自身设置：设置更改时外观随之变化。"
L["Each shield's charges back to their usual color."] = "各护盾的层数恢复为通常颜色。"
L["Each totem effect uses the look's own move. Turning it off puts your Effects styles back."] = "每个图腾效果使用该样式的专属动效。关闭后恢复你的效果样式。"
L["Each totem has party members' names underneath: class color when they have the buff, red when they don't."] = "每个图腾下方显示小队成员的名字：拥有增益时为职业色，没有时为红色。"
L["Each totem slot becomes an element-colored line. The totem's duration drains as an outline around the line (or the line itself drains), the pulse countdown refills inside it, and a tiny icon square can sit next to each line. Clicks, keybinds and flyouts work exactly as before. Cannot be combined with Dynamic Mode or TotemTimers Style: turning Compact on turns both of those off."] = "每个图腾槽位会变成一条元素色的线条。图腾的持续时间以外围边框消退的方式显示（或线条本身消退），脉冲倒计时在条内回充，每行旁边还可显示一个小图标方块。点击、按键绑定与弹出菜单的行为与之前完全相同。不能与动态模式或 TotemTimers 风格同时使用：开启紧凑样式会关闭这两者。"
L["Each totem's effects are in its own right-click menu: Totem Bar > Bar, the Totems row. When Destroyed (with the Red X),"] = "每个图腾的效果在其各自的右键菜单中：图腾条 > 条，图腾行。选择“被摧毁”时（连同红叉），"
L["Each tracker you pop out shows up here, with its settings in its menu."] = "你弹出的每个追踪器都会显示在此处，其设置位于其菜单中。"
