L["Every size above back to its usual size. Sizes picked in icons' own right-click menus stay."] = "以上所有大小恢复为原有尺寸。在图标右键菜单中选择的大小会保留。"
L["Every spell flashes on the shared spot again."] = "所有法术重新在共享位置闪烁。"
L["Every spell flashes on the shared spot. Right-click a spell above to give it a spot of its own."] = "所有法术都在共享位置闪烁。右键点击上方的法术可为其指定独立位置。"
L["Every spell is on a row."] = "所有技能都已在行中。"
L["Every totem has its own bubble, so someone can be inside Strength of Earth's range and outside Windfury's at the same time. A dot per member: class color = has that totem's buff, red = doesn't. The number = how many it reaches."] = "每个图腾都有各自的覆盖范围，所以某人可能同时处于大地之力图腾范围内、却在风怒图腾范围外。每个成员一个圆点：职业色 = 拥有该图腾的增益，红色 = 没有。数字 = 被覆盖的人数。"
L["Every totem of every element stays visible in rows. Click one to drop it; the assigned one is highlighted"] = "所有元素的所有图腾都按行常驻显示。点击其中一个即可插下；已分配的会高亮"
L["Every totem takes these settings of this one (they become the bar's own)."] = "每个图腾都采用这个图腾的这些设置（并成为图腾条自身的设置）。"
L["Every totem that can have a plate. Click one to show or hide its plate. Right-click it to mark it Important: its plate glows so it stands out in a fight."] = "所有可显示姓名板的图腾。点击可显示或隐藏其姓名板。右键点击可标记为重要：其姓名板会发光，便于在战斗中辨认。"
L["Every totem uses the list's Icon Size (Appearance) while Place Each Totem Freely is off. Turn it on"] = "“自由摆放每个图腾”关闭时，所有图腾都使用列表的“图标大小”（外观）。开启它"
L["Every totem you watch gets this size."] = "你监视的每个图腾都会使用此大小。"
L["Every watched totem gets its own spot and size (right-click a totem in Totems to Watch for its size)."] = "每个被监视的图腾都有自己的位置和大小（在“要监视的图腾”中右键点击图腾可设置大小）。"
L["Everyone covered: nothing to show."] = "所有人都已覆盖：无需显示。"
L["Everyone is covered."] = "所有人都已覆盖。"
L["Everything about how ShamanPower looks: themes, fonts, the bars, their flyouts, colors and visibility."] = "关于 ShamanPower 外观的一切：主题、字体、各条、飞出菜单、颜色与可见性。"
L["Everything else works as usual. Where a setting behaves differently on WoW: Forever, its page says so in an orange note."] = "其他一切照常。若某项设置在 WoW: Forever 上表现不同，其页面会用橙色提示说明。"
L["Everything you had is kept on the Custom card: click it to bring your whole look back. Your interface reloads to finish."] = "你原有的所有内容都会保留在“自定义”卡片上：点击它即可恢复你的整套外观。你的界面会重新加载以完成。"
