L["For Glowing and Flat Orbs. Charge Bar Color: the color the charge bar has (and a theme's Shield Colors). By Shield: Lightning, Water and Earth Shield each in their own color."] = "用于发光与扁平的宝珠。层数条颜色：层数条使用的颜色（以及主题的护盾颜色）。按护盾：闪电之盾、水之盾与大地之盾各用自己的颜色。"
L["For each totem you have down, show the names of party members missing its buff in red. Names stay accurate in combat and instances. The border and player count show estimated range, like the number counters."] = "对你已插下的每个图腾，以红色显示缺少其增益的小队成员名字。在战斗与副本中名字依然准确。边框与玩家计数显示估算范围，与数字计数器相同。"
