L["Free: each icon has its own spot, and a hidden icon leaves a gap. Grid: the icons form one block you move as a whole; the icons on screen fill it in the Spells row's order (drag a spell there to change it). Rows: you build each row yourself in the Spells row above, as many as you want, and move each row on its own."] = "自由：每个图标有独立位置，隐藏的图标会留出空隙。网格：图标组成一个整体，可整体移动；屏幕上的图标按“法术”行的顺序填充（在那里拖动法术即可改变顺序）。行：你在上方“法术”行中自行构建每一行，数量不限，并可单独移动每一行。"
