L["Give each totem you picked a strip of its own, instead of one line each in a single strip. Each"] = "为你选择的每个图腾各设一条，而不是在单一条中每图腾一行。每个"
L["Give each watched totem its own position and size. Use Move the Coverage List or ALT+drag to move them. Turn this off to group them in a row or column, with one icon for each element."] = "让每个被追踪的图腾拥有各自的位置与大小。使用“移动覆盖列表”或 ALT+拖动来移动它们。关闭此项可将它们按行或列编组，每种元素一个图标。"
L["Gives every button on the cooldown bar a border in the color of what it shows: shields in your Shield Colors,"] = "为冷却条上的每个按钮加上与其所示内容颜色一致的边框：护盾使用你的护盾颜色，"
L["Gives every button on the cooldown bar a border in the color of what it shows: shields in your Shield Colors, weapon imbues and element spells in their element color, other spells in the logo blue."] = "为冷却条上的每个按钮添加与其显示内容颜色一致的边框：护盾使用你的护盾颜色，武器附魔与元素法术使用各自的元素色，其他法术使用标志蓝。"
L["Gives every shield and weapon imbue in the cooldown bar's flyouts a border in the color of what it shows,"] = "为冷却条飞出菜单中的每个护盾与武器附魔加上与其所示内容颜色一致的边框，"
L["Gives every shield and weapon imbue in the cooldown bar's flyouts a border in the color of what it shows, like the cooldown bar's own buttons."] = "为冷却条弹出栏中的每个护盾和武器附魔添加与其显示内容颜色一致的边框，就像冷却条自身的按钮一样。"
L["Gives every totem in the totem bar's flyouts the same element-colored border as the bar's icons."] = "为图腾条弹出栏中的每个图腾添加与条上图标相同的元素色边框。"
L["Gives every totem in the totem bar's flyouts the same element-colored border."] = "为图腾条飞出菜单中的每个图腾加上相同的元素色边框。"
L["Glide between faded and full over a fifth of a second instead of switching at once. Out of combat only:"] = "在淡出与完全显示之间用五分之一秒平滑过渡，而不是瞬间切换。仅限战斗外："
L["Glide between faded and full over a fifth of a second instead of switching at once. Out of combat only: the bar is always at full the moment a fight starts."] = "在淡出与完全显示之间用五分之一秒平滑过渡，而不是瞬间切换。仅限战斗外：战斗开始的瞬间图腾条总是完全显示。"
