L["Grays Out: the icon starts in color and gray covers it as time runs out. Fills Back In: the icon starts gray and"] = "变灰：图标初始为彩色，随时间流逝逐渐被灰色覆盖。回填：图标初始为灰色，"
L["Grays Out: the icon starts in color and gray covers it as time runs out. Fills Back In: the icon starts gray and its color comes back as time runs out. Clock Sweep: the classic clock sweep (shields and cooldowns; weapon imbues keep Vertical - Grays Out)."] = "变灰：图标起初为彩色，随时间流逝灰色逐渐覆盖。回填：图标起初为灰色，随时间流逝颜色逐渐恢复。时钟扫过：经典的时钟式扫过（护盾与冷却；武器附魔保持“垂直 - 变灰”）。"
L["Green = you have that totem's buff. Red = the totem is down but you are out of its range. Gray = nobody has it down. Appears by itself whenever a shaman is in your group."] = "绿色 = 你拥有该图腾的增益。红色 = 图腾已插下但你不在其范围内。灰色 = 无人插下该图腾。你的队伍中有萨满时会自动出现。"
L["Green Earth and purple Air, from Blizzard's totem bar. The default on WoW: Forever."] = "绿色大地与紫色空气，取自暴雪图腾条。WoW: Forever 的默认主题。"
L["Green means you are getting that totem's buff, red means the totem is down but you are standing outside it - move closer to your shaman. It only appears when there is a shaman in your group."] = "绿色表示你正获得该图腾的增益，红色表示图腾已插下但你站在范围外——请靠近你的萨满。只有队伍中有萨满时才会出现。"
L["Green when full, yellow at half, red when low. Off: white."] = "满层为绿色，半数为黄色，接近耗尽为红色。关闭：白色。"
