L["Hide player names on the Earth Shield tracker"] = "在大地之盾追踪器上隐藏玩家名字"
L["Hide settings so you can set your keybinds. Hover a highlighted button and press a key. Done saves; Cancel restores your previous keys. Both return to settings. Also: /sp bind"] = "隐藏设置界面以便设置按键。将鼠标悬停在高亮的按钮上，按下想要的按键。点击“完成”保存；“取消”恢复之前的按键。两种方式都会返回设置界面。另见：/sp bind"
