L["Hide the panel behind the cooldown buttons, its background and its border, and show the icons alone."] = "隐藏冷却按钮后方的面板及其背景和边框，仅显示图标。"
L["Hide the panel behind the totem buttons, its background and its border, and show the icons alone."] = "隐藏图腾按钮后方的面板及其背景和边框，仅显示图标。"
