L["Hide the small totem icons and timers WoW shows under your player frame. Your totems stay on ShamanPower's bar. They come back when you turn this off, or when ShamanPower is switched off."] = "隐藏 WoW 在玩家框体下方显示的小图腾图标和计时器。你的图腾仍保留在 ShamanPower 的图腾条上。关闭此项或停用 ShamanPower 时会恢复显示。"
