L["Hide the totem name text (e.g. 'Tremor Totem')"] = "隐藏图腾名字文字（例如“战栗图腾”）"
L["Hide the tracker's border and title. ALT+drag to move it while they are hidden."] = "隐藏追踪器的边框与标题。隐藏时可 ALT+拖动来移动它。"
L["Hide this tracker's background and border; its icon stays. ALT+drag still moves it."] = "隐藏此追踪器的背景与边框；图标仍然保留。ALT+拖动仍可移动它。"
L["Hide totem names below the icons"] = "隐藏图标下方的图腾名字"
L["Hide when no shield is up"] = "无护盾时隐藏"
L["Hide when that totem is already down"] = "该图腾已插下时隐藏"
L["Hide while Tremor Totem is down"] = "战栗图腾插下时隐藏"
L["Hide: gone. Fade: dimmed to the Totem Bar Auto-Hide Faded Opacity above, still there."] = "隐藏：消失。淡出：降至上方“图腾条自动隐藏淡出透明度”，仍然可见。"
L["Hides this window and draws a box around the Loadout List on your screen. Drag it where you want it, then press Done to come back here."] = "隐藏此窗口，并在屏幕上的配装列表周围绘制方框。将其拖到所需位置，然后点击完成返回此处。"
L["Hides this window and draws a box around the Raid Coverage panel on your screen. Drag it where you want it, then press Done to come back here."] = "隐藏此窗口，并在屏幕上团队覆盖面板周围画一个框。将其拖到想要的位置，然后按“完成”返回此处。"
L["Hides this window and draws a box around the loadout bar on your screen. Drag it where you want it, then press Done to come back here."] = "隐藏此窗口，并在屏幕上的配装条周围画出边框。把它拖到想要的位置，然后按“完成”返回这里。"
L["Hides this window and draws a box round each shield's charges on your screen. Drag them where you want"] = "隐藏此窗口，并在屏幕上每个护盾的层数周围画一个框。将它们拖到想要的位置"
L["Highest"] = "最高"
L["Hold "] = "按住 "
L["Hold ALT and drag the loadout button to move the bar "] = "按住 ALT 拖动配装按钮即可移动该条 "
L["Hold For ShamanPower's Buttons"] = "按住以显示 ShamanPower 按钮"
L["Hold LB for ShamanPower's buttons: the d-pad drops your Earth (Up), Fire (Right), Water (Down) and Air (Left) totems,"] = "按住 LB 使用 ShamanPower 的按钮：方向键插下你的大地（上）、火焰（右）、水（下）与空气（左）图腾，"
L["Hold this button to use ShamanPower's controls below; let go and the pad is WoW's again. While the controller bar is on, this one button is ShamanPower's."] = "按住此键使用下方 ShamanPower 的控制；松开后手柄重归魔兽。手柄条开启期间，只有这一个键属于 ShamanPower。"
L["Horizontal (stacked)"] = "水平（堆叠）"
L["Horizontal Left | Down"] = "水平 左 | 向下"
L["Horizontal Left | Up"] = "水平 左 | 向上"
L["Horizontal Offset"] = "水平偏移"
L["Horizontal Right | Down"] = "水平 右 | 向下"
L["Horizontal Right | Up"] = "水平 右 | 向上"
L["Horizontal lines stack top to bottom; vertical lines sit side by side."] = "水平线条自上而下排列；垂直线条并排显示。"
L["Horizontal: each row runs from side to side. Vertical: each row runs from top to bottom."] = "水平：每行从一侧延伸到另一侧。垂直：每行从上到下排列。"
L["Horizontal: in a row. Vertical: in a column."] = "水平：排成一行。垂直：排成一列。"
L["Hover a button and press a key"] = "将鼠标悬停在按钮上并按下一个按键"
L["Hover a look to see it in the preview; click one to use it. Standard is how ShamanPower has always looked."] = "将鼠标悬停在一种外观上可在预览中查看；点击即可使用。“标准”是 ShamanPower 一贯的外观。"
L["Hover to pick another Call"] = "悬停以选择其他召唤"
L["Hovering any part of a settings button shows its tooltip, not only its border."] = "将鼠标悬停在设置按钮的任意部位都会显示提示，而不仅限于边框。"
L["Hovering the loadout button no longer opens the flyout of your other loadouts: clicking is the only way to switch."] = "悬停配装按钮不再弹出其他配装的菜单：只能通过点击切换。"
L["How Cooldown Ready, Weapon Imbue Gone and Shield Gone look: Standard, Elemental or Signal."] = "冷却就绪、武器附魔消失与护盾消失的显示方式：标准、元素或信号。"
L["How Flame Shock looks in its last seconds."] = "烈焰震击在最后几秒的外观。"
L["How Next Shock's Flame Shock looks when it's time to cast it: while your target doesn't have yours, and again just before yours runs out. Also in Flame Shock's right-click menu on Target Tracker, under Next Shock."] = "“下一个震击”中的烈焰震击在需要施放时的外观：目标身上没有你的烈焰震击时，以及你的即将消失前。也位于“目标追踪”中烈焰震击右键菜单的“下一个震击”下。"
L["How Totem Destroyed, Totem Expired and Totem Expiring Soon look: Standard, Elemental or Signal."] = "图腾被摧毁、图腾已失效与图腾即将失效的显示方式：标准、元素或信号。"
L["How a totem's spell cooldown is drawn. Grays Out: the icon starts in color and gray covers it as time runs out. Fills Back In: the icon starts gray and its color comes back as time runs out. Clock Sweep: the classic clock sweep."] = "图腾技能冷却的绘制方式。逐渐变灰：图标起初为彩色，随冷却推进被灰色覆盖。逐渐恢复：图标起初为灰色，随冷却推进恢复彩色。时钟扫描：经典的时钟扫描。"
L["How alerts animate on screen"] = "提醒在屏幕上的动画方式"
L["How big the buff is, as a percentage of this icon's size."] = "增益的大小，为此图标尺寸的百分比。"
L["How big the buff's icon is, as a percentage of this icon's size."] = "增益图标的大小，为此图标尺寸的百分比。"
L["How big the buff's time left is. Auto sizes it to the buff's look."] = "增益剩余时间的大小。“自动”会随增益外观调整。"
L["How big the controller bar is. Your keyboard totem bar keeps its own size."] = "手柄条的大小。你的键盘图腾条保持自身大小。"
L["How big the icons in "] = "设置 "
L["How big the icons in the flyout are. 22 is the classic size. The Cooldown Bar's scale still applies on top."] = "飞出菜单中图标的大小。22 为经典尺寸。冷却条的缩放仍会叠加生效。"
L["How big the icons in the shield and weapon imbue flyouts are. 22 is the classic size. The cooldown bar's scale still applies on top."] = "护盾与武器附魔弹出栏中图标的大小。22 为经典尺寸。冷却条的缩放仍会叠加生效。"
L["How big the icons in the totem flyouts are while Compact style is on. The default is 15, the same as the icon squares, so a flyout sits neatly beside the lines instead of spilling over its neighbors (the icon bar uses 28, and keeps its own size in Appearance). The totem bar's scale still applies on top."] = "紧凑样式开启时图腾弹出栏中图标的大小。默认值为 15，与图标方格相同，因此弹出栏会整齐地贴在行旁，而不会溢出到相邻行（图标条使用 28，并在外观中保留各自的大小）。图腾条的缩放仍会叠加生效。"
L["How big the icons in the totem flyouts are while the totem bar shows icons. 28 is the classic size."] = "当图腾条显示图标时，图腾弹出栏中图标的大小。28 为经典尺寸。"
L["How big the strip is."] = "条带的大小。"
L["How big the strips are. This sets every strip; in Unlock UI the mouse wheel over a strip"] = "条带的大小。此设置作用于所有条带；在“解锁界面”中，将鼠标滚轮移到条带上"
L["How big the totem bar is. The same as Scale on Appearance > Totem Bar."] = "图腾条的大小。与外观 > 图腾条中的“缩放”相同。"
L["How big the totems in the rows are. 100% is the size of the totems in the flyouts."] = "行中图腾的大小。100% 为弹出菜单中图腾的大小。"
L["How big this alert is. In Unlock UI, the mouse wheel over its box does the same."] = "此提醒的大小。在解锁界面中，在它的框体上滚动滚轮效果相同。"
L["How big this tracker is."] = "此追踪器的大小。"
L["How big your cooldowns are in their own frame. The controller bar and your cooldown bar keep their own sizes."] = "冷却在独立框架中的大小。手柄条与冷却条保持各自的大小。"
L["How bright the flash around the button is each time a totem like Healing Stream or Tremor pulses. 0% turns the flash off."] = "治疗之泉或战栗等图腾每次脉动时按钮周围闪光的亮度。0% 关闭闪光。"
L["How each flat box shows which totem it is. Each part below can pick its own."] = "每个扁平方块如何表示对应的图腾。以下各部分可各自选择。"
L["How each flat box shows which totem it is. The full name is always in the tooltip."] = "每个扁平方块如何表示对应的图腾。完整名称始终显示在提示中。"
L["How each totem shows its remaining time, cooldown and pulse timer."] = "每个图腾如何显示剩余时间、冷却与脉冲计时。"
L["How faint an element with no totem down is."] = "无图腾插下的元素有多淡。"
L["How far apart alerts stack when more than one shows at once, from one alert's middle to the next."] = "同时显示多个提醒时它们的堆叠间距，从一个提醒的中部到下一个。"
L["How it looks on your screen with its settings now. A click plays its charges being used, then fills it again."] = "它按当前设置在屏幕上的外观。点击可播放其层数消耗过程，然后重新充满。"
L["How its button looks while you're out of its range: gray as it always was, a glow, both, or nothing."] = "你不在其范围内时按钮的外观：一如既往的灰色、发光、两者兼有，或什么都不做。"
L["How long after a press the button (and the SP_DropAll macro) waits before the sequence starts over at its"] = "按下后，按钮（以及 SP_DropAll 宏）等待多久才让序列从其"
L["How long alerts stay on screen (seconds)"] = "提醒在屏幕上停留的时间（秒）"
L["How long it stays up after each proc. A proc while it shows keeps it up this long from that proc."] = "每次触发后停留多久。显示期间再次触发，会从那次触发重新计时。"
L["How long the burst or the word stays before the ready look takes over."] = "迸发或文字在就绪外观接管前的停留时间。"
L["How loud Lightning Shield and Water Shield's Sound When Shield Ends plays. Earth Shield's plays at"] = "闪电之盾和水之盾的“护盾结束音效”的音量。大地之盾的音量为"
L["How loud every alert's sound is: the totems', the weapon imbues'"] = "所有提醒音效的音量：图腾的、武器附魔的"
L["How loud this alert's sound is. Your game's Dialog volume must be at 100% for this to work."] = "此提醒音效的音量。需将游戏的“对话”音量调到 100% 才生效。"
L["How many Ankhs are in your bags, on the icon."] = "在图标上显示背包中十字章的数量。"
L["How many icons fit in a row before the next row starts. 1 makes a column."] = "一行能容纳多少个图标后开始下一行。设为 1 即为单列。"
L["How many seconds of Windfury buff are left when the sound plays"] = "播放音效时风怒增益剩余多少秒"
L["How much of the color is left at the faded end of the border: 0% fades right into the game world."] = "边框淡出端保留多少颜色：0% 则完全融入游戏世界。"
L["How much of the color is left at the faded end: 0% fades right into the game world."] = "淡出端保留多少颜色：0% 会完全融入游戏画面。"
L["How see-through "] = "设置 "
L["How see-through the flyout is."] = "飞出菜单的透明程度。"
L["How see-through the list's background is. Its border, text and icons always stay solid."] = "列表背景的透明程度。其边框、文字与图标始终保持不透明。"
L["How see-through this alert is. In Unlock UI: Ctrl + mouse wheel over its box."] = "此提醒的透明程度。在解锁界面中：在它的框体上 Ctrl + 滚轮。"
L["How see-through this color is."] = "此颜色的透明程度。"
L["How see-through this shield's charges are."] = "此护盾层数的透明程度。"
L["How see-through this tracker is."] = "此追踪器的透明程度。"
L["How solid or see-through it looks."] = "外观的实心或不透明程度。"
L["How solid the panels of the options and assignment windows are. Text, icons and borders always stay fully visible."] = "设置窗口与分配窗口面板的不透明程度。文字、图标和边框始终保持完全可见。"
L["How solid the range rings are."] = "范围环的不透明程度。"
L["How solid the strip's background is. The markers and names always stay fully visible."] = "条背景的不透明程度。标记和名称始终保持完全可见。"
L["How solid the totem markers are. Lower: you see what is under them (a herb, an ore)."] = "图腾标记的不透明程度。调低可看清其下方的内容（草药、矿石）。"
L["How tall the bar is. Auto: a third of Size. Size (Appearance) sets how wide it is."] = "条的高度。自动：大小的三分之一。宽度由“外观”中的大小决定。"
L["How the gray warning looks while your "] = "当你的 "
L["How the gray warning looks while your shock isn't on your target: Flame Shock, Frost Shock and Stormstrike. Also on Target Tracker (right-click a spell > Look)."] = "当你的震击不在目标身上时，灰色警示的显示效果：烈焰震击、冰霜震击与风暴打击。也应用于“目标追踪”（右键点击技能 > 外观）。"
L["How the icon counts down. Clock Sweep: the clock sweep. Grays Out: gray covers the icon as the time runs"] = "图标如何倒计时。“表盘扫过”：表盘扫过。“变灰”：灰色随时间流逝覆盖图标，直到时间"
L["How the icon looks while no one has the totem down. Gray is the overlay's look as it always was."] = "无人插下图腾时图标的外观。“灰色”为覆盖层一贯的外观。"
L["How the icon looks while the totem is down but you're out of its range. Red is the overlay's look as it always was."] = "图腾已插下但你不在其范围内时图标的外观。“红色”为覆盖层一贯的外观。"
L["How thick the Proc Glow ring is. It grows outward from the icon's edge."] = "触发发光圆环的粗细。它从图标边缘向外扩展。"
L["How thick the Proc Glow ring is: it grows outward from the icon's edge. 20% by default. Also on Totem Bar > Duration Bars; each Ready Reminders icon has its own."] = "触发光晕环的粗细：从图标边缘向外扩展。默认 20%。也应用于“图腾条 > 持续时间条”；每个就绪提醒图标可单独设置。"
L["How thick the Proc Glow ring is: it grows outward from the icon's edge. 20% by default. The same setting as on Appearance > Themes; each Ready Reminders icon has its own."] = "触发发光环的粗细：它从图标边缘向外扩展。默认为 20%。与外观 > 主题中的设置为同一项；每个就绪提醒图标都有各自的设置。"
L["How thick the element-colored border is on "] = "元素色边框的粗细（作用于 "
L["How thick the icon's border is. 0 is no border. Its color follows the theme's enemy and friendly colors."] = "图标边框的粗细。0 表示无边框。其颜色跟随主题的敌方与友方颜色。"
L["How this shield's charges look: the bar, or one orb per charge (Glowing, Shield Icon, Flat or one of the Storm looks). Works in combat. The same setting as on Appearance > Themes."] = "护盾层数的显示方式：条状，或每层一个光球（发光、护盾图标、扁平或风暴外观）。战斗中同样有效。与“外观 > 主题”中的设置相同。"
L["How to Show It"] = "显示方式"
L["How to display alerts"] = "如何显示提醒"
L["How to display the reminder"] = "提醒的显示方式"
L["How visible the Blizzard flyout's border and background are. Lower makes them more see-through."] = "暴雪弹出菜单边框与背景的可见程度。数值越低越透明。"
L["How visible the cooldown bar stays while faded."] = "淡出时冷却条的可见程度。"
L["How visible the duration bars and their dark track are."] = "持续时间条及其深色底槽的可见程度。"
L["How visible the icon stays out of combat. 100% is how it looks in a fight."] = "战斗外图标保留的可见度。100% 即战斗中的外观。"
L["How visible the separate counters are."] = "独立计数器的可见程度。"
L["How visible the totem bar stays while faded."] = "淡出时图腾条的可见程度。"
L["How your stacks show: a number on the icon, a Charge Bar like Shield Charges, Blizzard's wings building up, the emblem or the icon filling a fifth per stack, or the icon's glow growing."] = "层数的显示方式：图标上的数字、类似护盾层数的层数条、暴雪翅膀逐渐充盈、徽记或图标每层填充五分之一，或图标光晕逐渐增强。"
