L["Off to start. On: the settings window drops in and flies away, Unlock UI's boxes rise into place, and Tuck Away glides. Off: they open, close and move at once. Ready Reminders, Totem Bar effects and alerts keep their own animations either way."] = "默认关闭。开启：设置窗口会落下并飞走，“解锁界面”的边框会升起就位，“收起”会滑动。关闭：它们会立即打开、关闭和移动。就绪提醒、图腾条特效与提醒无论如何都保留各自的动画。"
L["Off your screen: it is on no row. Click to put it on the last row, or drag it onto one."] = "已移出屏幕：它不在任何行上。点击可放到最后一行，或把它拖到某行。"
