L["Off: no caller buttons, no alert when someone calls for a cooldown, and no calls sent from you. What the raid lead assigned is kept for when you turn it back on."] = "关闭：不显示召唤按钮，有人召唤冷却时不会提醒，也不会由你发送召唤。团队领袖分配的设置会保留，待你重新开启时使用。"
L["Off: only this group's loadouts show in the flyout there."] = "关闭：该处的飞出菜单只显示此分组的配装。"
L["Off: the shield and weapon imbue buttons work the way your totem bar style does (Totem Bar Style on General > Main). On: they use the style you pick below, whatever the totem bar uses."] = "关闭：护盾与武器附魔按钮的行为与你的图腾条样式一致（“通用 > 主要”中的图腾条样式）。开启：无论图腾条使用什么样式，它们都使用你在下方选择的样式。"
