L["On: every element's totems also sit in a row of their own, which you can put anywhere"] = "开启：每个元素的图腾也会各自成行，可放置在任意位置"
L["On: holding ALT and dragging the list does not move it. Move the Loadout List still does."] = "开启：按住 ALT 拖动列表不会移动它。“移动配装列表”仍可移动。"
L["On: it starts in the Charge Color and shades into the second color. Off: it starts in a first color you pick."] = "开启：以层数颜色开始，并过渡到第二种颜色。关闭：以你选择的第一种颜色开始。"
L["On: your main totem bar shows as well as the rows. Off: only the rows show, and the bar's"] = "开启：除各行外还显示主图腾条。关闭：只显示各行，图腾条的"
L["On: your main totem bar still opens its flyouts, as well as showing the rows. Off: the rows"] = "开启：主图腾条仍会打开其弹出菜单，同时显示各行。关闭：各行"
L["Once everyone is in range of a totem, it drops out of the list (you can turn that off). Pick which totems it watches in Settings."] = "一旦所有人都在某图腾的范围内，它就会从列表中移出（可关闭此行为）。在设置中选择它监视哪些图腾。"
