L["Only When Missing: Shield shows while neither Lightning Shield nor Water Shield is on you and hides while one is."] = "仅缺失时：既没有闪电之盾也没有水之护盾时显示护盾，有其中之一时隐藏。"
L["Only When Ready"] = "仅在就绪时"
L["Only When Ready: the icon comes up when the spell is ready and goes while it cools. Only While On Cooldown: the other way round. While Ready And On Cooldown: always there, with the cooldown sweep and countdown over it; Dimmed: faded while it cools (While On Cooldown sets how)."] = "仅在就绪时：技能就绪时出现，冷却时消失。“仅在冷却中”：正好相反。“就绪及冷却中”：始终显示，并叠加冷却扫描与倒计时；“变暗”：冷却时淡化（由“冷却中”设定方式）。"
L["Only When Running Out"] = "仅在即将结束时"
L["Only When Running Out: out of sight until it is running out, then up with its time left. Gone: up until you cast"] = "仅在即将结束时：在此之前隐藏，进入即将结束后显示并带剩余时间。“消失”：一直显示，直到你施放"
L["Only While I'm in Range"] = "仅当我在范围内"
L["Only While On Cooldown"] = "仅在冷却中"
L["Only While The Totem Is Down"] = "仅在图腾存在时"
L["Only alert inside instances"] = "仅在副本内提醒"
L["Only available to shamans."] = "仅萨满可用。"
L["Only in Arenas and Battlegrounds"] = "仅在竞技场和战场"
L["Only in combat"] = "仅在战斗中"
L["Only matters if you are melee (warrior, rogue, paladin). Casters can skip this step."] = "仅与你是否是近战（战士、盗贼、圣骑士）有关。法系职业可以跳过此步。"
L["Only shamans running ShamanPower, or the raid leader or an assistant, can request resistances"] = "只有安装了 ShamanPower 的萨满，或团队领袖/助理才能请求抗性"
L["Only show reactive totem alerts inside dungeons, raids, and battlegrounds"] = "仅在地下城、团队和战场内显示应急图腾提醒"
L["Only show who's missing the buff"] = "只显示缺少增益的人"
L["Only the Charge Bar and the Storm Glow color the stacks below 5. The other looks show the spell's own picture."] = "只有“层数条”和“风暴光晕”会为 5 层以下的层数着色。其他外观显示技能自身的图片。"
L["Only the totems you have down, nothing else, centered as a group: a totem appears the moment it lands and goes the moment it ends, with its bar, time and pulse. No flyouts, no clicks; your keybinds still cast."] = "只显示你已插下的图腾，别无其他，作为一组居中排列：图腾落地的瞬间出现，结束的瞬间消失，并带有进度条、时间和脉冲。没有弹出菜单，也不能点击；你的按键仍可施放。"
L["Only these players show in the flyout: a player shows if any picked role or class matches them. Nothing picked: everyone."] = "弹出菜单中只显示这些玩家：只要符合任一已选职责或职业即会显示。未选择任何项：显示所有人。"
L["Only when ready"] = "仅在就绪时"
L["Only when ready: the icon shows up when you can press the spell and vanishes while it recharges."] = "仅在就绪时：技能可施放时图标出现，充能期间消失。"
L["Only while YOU are feared, charmed or asleep: in a fight the game hides what"] = "仅当你自己被恐惧、魅惑或睡眠时：战斗中游戏会隐藏"
L["Only while on cooldown"] = "仅在冷却时"
L["Only while on cooldown: the icon shows with a countdown while the spell recharges and vanishes when ready."] = "仅在冷却时：技能充能期间图标显示并带倒计时，就绪后消失。"
L["Only you see it."] = "只有你能看到。"
L["Only your raid leader or an assistant can change these"] = "只有团队领袖或助理才能更改这些"
L["Opacity"] = "不透明度"
L["Opacity includes both bars, their flyouts and the settings that make active buttons fully visible."] = "透明度包含两条、其弹出菜单以及使激活按钮完全可见的设置。"
L["Opacity of alerts"] = "提醒的透明度"
L["Opacity of the reminder icon"] = "提醒图标的透明度"
L["Opacity of the totem plate icons"] = "图腾姓名板图标的透明度"
L["Open "] = "打开 "
L["Open Fear-Caster Mob List"] = "打开恐惧施放者列表"
L["Open Flyouts Only From the Arrow or a Keybind"] = "仅通过箭头或按键打开弹出菜单"
L["Open Keybind Mode..."] = "打开按键绑定模式..."
L["Open Settings"] = "打开设置"
L["Open ShamanPower Settings"] = "打开 ShamanPower 设置"
L["Open Totem Assignments"] = "打开图腾分配"
L["Open Totem Bar > Bar"] = "打开 图腾条 > 条形"
L["Open Totem Coverage Settings"] = "打开图腾覆盖设置"
L["Open Totem Picker"] = "打开图腾选择器"
L["Open Tracker Settings"] = "打开追踪设置"
L["Open Unlock UI to move this spell's Ready Flash."] = "打开解锁界面以移动此技能的就绪闪烁。"
L["Open World"] = "开放世界"
L["Open flyouts with their arrows or keybinds, in or out of combat. They stay open until you pick from them or press the arrow or key again. Hovering does not open them. The arrows are always shown."] = "通过箭头或按键打开弹出菜单，战斗内外均可。菜单会保持打开，直到你选择其中一项或再次按下箭头或按键。悬停不会打开它们。箭头始终显示。"
L["Open the full settings window after the reload"] = "重新加载后打开完整设置窗口"
L["Open the guided setup again."] = "再次打开向导式设置。"
L["Open world only: in dungeons and raids WoW hides where you are, so there are no markers there."] = "仅限户外世界：在地下城和团队中 WoW 会隐藏你的位置，因此那里不会显示标记。"
L["Opens Keybind Mode: press the key you want on it."] = "打开按键绑定模式：按下你想绑定的按键。"
L["Opens Keybind Mode: press the key you want on the button, or on its flyout."] = "进入按键绑定模式：为按钮或其飞出菜单按下想要的按键。"
L["Opens Keybind Mode: press the key you want on this alert's totem."] = "打开按键绑定模式：按下你想用于此提醒图腾的按键。"
L["Opens Settings > Appearance > Themes. Nothing changes until you pick a theme there."] = "打开“设置 > 外观 > 主题”。在你于那里选择主题之前不会发生任何变化。"
L["Opens Settings > Appearance > Themes. Nothing changes until you pick something there."] = "打开“设置 > 外观 > 主题”。在你于那里选择之前不会发生任何变化。"
L["Opens ShamanPower's settings on the page you used last. Unlock UI comes back when"] = "打开 ShamanPower 设置，并停留在你上次使用的页面。关闭设置后"
L["Opens Unlock UI with just this buff's box. Drag it where you want it, then press Done."] = "仅以该增益的框打开解锁界面。把它拖到想要的位置，然后按“完成”。"
L["Opens a small box with the link selected: press Ctrl+C to copy it."] = "打开一个已选中链接的小框：按 Ctrl+C 复制。"
L["Opens the same settings panel as the tracker's cog (or SHIFT+middle-click on it)."] = "打开与追踪器齿轮相同的设置面板（或对其 SHIFT+中键点击）。"
L["Opens the setup tour again. It changes nothing until you pick something in it."] = "再次打开设置向导。在你于其中做出选择之前，不会更改任何内容。"
L["Opens the wago.io link for the companion aura."] = "打开该配套光环的 wago.io 链接。"
L["Optional sound when it is time to re-drop Windfury. On by default for Enhancement."] = "该重新插下风怒时可选的音效。增强默认开启。"
L["Options"] = "选项"
L["Options > Key Bindings > ShamanPower"] = "选项 > 按键绑定 > ShamanPower"
L["Or a number: how many of them the totem reaches. Or both."] = "或者一个数字：图腾覆盖了多少人。也可两者兼用。"
L["Orb Color"] = "宝珠颜色"
L["Original Colors"] = "原始颜色"
L["Original color."] = "原始颜色。"
L["Other Spells"] = "其他技能"
L["Other pages are still available."] = "其他页面仍可访问。"
L["Out Of The Way"] = "避让"
L["Out of Mana Color"] = "法力不足颜色"
L["Out of Range"] = "超出范围"
L["Out of Range Color"] = "超出范围颜色"
L["Out of a fight the icon shows with no glow; the glow comes in a fight."] = "战斗外图标不发光；进入战斗后才会发光。"
L["Out of a fight, not inside a dungeon, raid or battleground, and with no enemy targeted (red or yellow: anything you can attack), ShamanPower's displays get out of the way: in a city or an inn, or anywhere (Where, below). Any one of those brings them back at once."] = "不在战斗中、不在地下城、团队或战场内，且没有选中敌人（红色或黄色：任何你可攻击的目标）时，ShamanPower 的显示会自动避让：在城市或旅店中，或在任何地方（下方“何处”）。其中任一条件结束都会立即恢复显示。"
L["Out of combat, bring the cooldown bar back while you target something you can attack, even with Hide Out of Combat on."] = "战斗外，当你选中可攻击的目标时重新显示冷却条，即使已开启“战斗外隐藏”。"
L["Out of combat, bring the totem bar back while you target something you can attack, even when a hide option above applies."] = "战斗外，当你选中可攻击的目标时重新显示图腾条，即使上述某个隐藏选项已生效。"
L["Out of combat, this icon fades to the opacity below instead of hiding, so you can still see which spells are ready. In a fight it's back to full."] = "战斗外此图标会淡至下方的不透明度而非隐藏，让你仍能看到哪些技能已就绪。战斗中恢复为完全不透明。"
L["Out of sight until its last seconds (Almost Ready At). Then Hide Again: gone again once it is ready."] = "在最后几秒（“即将就绪于”）前隐藏。之后“再次隐藏”：就绪后再次消失。"
L["Outline"] = "描边"
L["Outline Color"] = "外框颜色"
L["Outline Gradient"] = "外框渐变"
L["Outline Width"] = "外框宽度"
L["Outline Without a Totem"] = "无图腾时的外框"
L["Outline color"] = "外框颜色"
L["Outline draining around the line"] = "线条周围的外框逐渐消退"
L["Outline the dots"] = "为圆点描边"
L["Outline width"] = "外框宽度"
L["Outlined text"] = "描边文字"
L["Outlines each totem on the totem bar in its element color from the colors above,"] = "用上方颜色为图腾条上的每个图腾描上其元素色边框，"
L["Outlines each totem on the totem bar in its element color. Not shown with the Compact, Grid or Blizzard's Totem Bar styles."] = "用元素色勾勒图腾条上的每个图腾。在紧凑、网格或 Blizzard 图腾条样式中不显示。"
L["Over a cooldown's last seconds, its button plays the style below in gold, until it is ready."] = "在冷却的最后几秒，其按钮会以金色播放下方样式，直到就绪。"
L["Over a totem's last seconds its button pulses darker, or its edges glow orange, until it runs out or you drop it again."] = "在图腾最后的几秒内，其按钮会变暗脉动，或边缘发出橙光，直到它到期或你重新插放。"
L["Over a totem's last seconds its button pulses darker, or its edges glow orange."] = "图腾最后几秒，其按钮会变暗脉冲，或边缘发出橙色光。"
L["Over its last moments (Running Out At), the button plays this until you cast it again."] = "在其最后时段（“即将结束阈值”），按钮会播放此特效，直到你再次施放。"
L["Over its last seconds (Running Out At), or on its last 2 charges, the Earth Shield button plays this until you"] = "在最后几秒（“即将结束阈值”）或剩最后 2 层时，大地之盾按钮会持续播放此效果，直到你"
L["Over the cooldown's last seconds (Almost Ready At), the button plays this in gold."] = "在冷却的最后几秒（“即将就绪于”），按钮以金色播放此效果。"
L["Over the last moments of your shield or weapon imbue"] = "在你的护盾或武器附魔最后的时刻"
L["Over this totem's last seconds its button plays the style below, until it runs out or you drop it again."] = "在此图腾的最后几秒，其按钮会播放下方样式，直到它结束或你再次插下。"
L["Overlay"] = "覆盖层"
L["Overlay Opacity"] = "遮罩透明度"
L["Own Icon"] = "独立图标"
L["Own Spot"] = "独立位置"
L["Page Down"] = "向下翻页"
L["Page Up"] = "向上翻页"
L["Pages lit by each group's element, the logo and new fonts. Preview and Reset This Page on every page. A module's page grays out with a Turn On button while the module is off. Menus and tooltips got the same look. The settings window can also drop in and fly away, and Unlock UI's boxes rise into place: that's off to start, so turn on UI Animations at the top of the settings sidebar if you'd like it."] = "各页面按所属分组的元素着色，还有新标志与新字体。每个页面都有“预览”和“重置此页”。模块关闭时，其页面会变灰并显示“开启”按钮。菜单和提示框也换上了同样的外观。设置窗口还能落下与飞出，解锁界面中的框会升起就位：该效果默认关闭，如需启用，请在设置侧栏顶部打开“界面动画”。"
L["Paladin"] = "圣骑士"
L["Panel"] = "面板"
L["Panel Edge Style"] = "面板边缘样式"
L["Panel Edge Style changes both bars' panels and ShamanPower's other panels. Keep Icon Borders Square also changes Ready Reminders."] = "面板边缘样式会改变两条及 ShamanPower 其他面板的样式。“保持图标边框为方形”也会改变就绪提醒。"
L["Panel and Count"] = "面板与计数"
L["Panels and Center Alert"] = "面板与中央提醒"
L["Partially Buffed"] = "部分增益"
L["Party"] = "小队"
L["Party Buff Tracker"] = "小队增益追踪"
L["Party Buff Tracker is about YOUR totems. Totem Range Tracker (later) is about other shamans' totems reaching you."] = "小队增益追踪关注的是你的图腾。图腾范围追踪（稍后）关注的是其他萨满的图腾是否覆盖到你。"
L["Party Coverage"] = "小队覆盖"
L["Party Dots: Class Colors"] = "小队圆点：职业颜色"
L["Party Dots: Missing Buff"] = "小队圆点：缺少增益"
L["Party Drummer"] = "小队鼓手"
L["Party Frames"] = "小队框体"
L["Party Range Counter"] = "小队范围计数"
L["Party Strip"] = "小队条"
L["Party Strip Background"] = "小队条背景"
L["Party Strip Element Line"] = "小队条元素线"
L["Party Strip Icon"] = "小队条图标"
L["Party Strip Markers"] = "小队条标记"
L["Party Strip: "] = "小队条： "
L["Party Strip: Class Colors"] = "小队条：职业颜色"
L["Party buff dots and range counters"] = "小队增益圆点与范围计数"
L["Party names, range counters, Totem Range, Coverage, Totem Plates and other small labels."] = "小队名称、范围计数、图腾范围、覆盖、图腾姓名板及其他小标签。"
L["Paste Settings"] = "粘贴设置"
L["Paste Settings  (from "] = "粘贴设置（来自 "
L["Paste a ShamanPower code to create a new profile."] = "粘贴 ShamanPower 代码以创建新配置。"
L["Paste a ShamanPower code, name the new profile, then click Import."] = "粘贴 ShamanPower 代码，为新配置命名，然后点击“导入”。"
L["Paste a theme code (it starts with SPT1:). The theme is added to Your Themes; click it to use it."] = "粘贴主题代码（以 SPT1: 开头）。该主题会添加到“你的主题”，点击即可使用。"
L["Patch Notes"] = "更新说明"
L["People"] = "玩家"
L["Pick Another Icon..."] = "选择其他图标..."
L["Pick a color for each element's range ring on the minimap. Off: each ring takes its element's color (a theme's palette if one is on)."] = "为小地图上每个元素的范围环选择颜色。关闭：每个环使用其元素的颜色（若启用主题则使用主题配色）。"
L["Pick a profile for each spec. When you change spec, ShamanPower switches to that spec's profile. Your spec is read from your talents, the same way Ready Reminders' Show For reads it. Saved for this character."] = "为每个专精指定一套配置。切换专精时，ShamanPower 会自动切到该专精的配置。专精依据你的天赋判定，与就绪提醒的「显示于」判定方式相同。按角色保存。"
L["Pick a profile, then press Copy Settings to This Profile."] = "选择一个配置，然后按“将设置复制到此配置”。"
L["Pick a profile, then press Delete Selected Profile."] = "选择一个配置，然后按“删除所选配置”。"
L["Pick a style for each - shake, pop, flash or glow. The preview plays the ones you turn on."] = "为每种选择样式——抖动、弹出、闪烁或发光。预览会播放你开启的那些。"
L["Pick a totem on Blizzard's own"] = "在暴雪自带的"
L["Pick a totem on Blizzard's own totem bar and the matching ShamanPower button takes it (clearing a slot there un-assigns it here). Elements kept out of Drop All are left alone. Out of combat; a change made during a fight is picked up when it ends."] = "在暴雪自带图腾条上选择图腾后，对应的 ShamanPower 按钮会采用它（在该处清空槽位即在此取消分配）。被排除在“全部插放”之外的元素不受影响。仅在战斗外生效；战斗中做出的更改会在战斗结束时应用。"
L["Pick an Icon..."] = "选择图标..."
L["Pick the spells below; icons only appear for spells you know."] = "在下方选择技能；图标只会为你已学会的技能出现。"
L["Pick the totems you care about: green in range, red out of range, gray when nobody has it down."] = "选择你关心的图腾：绿色表示在范围内，红色表示超出范围，灰色表示无人插下。"
L["Pick which totems the overlay tracks."] = "选择浮层要追踪的图腾。"
L["Pick which totems the overlay watches."] = "选择浮层要追踪的图腾。"
L["Pick your look"] = "选择外观"
L["Pick your spec and we will walk you through the features that matter for it, showing each one live. You can change anything later."] = "选择你的专精，我们会带你逐一了解与该专精相关的功能，并现场演示每一项。之后你可以随时更改任何设置。"
L["Pick your spec and we will walk you through the features that matter for it, showing each one live. Your current settings are kept - nothing changes unless you change it here."] = "选择你的专精，我们会带你逐一了解与该专精相关的功能，并现场演示每一项。你当前的设置会保留 - 除非你在此处更改，否则不会有任何变化。"
L["Place Each Totem Freely"] = "自由摆放每个图腾"
L["Place an icon for each spell anywhere you like. It appears when the spell comes off cooldown: Earth Shock, Stormstrike, Riptide and more."] = "把每个技能的图标放在任意位置。技能冷却结束时图标出现：大地震击、风暴打击、激流等。"
L["Place each totem freely"] = "自由放置每个图腾"
L["Place the bar above, below, left or right of the icon or number. Vertical bars fill from the bottom. With both the icon and number off, choose Horizontal or Vertical and place the bar anywhere."] = "将条放在图标或数字的上方、下方、左侧或右侧。垂直条从底部填充。图标与数字都关闭时，选择水平或垂直，并把条放在任意位置。"
L["Placement"] = "排列方式"
L["Plain (default)"] = "朴素（默认）"
L["Plain Totem Icon (No Dim or Colored Outline)"] = "纯图腾图标（无变暗或彩色外框）"
L["Plain totem icon (no dim or colored outline)"] = "纯图腾图标（无变暗或彩色轮廓）"
L["Plate Borders"] = "姓名板边框"
L["Plate Icons"] = "姓名板图标"
L["Play"] = "播放"
L["Play Alert Sound"] = "播放提醒音效"
L["Play Sound"] = "播放音效"
L["Play Sound With Seconds Left"] = "剩余秒数时播放音效"
L["Play a Sound"] = "播放音效"
L["Play a sound on each proc (at most once a second)"] = "每次触发播放音效（每秒最多一次）"
L["Play a sound shortly before the Windfury buff runs out"] = "风怒增益结束前不久播放音效"
L["Play a sound when a reactive totem icon appears"] = "应急图腾图标出现时播放音效"
L["Play a sound when the twist timer reaches the number of seconds chosen below."] = "当轮换计时器达到下方选择的秒数时播放音效。"
L["Play a sound when totem alerts appear"] = "图腾提醒出现时播放音效"
L["Play a sound when weapon imbue alerts appear"] = "武器附魔提醒出现时播放音效"
L["Play a sound when your shield's last charge is used, including in combat."] = "护盾最后一层被消耗时播放音效，包括战斗中。"
L["Play a sound when your shield's last charge is used, including in combat. Shield Charges shares"] = "护盾最后一层被消耗时播放音效，包括战斗中。“护盾层数”共用"
