L["ShamanPower does a LOT more than a totem bar. This walkthrough shows every feature working and lets you set it up as you go - it is the fastest way to get the most out of the addon."] = "ShamanPower 远不止一个图腾条。本导览会演示每项功能的效果，并让你边看边设置——这是充分发挥插件作用最快的方式。"
L["ShamanPower has changed"] = "ShamanPower 已更新"
L["ShamanPower helps you play alongside shamans."] = "ShamanPower 帮你与萨满并肩作战。"
L["ShamanPower is free for every shaman, and it always will be. These people"] = "ShamanPower 对每位萨满都免费，而且永远如此。这些人"
L["ShamanPower is off"] = "ShamanPower 已关闭"
L["ShamanPower is off. Click to turn it back on."] = "ShamanPower 已关闭。点击重新开启。"
L["ShamanPower on GitHub"] = "在 GitHub 上查看 ShamanPower"
L["ShamanPower's bar hides and you play on Blizzard's own totem bar. ShamanPower draws its timers, duration bars, pulse and party dots on Blizzard's slots; you pick totems with Blizzard's flyout, which opens only from the arrow above each slot. Every other style opens its flyouts when you hover the totem, unless you set them to open only from an arrow or a key (Totem Bar > Clicks)."] = "ShamanPower 的条会隐藏，你改用暴雪自带的图腾条。ShamanPower 在暴雪的槽位上绘制计时、持续时间条、脉冲和小队圆点；你通过暴雪的弹出菜单选择图腾，该菜单只能从每个槽位上方的箭头打开。其他所有样式都会在鼠标悬停图腾时打开弹出菜单，除非你将其设置为仅通过箭头或按键打开（图腾条 > 点击方式）。"
L["ShamanPower: Cannot update macros in combat"] = "ShamanPower：战斗中无法更新宏"
L["ShamanPower: Macros created! Check your macro panel (Esc -> Macros)"] = "ShamanPower：宏已创建！请查看宏面板（Esc -> 宏）"
L["ShamanPower: Macros updated! Look for these in your macro list:"] = "ShamanPower：宏已更新！请在宏列表中查找："
L["ShamanPower: the logo's element colors, WoW's own green, yellow and red for charges and timers, and navy panels."] = "ShamanPower：标志的元素色，层数与计时沿用 WoW 自带的绿、黄、红，以及深蓝色面板。"
L["Shamanistic Rage"] = "萨满之怒"
L["Shamans talk to each other through the addon. A shaman without it will not appear in this list and cannot receive assignments - tell your fellow shamans to install it."] = "萨满们通过插件互相通信。没有安装此插件的萨满不会出现在列表中，也无法接收分配——请转告你的萨满同伴安装。"
