L["Show a bar along the bottom of the shield button with one segment per charge, filled to the charges left: the same look as the charge bar on the Shield Charges display. It stays blue at every count, in and out of combat."] = "在护盾按钮底部显示一条分段进度条，每层一段，填充至剩余层数：外观与“护盾层数”显示中的层数条相同。无论层数多少、战斗内外，它都保持蓝色。"
L["Show a bar with one segment per charge (3 for Lightning Shield or Water Shield), filled to the charges left: under, over or beside the display (Charge Bar Direction). The bar stays blue at every count."] = "显示一条每层一段的进度条（闪电之盾或水之盾为 3 段），填充至剩余层数：位于显示区域下方、上方或旁边（层数条方向）。无论层数多少，进度条始终为蓝色。"
L["Show a bar with one segment per charge (3 for Lightning Shield or Water Shield, 6 for Earth Shield), filled to the charges left: under, over or beside the display (Charge Bar Direction). The bar keeps the shield's color at every count: blue for your own shield, green for Earth Shield."] = "显示一条每层一段的进度条（闪电之盾或水之盾为 3 段，大地之盾为 6 段），填充至剩余层数：位于显示区域下方、上方或旁边（层数条方向）。无论层数多少，进度条都保持护盾的颜色：自己的护盾为蓝色，大地之盾为绿色。"
L["Show a box you can drag to move the Cooldown Bar. Turn this off when done."] = "显示一个可拖动来移动冷却条的框。完成后请关闭此项。"
L["Show a button at full opacity while its buff is up or its cooldown is running, even if the opacity above is lower."] = "当按钮的增益存在或冷却进行中时以完全不透明显示，即使上方的不透明度更低。"
L["Show a flyout on the Earth Shield button to choose its target."] = "在大地之盾按钮上显示弹出菜单以选择目标。"
L["Show a gray sweep over the icon as time runs out."] = "随时间流逝在图标上显示灰色扫过效果。"
L["Show a grid to help line up your bars and panels. With Snap to Grid on, a dropped box lines up with it. This choice is saved."] = "显示网格以帮助对齐条和面板。开启“吸附网格”时，松开的框体会与网格对齐。此选择会被保存。"
