L["Show the 4 totem icons on the active loadout button instead of the loadout icon, so you can see at a glance which totems are assigned"] = "在当前配装按钮上显示 4 个图腾图标而非配装图标，便于一眼看出已分配哪些图腾"
L["Show the Cooldown Bar for shields, Reincarnation, Nature's Swiftness and other spells."] = "为护盾、复生、自然迅捷及其他法术显示冷却条。"
L["Show the Drop All button on the Totem Bar."] = "在图腾条上显示“全部插放”按钮。"
L["Show the Loadout List on your screen. Off by default. The loadout bar can stay on too."] = "在你的屏幕上显示配装列表。默认关闭。配装条也可同时保持开启。"
L["Show the Mana Tide Call on My Screen"] = "在我的屏幕上显示法力之潮召唤"
L["Show the Party Strip while you are in a group. In a raid it shows your own party."] = "在组队时显示小队条。在团队中显示你自己的小队。"
L["Show the Rage of the Farseer cooldown on the cooldown bar (Enhancement capstone talent, WoW: Forever)"] = "在冷却条上显示先知之怒的冷却（增强系顶级天赋，WoW: Forever）"
L["Show the Raid Cooldowns alert when anyone in your group asks for Mana Tide using a word below and it is ready. They do not need to be an assigned caller. Only you see the alert. Ignore ShamanPower announcements and replies."] = "当队伍中任何人使用下方词语请求法力之潮且其已就绪时，显示团队冷却提醒。他们不必是指定的召唤者。只有你能看到此提醒。忽略 ShamanPower 的通报与回复。"
L["Show the Raid Coverage panel in a raid, for the totems whose cells you turn on below."] = "在团队中显示团队覆盖面板，用于你在下方开启格子的图腾。"
L["Show the Raid Resistance checkboxes and answer requests from the raid. Off: you do not see the checkboxes, and a request that picks you passes straight to the next shaman."] = "显示团队抗性复选框并响应团队中的请求。关闭：不显示复选框，且选中你的请求会直接转给下一位萨满。"
L["Show the ShamanPower button on the minimap."] = "在小地图上显示 ShamanPower 按钮。"
L["Show the Totem Bar in a party or raid. The Cooldown Bar has its own settings."] = "在小队或团队中显示图腾条。冷却条有独立设置。"
L["Show the Totem Bar while solo. The Cooldown Bar has its own settings."] = "单人时显示图腾条。冷却条有独立设置。"
L["Show the WeakAura import string to copy and send to a melee player."] = "显示可复制并发送给近战玩家的 WeakAura 导入字符串。"
L["Show the WeakAura string (copy, then import in WeakAuras)"] = "显示 WeakAura 字符串（复制后在 WeakAuras 中导入）"
L["Show the WeakAura string to copy"] = "显示可复制的 WeakAura 字符串"
L["Show the alert each time Windfury procs on you"] = "每次风怒在你身上触发时显示提醒"
L["Show the background and border behind the caller buttons. Turn this off (or use Hide Frame in the buttons' own settings) to show only icons."] = "显示召唤按钮后面的背景与边框。关闭此项（或使用按钮自身设置中的“隐藏框架”）可仅显示图标。"
L["Show the bar outside combat while you target anything you can attack, including neutral creatures."] = "在战斗外，当你选中任何可攻击目标（包括中立生物）时显示该条。"
L["Show the buff you can Purge. Turn off to use the Purge icon."] = "显示可净化的增益。关闭后使用净化图标。"
L["Show the charge count as a number. It can only be turned off while the shield icon or the charge bar is shown, so the display never goes blank."] = "以数字显示层数。只有在显示护盾图标或层数条时才能关闭，因此显示永远不会空白。"
L["Show the debuff's icon"] = "显示减益图标"
L["Show the debuff's icon in the alert's corner, including in combat. Turn this off to show only the totem to drop."] = "在提醒的角落显示减益图标，战斗中也会显示。关闭此项则只显示要插的图腾。"
L["Show the debuff's icon in the corner. Its name is unavailable in combat on this version of the game."] = "在角落显示减益图标。此版本游戏中战斗中无法获取其名称。"
L["Show the key bound to each button in its top-right corner. The same setting as on General > Keybinds."] = "在每个按钮右上角显示所绑定的按键。与通用 > 按键绑定中的设置为同一项。"
L["Show the large totem icons when you or a party member is feared, poisoned or diseased."] = "当你或小队成员被恐惧、中毒或染病时，显示大型图腾图标。"
L["Show the live preview"] = "显示实时预览"
L["Show the loadout bar to switch totem loadouts quickly."] = "显示配装条以快速切换图腾配装。"
L["Show the number of charges left in the corner of the shield button. Turn it off to show only the Shield Charge Bar."] = "在护盾按钮角落显示剩余层数。关闭后只显示护盾层数条。"
L["Show the remaining time as a number on the totem. Turn off for just the swipe."] = "在图腾上以数字显示剩余时间。关闭则只显示扫描动画。"
L["Show the reminder when you target a known fear-casting mob, or when a boss fight that fears starts"] = "当你选中已知会施放恐惧的怪物，或带有恐惧的 Boss 战开始时显示提醒"
L["Show the shield's icon ("] = "显示护盾图标（"
L["Show the time left as text on spell cooldowns and weapon imbues. Only used while Duration Text Location is set to None; any other location always shows the time. The shield's time shows only when Duration Text Location is set."] = "在法术冷却和武器附魔上以文字显示剩余时间。仅在“持续时间文字位置”设为“无”时使用；其他任何位置都会始终显示时间。护盾的时间仅在设置了“持续时间文字位置”时显示。"
L["Show the totem bar"] = "显示图腾条"
L["Show the totem icons without a background or title. ALT+drag to move. Right-click for settings."] = "不显示背景或标题，仅显示图腾图标。ALT+拖动可移动。右键可打开设置。"
L["Show the totem's time left when Time Left Position is On Icon (Top, Center or Bottom). Other text locations have their own settings."] = "当“剩余时间位置”为“在图标上”（顶部、中央或底部）时，显示图腾的剩余时间。其他文字位置有各自的设置。"
L["Show the twist countdown as whole seconds instead of decimals (8 instead of 8.3)"] = "轮换倒计时以整秒显示，而非小数（显示 8 而非 8.3）"
