L["Shows every ShamanPower element at once - both bars and each enabled module, with sample content - under a blue box you can drag. Most boxes have their own Reset, and the bar at the top has Reset All Positions and Done. Out of combat only; a fight locks everything again. Each module's own lock setting is left as it is. Also: /spunlock"] = "一次性显示 ShamanPower 的每个元素——两条状态条和每个已启用的模块，并带有示例内容——它们都位于可拖动的蓝色框中。大多数框有自己的“重置”，顶部的条则有“重置所有位置”和“完成”。仅限战斗外；一旦进入战斗，所有内容会再次锁定。各模块自身的锁定设置保持不变。另见：/spunlock"
L["Shows every alert for 3 seconds, each with its own look and glow, and plays each alert's own sound."] = "显示每个提醒 3 秒，各带自己的外观与发光，并播放每个提醒自己的音效。"
L["Shows every enabled icon with settings hidden. Drag them, then press Done to return here."] = "显示所有已启用的图标并隐藏设置。拖动它们，然后点击“完成”返回此处。"
L["Shows large totem icons when you have fear, disease, or poison debuffs"] = "当你带有恐惧、疾病或中毒减益时显示大型图腾图标"
L["Shows the controller button for each slot in its corner, as Xbox, PlayStation or Switch pictures, whichever pad you use."] = "在栏位角落显示对应的手柄按键，按你使用的手柄显示为 Xbox、PlayStation 或 Switch 图标。"
L["Shows the items on your Cooldown Bar (shield, imbue and cooldowns, in the Cooldown Bar's order) in the controller look."] = "以手柄外观显示冷却条上的项目（护盾、附魔与冷却，顺序同冷却条）。"
L["Shows the reminder for 5 seconds on your Air button, or on the next element with an assigned totem"] = "在你的空气按钮上显示 5 秒提醒，或在下一个分配了图腾的元素按钮上显示"
L["Shows the totems you picked as Quick Totem 1 and 2 at each element's corners. While one of them is down it"] = "在每个元素的角上显示你选为快捷图腾 1 和 2 的图腾。其中一个已插下时，它会以该元素的颜色亮起并显示剩余时间；"
