L["Tank: Intimidating Shout"] = "坦克：破胆怒吼"
L["Tanks"] = "坦克"
L["Target Tracker"] = "目标追踪"
L["Target Tracker Icon Edge"] = "目标追踪图标边缘"
L["Target Tracker Missing Debuff Style"] = "目标追踪缺失减益样式"
L["Target a mob known to fear and the reminder appears. Drop Tremor and it goes away. It starts just above the middle of your screen. Move it in the Position step."] = "选中已知会施放恐惧的怪物时提醒就会出现。插下战栗图腾后它便消失。它初始位于屏幕中部偏上的位置，可在“位置”步骤中移动。"
L["Tell My Group in Chat"] = "在聊天中告知队伍"
L["Tell me what is new at the trainer when I level up."] = "升级时告诉我训练师处有什么新内容。"
L["Tell your group a set number of seconds (Seconds Before) before the cooldown is ready. Works in combat when chat is available."] = "在冷却就绪前的指定秒数（提前秒数）告知队伍。聊天可用时在战斗中也能生效。"
L["Tell your group when you use Mana Tide"] = "当你使用法力之潮时告知队伍"
L["Terrifying Screech"] = "恐惧尖啸"
L["Test"] = "测试"
L["Test "] = "测试 "
L["Test Cooldown Bar Effects"] = "测试冷却条效果"
L["Test Cooldown Reset"] = "测试冷却重置"
L["Test Expiring Alerts"] = "测试到期提醒"
L["Test Icon"] = "测试图标"
L["Test Messages (Only You See Them)"] = "测试消息（仅你可见）"
L["Test Reactive Totems"] = "测试应急图腾"
L["Test Sound"] = "测试音效"
L["Test This Button's Effects"] = "测试此按钮的效果"
L["Test This Flash"] = "测试此闪烁"
L["Test This Totem's Effects"] = "测试此图腾的效果"
L["Test Totem Bar Effects"] = "测试图腾条效果"
L["Test Tremor Reminder"] = "测试战栗图腾提醒"
L["Test Usual Totem Reminder"] = "测试常用图腾提醒"
L["Test Windfury Proc"] = "测试风怒触发"
L["Test sound"] = "测试音效"
L["Test the Ready Flash"] = "测试就绪闪烁"
L["Testing"] = "测试"
L["Testing & Position"] = "测试与位置"
L["Text Color"] = "文字颜色"
L["Text Only"] = "仅文字"
L["Text Outline"] = "文字描边"
L["Text Outline (If Not Set Under Fonts & Textures)"] = "文字描边（若未在“字体与材质”中设置）"
L["Text Size"] = "文字大小"
L["Text only"] = "仅文字"
L["Text size"] = "文字大小"
L["Textures"] = "材质"
L["The 10 second Windfury buff has started ticking."] = "10 秒的风怒增益已开始计时。"
L["The Air slot always shows the totem to cast NEXT. The number is how long the Windfury buff has left."] = "空气槽位始终显示下一个要插的图腾。数字表示风怒增益的剩余时间。"
L["The Charge Bar's color below 5 stacks."] = "5 层以下时层数条的颜色。"
L["The Cooldown Text Color setting on Totem Bar > Duration Bars. The ShamanPower themes set it to white; you can still change it there."] = "图腾条 > 持续时间条中的“冷却文字颜色”设置。ShamanPower 主题将其设为白色；你仍可在那里更改。"
L["The Drop All button. ShamanPower Minimal draws it as a box in the color of the totem it shows."] = "全部插放按钮。ShamanPower Minimal 以所显示图腾的颜色将其绘制为方块。"
L["The Earth Shield icon. ShamanPower Minimal draws it as a flat box."] = "大地之盾图标。ShamanPower Minimal 将其绘制为扁平方块。"
L["The Element Colors setting on Appearance. The ShamanPower themes switch it to the ShamanPower palette; Standard puts yours back."] = "外观页中的“元素颜色”设置。ShamanPower 主题会将其切换为 ShamanPower 调色板；标准主题则恢复为你自己的配色。"
L["The Empty choice in a flyout. ShamanPower Minimal shows a dark box with a dash."] = "弹出菜单中的“空”选项。ShamanPower Minimal 显示为带横线的深色方块。"
L["The Grid style's icons. ShamanPower Minimal draws them as flat element boxes."] = "网格样式的图标。ShamanPower Minimal 将其绘制为扁平的元素方块。"
L["The Party Strip's background and border. Its Background Opacity setting still decides how solid they are."] = "小队条的背景与边框。其“背景不透明度”设置仍决定它们的实心程度。"
L["The Party Strip's circle with a slash (missing your buff) and its question mark (can't tell)."] = "小队条上的斜线圆圈（缺少你的增益）与问号（无法确定）。"
L["The Party Strip's dots and names in class colors. Class Colors picks the set: Use Theme's follows the Class Colors cards at the top."] = "使用职业颜色的小队条圆点与名称。职业颜色决定所用配色：“使用主题的”会跟随顶部的职业颜色卡片。"
L["The Pop-Out Trackers' background and border."] = "弹出追踪器的背景与边框。"
L["The Priest is back too - only the Hunter is still missing Mana Spring."] = "牧师也回来了 - 只有猎人还缺少法力之泉。"
L["The Raid Cooldowns panels and the alert in the middle of the screen."] = "团队冷却面板与屏幕中央的提醒。"
L["The Settings Window"] = "设置窗口"
L["The ShamanPower colors, with flat element boxes and each totem's letters in place of the icons."] = "沿用 ShamanPower 配色，扁平的元素方块，并以各图腾的字母代替图标。"
L["The ShamanPower look"] = "ShamanPower 风格"
L["The ShamanPower theme with icons replaced by flat, colored boxes and letters. This preset never changes."] = "ShamanPower 主题，但图标替换为扁平的彩色方块与字母。此预设永不改变。"
L["The Storm Glow's color below 5 stacks."] = "5 层以下时风暴光晕的颜色。"
L["The Totem Bar shows whatever totem you have down for each element. No need to assign totems first: drop one and it becomes that element's button. Great for PvP. Turning this on turns Compact Style off. While Totem Twisting is on, the Air button is left alone."] = "图腾条会显示你当前为每个元素插下的图腾。无需先分配图腾：插下哪个，它就成为该元素的按钮。非常适合 PvP。开启此项会关闭紧凑样式。图腾轮换开启时，空气按钮不受影响。"
L["The Tremor Totem glow and the Raid Cooldowns alert."] = "战栗图腾的发光与团队冷却提醒。"
L["The Tremor Totem glow. Standard keeps the color you picked on Tremor Reminder."] = "战栗图腾的光晕。标准主题保留你在战栗图腾提醒中所选的颜色。"
L["The Tremor Totem icon. ShamanPower Minimal draws it as a flat Earth box."] = "战栗图腾图标。ShamanPower Minimal 将其绘制为扁平的大地方块。"
L["The Warrior is back in range: Earth's cell has nothing to say and drops out."] = "战士回到了范围内：大地的格子无需再显示，因而隐去。"
L["The Warrior is back in range: everyone has Earth's buff now."] = "战士回到了范围内：现在所有人都拥有大地的增益。"
L["The Windfury Proc alert's WINDFURY! word and its internal cooldown countdown."] = "风怒触发警报里的 WINDFURY! 字样及其内置冷却倒计时。"
L["The X stays on the button until you cast again, instead of fading after 5 seconds. Off: an X held now fades."] = "红叉会留在按钮上直到你再次施放，而不是 5 秒后淡出。关闭：当前保留的红叉会淡出。"
L["The X stays on the button until you drop that element again, instead of fading after 5 seconds. Off: an X held now fades."] = "X 会一直留在按钮上，直到你再次插放该元素的图腾，而不是 5 秒后淡出。关闭：当前显示的 X 立即淡出。"
L["The X stays on the totem until the fight ends, then for a few seconds more (or until you drop that element again), instead of fading after 5 seconds. Out of a fight it fades after 5 seconds. Off: an X held now fades."] = "X 会一直留在图腾上，直到战斗结束，然后多停留几秒（或直到你再次插放该元素的图腾），而不是 5 秒后淡出。战斗外则 5 秒后淡出。关闭：当前显示的 X 立即淡出。"
L["The X stays until you drop that element again, instead of fading after 5 seconds."] = "红叉会一直保留到你再次插下该元素，而不是 5 秒后淡出。"
L["The background and border of the totem bar's panel - the box drawn behind the four totem buttons. (The icons, the flyouts, the cooldown bar and the Compact lines are not skinned by this.)"] = "图腾条面板的背景与边框——即绘制在四个图腾按钮后面的方框。（图标、弹出栏、冷却条和紧凑行不由此换肤。）"
L["The bar and the flash for totems that pulse (Tremor, Healing Stream...)."] = "有脉冲的图腾（战栗、治疗之泉……）的条和闪光。"
L["The bar ignores the mouse: no tooltip, no click, no flyout from hovering. Clicks land on whatever is behind it."] = "条会忽略鼠标：没有提示信息、无法点击、悬停也不会弹出菜单。点击会落到其后方的内容上。"
L["The bar lies flat or stands upright (the icon and the number are off, so there is nothing to sit beside)."] = "条横向平放或竖直立起（图标与数字已关闭，因此没有需要并排的对象）。"
L["The bar on each totem button that runs down as the totem's time runs out."] = "每个图腾按钮上随图腾剩余时间减少的条。"
L["The bar simply becomes whatever you last dropped - one totem per slot, nothing else. Great for PvP."] = "图腾条直接变为你最后插下的图腾——每格一个图腾，别无其他。非常适合 PvP。"
L["The bar, or one orb per charge. Works in fights."] = "条，或每层一颗宝珠。战斗中可用。"
L["The bars that count down each totem. The ShamanPower themes use the element palette."] = "为每个图腾倒计时的条。ShamanPower 主题使用元素调色板。"
L["The bars that run down under your totems, on pop-outs, Grid and Blizzard's bar."] = "在你的图腾下方、弹出元素、网格和暴雪图腾条上显示的持续时间条。"
L["The big charge number and bar: full, low and last charge."] = "大号层数数字与条：满层、低层与最后一层。"
L["The blue ShamanPower has always used, on all three shields."] = "ShamanPower 一直使用的蓝色，用于全部三种护盾。"
L["The blue ShamanPower has always used, on both shields."] = "ShamanPower 一直使用的蓝色，用于两种护盾。"
L["The blue WoW gives magic buffs. Your shields use it when you pick WoW Magic Blue above."] = "WoW 赋予魔法增益的蓝色。当你在上方选择“WoW 魔法蓝”时，护盾会使用它。"
L["The border around Purge's icon. Spell Color: WoW's Magic blue."] = "净化图标周围的边框。“技能颜色”：WoW 的魔法蓝色。"
L["The border around enemy and friendly totem plates."] = "敌方与友方图腾姓名板周围的边框。"
L["The border around this spell's icon. Spell Color: the spell's element color."] = "此技能图标周围的边框。“技能颜色”：该技能的元素颜色。"
L["The border drawn around the totem bar's panel (the box behind the totem buttons)."] = "绘制在图腾条面板（图腾按钮后面的方框）周围的边框。"
L["The border drawn round the totem bar's panel."] = "绘制在图腾条面板周围的边框。"
L["The bright line that travels around the icon with the Clock Sweep. Off for a plain dark sweep."] = "时钟扫描时绕图标移动的亮线。关闭则为纯暗色扫描。"
L["The buff's time left, as a number beside the bar."] = "增益剩余时间，以数字显示在条旁。"
L["The buff's time left, as a smaller number under the count."] = "该增益的剩余时间，以较小的数字显示在层数下方。"
L["The buff's time left: a number, or Drain: the look goes gray from the top as the time runs out."] = "增益剩余时间：显示数字，或“流干”：随时间耗尽，外观从顶部开始变灰。"
L["The caller buttons can be dragged any time they are on screen."] = "召唤按钮在屏幕上时随时可以拖动。"
L["The caller buttons. ShamanPower Minimal draws them as flat boxes (Mana Tide in Water)."] = "召唤按钮。ShamanPower Minimal 将其绘制为扁平方块（法力之潮为水色）。"
L["The charge count as a number. It can only be off while the icon or the charge bar is on."] = "以数字显示层数。仅当图标或层数条开启时才能关闭。"
L["The charge count on the shield button. The ShamanPower themes use WoW's green, yellow and red."] = "护盾按钮上的层数计数。ShamanPower 主题使用魔兽的绿、黄、红。"
L["The charges left, as a number. It can only be off while the icon or the charge bar is on, so the display never goes blank."] = "剩余层数，以数字显示。只有在图标或层数条开启时才能关闭，因此显示不会完全空白。"
L["The charges left, in the button's corner."] = "在按钮角落显示剩余层数。"
L["The class colors of the party dots and the Totem Coverage dots."] = "小队圆点与图腾覆盖圆点所使用的职业颜色。"
L["The class colors of the party dots and the Totem Coverage dots: WoW's own, or ShamanPower's Subtle, Stronger, Vibrant or Muted (the same hue for every class). The same setting as the Class Colors cards on Appearance > Themes."] = "小队圆点与图腾覆盖圆点使用的职业颜色：魔兽自带的，或 ShamanPower 的柔和、更强、鲜艳或内敛（所有职业使用同一色调）。与“外观 > 主题”中的“职业颜色”卡片是同一项设置。"
L["The class icons in the Earth Shield flyout. ShamanPower Minimal shows a class-color box with letters."] = "大地之盾弹出菜单中的职业图标。ShamanPower Minimal 显示带字母的职业色方块。"
L["The color each element is drawn in: Compact lines, alerts, party counters"] = "每种元素的显示颜色：紧凑线条、提醒、小队计数"
L["The color of each alert's text."] = "每条提醒文字的颜色。"
L["The color of the line round the panel. The same as Border on Appearance > Themes > Cooldown Bar > Frame Background and Border."] = "面板周围线条的颜色。与 外观 > 主题 > 冷却条 > 边框背景与边框 中的“边框”相同。"
L["The color of the line round the panel. The same as Border on Appearance > Themes > Totem Bar > Frame Background and Border."] = "面板周围线条的颜色。与 外观 > 主题 > 图腾条 > 边框背景与边框 中的“边框”相同。"
L["The color of this shield's charge bar and orbs (Shield Icon Orbs keep their icons). Any color you like. Also on Appearance > Themes."] = "此护盾层数条和光球的颜色（“护盾图标光球”保留其图标）。任意颜色均可。外观 > 主题中也有。"
L["The color of this shield's charge bar and orbs (Shield Icon Orbs keep their icons). The same setting as on Shield Charges."] = "该护盾的层数条与光球颜色（护盾图标光球的图标保持不变）。与“护盾层数”中的设置相同。"
L["The color the Two-Tone gradient shades into. WoW gold to start."] = "双色渐变过渡到的颜色。初始为 WoW 金色。"
L["The color the gradient shades into. WoW gold by default."] = "渐变过渡到的颜色。默认为 WoW 金色。"
L["The color the gradient shades into. WoW gold to start."] = "渐变过渡到的颜色。初始为 WoW 金色。"
L["The color the gradient starts in."] = "渐变起始的颜色。"
L["The color this opened with. Click it to go back to it."] = "打开时所用的颜色。点击可恢复为该颜色。"
L["The colored edge round the totem's icon."] = "图腾图标周围的彩色边框。"
L["The colors WoW itself uses, so the ShamanPower themes match the rest of your game."] = "WoW 自身使用的颜色，让 ShamanPower 主题与游戏其他界面保持一致。"
L["The colors of the ShamanPower logo."] = "ShamanPower 标志的配色。"
L["The cooldown bar is off. Its switch is beside Cooldown Bar in the sidebar."] = "冷却条已关闭。其开关位于侧边栏“冷却条”旁边。"
L["The cooldown bar's Shield Charge Bar (each shield's charges on screen have their own gradient: Shield Charge Display, below), and each shield's Charge Color. Bar Gradient never touches them."] = "冷却条的护盾层数条（屏幕上每个护盾的层数有各自的渐变，见下方“护盾层数显示”），以及每个护盾的层数颜色。“条渐变”不会影响它们。"
L["The cooldown bar's background and border. The ShamanPower themes use navy."] = "冷却条的背景与边框。ShamanPower 主题使用深蓝色。"
L["The cooldown bar's buttons and its shield and imbue flyouts (ShamanPower Minimal's boxes too). Also on Appearance > Cooldown Bar and the Cooldown Bar page."] = "冷却条的按钮及其护盾与附魔飞出菜单（ShamanPower 极简的方块同样适用）。也应用于“外观 > 冷却条”和“冷却条”页面。"
L["The cooldown buttons. ShamanPower Minimal draws them as flat boxes."] = "冷却按钮。ShamanPower Minimal 将其绘制为扁平方块。"
L["The cooldown number on a Ready Reminder's icon, Combined Shocks too (the same switch as the Ready Reminders page's)."] = "就绪提醒图标上的冷却数字，组合震击亦然（与就绪提醒页面上的开关相同）。"
L["The cooldown number on every Ready Reminders icon. An icon's own Countdown Text Size (its right-click menu) wins."] = "每个就绪提醒图标上的冷却数字。图标自身的“倒计时文字大小”（右键菜单中）优先。"
L["The cooldown sweep and gray overlay. ShamanPower Minimal draws a dark band on the box."] = "冷却扫描与灰色遮罩。ShamanPower Minimal 在方块上绘制深色色带。"
L["The cooldown sweep over a totem. ShamanPower Minimal draws a dark band on the box."] = "覆盖图腾的冷却扫描。ShamanPower Minimal 在方块上绘制深色色带。"
L["The count over the look, as Icon + Stack Number shows it: white, in Color At 5 Stacks at 5."] = "覆盖在外观上的层数，与“图标 + 层数数字”显示一致：白色，5 层时改用“5 层时的颜色”。"
L["The countdown changes color as it runs: the Cooldown Numbers colors on Appearance > Colors & Borders. Off: white."] = "倒计时随时间变色：颜色取自 外观 > 颜色与边框 里的冷却数字。关闭则为白色。"
L["The coverage dots in class colors. Class Colors picks the set: Use Theme's follows the Class Colors cards at the top."] = "使用职业颜色的覆盖圆点。职业颜色决定所用配色：“使用主题的”会跟随顶部的职业颜色卡片。"
L["The coverage panel's background and border."] = "覆盖面板的背景与边框。"
L["The dark square behind the totem's icon."] = "图腾图标后方的深色方块。"
L["The dark track behind the duration bar. Turn it off to show only the colored bar, like the pulse bars. Also on the pop-out trackers' bars."] = "持续时间条后方的深色底槽。关闭后仅显示彩色条，与脉动条相同。弹出追踪器的条同样适用。"
L["The dark track behind the duration bars. Turn it off to show only the colored bar, like the pulse bars. The same setting as on Totem Bar > Duration Bars."] = "持续时间条后方的暗色底槽。关闭后只显示彩色条，与脉冲条一致。与“图腾条 > 持续时间条”中的设置相同。"
L["The debuff's own icon in the alert's corner, in fights too."] = "在提醒角落显示减益自身的图标，战斗中同样显示。"
L["The dot for a party member without the buff."] = "没有该增益的小队成员的圆点。"
L["The dot for a party member without your totem's buff."] = "未获得你的图腾增益的小队成员的圆点。"
L["The dropped totem becomes the big icon. Your assigned totem stays in the bottom-right corner until the dropped totem is gone."] = "插下的图腾成为大图标。你分配的图腾留在右下角，直到插下的图腾消失。"
L["The edge around each spell's icon: Flame Shock, Frost Shock, Stormstrike and Purge. Spell Color: each spell's own color. Also on Target Tracker (right-click a spell > Look)."] = "每个技能图标周围的边缘：烈焰震击、冰霜震击、风暴打击与净化。技能颜色：各技能自身的颜色。也应用于“目标追踪”（右键点击技能 > 外观）。"
L["The edge the color comes back from."] = "颜色回填的起始边。"
L["The edge's color while the buff is on you. It starts as WoW's mana-bar blue."] = "增益在你身上时边框的颜色。默认为魔兽法力条的蓝色。"
L["The element lines of the Compact style."] = "紧凑样式的元素线条。"
L["The element names in a loadout's tooltip."] = "配装鼠标提示中的元素名称。"
L["The element rings and split borders of the Grid style."] = "网格样式的元素环与分割边框。"
L["The element squares ShamanPower draws on Blizzard's Totem Bar."] = "ShamanPower 在 Blizzard 图腾条上绘制的元素方块。"
L["The element tints in the Totem Assignments window."] = "图腾分配窗口中的元素色调。"
L["The element tints in the range tracker's totem picker."] = "范围追踪器图腾选择器中的元素色调。"
L["The element-colored border around a dropped totem."] = "已插下图腾周围的元素色边框。"
L["The element-colored borders round each totem, and the totem bar, cooldown bar and panel borders. Also on Appearance > Colors & Borders (Border Gradient)."] = "每个图腾周围的元素色边框，以及图腾条、冷却条和面板的边框。也应用于“外观 > 颜色与边框（边框渐变）”。"
L["The entries in the shield and imbue flyouts. ShamanPower Minimal draws them as flat boxes."] = "护盾与附魔弹出菜单中的条目。ShamanPower Minimal 将其绘制为扁平方块。"
L["The first cooldown plays Cooldown Ready, the imbue Weapon Imbue Gone and the shield Shield Gone,"] = "第一个冷却播放“冷却就绪”，附魔播放“武器附魔消失”，护盾播放“护盾消失”，"
L["The first cooldown plays Cooldown Ready, the imbue button Weapon Imbue Gone and the shield button"] = "第一个冷却播放“冷却就绪”，附魔按钮播放“武器附魔消失”，护盾按钮播放"
L["The first spot: the left corner (the top one on a bar that runs up and down)."] = "第一个位置：左角（纵向排列的图腾条上为上方）。"
L["The flash on the button each time this totem pulses."] = "此图腾每次脉冲时按钮上的闪烁。"
L["The flash on the shared spot. A spell with a spot of its own has its own Size in its menu."] = "共享位置上的闪烁。有独立位置的法术可在其菜单中设置自己的大小。"
L["The flash says "] = "闪烁会在图标下方显示 "
L["The flyout arrow tabs and panel. The ShamanPower themes draw flat tabs in the element colors."] = "弹出菜单的箭头标签与面板。ShamanPower 主题以元素色绘制扁平标签。"
L["The font for everything ShamanPower draws on screen, unless a section below picks its own."] = "ShamanPower 在屏幕上绘制的所有内容所用的字体，除非下方某部分指定了自己的字体。"
L["The game can't say what "] = "游戏还无法读取“"
L["The game never shows Windfury Totem's weapon buff on other players, so ShamanPower cannot see who has it. "] = "游戏从不向他人显示风怒图腾的武器增益，因此 ShamanPower 无法得知谁拥有它。 "
L["The game never shows Windfury Totem's weapon buff on other players, so ShamanPower cannot see who has it. A tiny WeakAura on your melee fixes that."] = "游戏从不显示其他玩家身上的风怒图腾武器增益，所以 ShamanPower 无法得知谁拥有它。给你的近战装一个小型 WeakAura 即可解决。"
L["The game never shows Windfury Totem's weapon buff on other players, so your shaman's addon cannot see that you have it. A tiny WeakAura on YOUR side fixes that."] = "游戏从不显示其他玩家身上的风怒图腾武器增益，所以你萨满的插件无法知道你拥有它。在你自己这边装一个小型 WeakAura 即可解决。"
L["The game's own class colors, exactly. What Standard always shows."] = "游戏原版职业色，完全一致。标准主题始终使用它。"
L["The gap between the icons: in the grid, or on every row at once (a row's own menu can give that row its own)."] = "图标之间的间隙：适用于网格，或同时适用于每一行（某行自己的菜单可为其单独设置）。"
L["The gap between this row's icons. 0 puts them side by side, touching."] = "此行图标之间的间距。0 表示紧挨着并排。"
L["The gap between your debuffs."] = "你的减益之间的间隔。"
L["The glow's color for this totem."] = "此图腾的发光颜色。"
L["The glow's color."] = "发光的颜色。"
L["The glow's shape. Proc Glow is the game's ring."] = "发光的形状。“触发发光”是游戏自带的圆环。"
L["The glow's shape: Square, Round or Proc Glow. Until you pick one it follows Appearance > Themes > Glow Shape."] = "光晕形状：方形、圆形或触发光晕。未选择前跟随 外观 > 主题 > 光晕形状。"
L["The highest rank you know. A rank you learn later is used right away."] = "你已知的最高等级。之后学会更高等级会立即改用。"
L["The icon beside the alert text. ShamanPower Minimal draws it as a flat box."] = "提醒文字旁的图标。ShamanPower Minimal 将其绘制为扁平方块。"
L["The icon darkens clockwise as it runs out."] = "图标随时间顺时针变暗。"
L["The icon gray while it can't proc."] = "无法触发期间图标变灰。"
L["The icon of the totem you have down. ShamanPower Minimal draws it as a flat box."] = "已插下图腾的图标。ShamanPower Minimal 将其绘制为扁平方块。"
L["The icon picker, beside this window. Without an icon of its own a loadout shows its first totem."] = "图标选择器就在此窗口旁边。没有专属图标的配装会显示它的第一个图腾。"
L["The icon's Sound (its group below) plays the moment the set changes."] = "套装变化时播放图标的音效（见下方分组）。"
L["The icons ignore the mouse: no tooltip. Clicks land on whatever is behind them. In Combat: only during fights, so they're yours again between them. Move the Icons still works."] = "图标不响应鼠标：没有鼠标提示，点击会落到它们后面的东西上。「仅战斗中」只在战斗期间如此，战斗之间仍归你操作。「移动图标」依然可用。"
L["The icons in the coverage cells. ShamanPower Minimal draws them as flat boxes."] = "覆盖格中的图标。ShamanPower Minimal 将其绘制为扁平方块。"
L["The inside of a line while no totem of that element is down."] = "该元素没有图腾插下时线条内部的颜色。"
L["The key found right now."] = "当前找到的按键。"
L["The last charge or almost out, a missing buff, a destroyed totem. Enemy totems on nameplates."] = "最后一层或即将耗尽、缺失增益、图腾被摧毁。姓名板上的敌方图腾。"
L["The link is selected - press |cffFFD100Ctrl+C|r to copy it, then paste it into your browser."] = "链接已选中 — 按 |cffFFD100Ctrl+C|r 复制，然后粘贴到浏览器中。"
L["The link is selected: press |cffFFD100Ctrl+C|r to copy it, then paste it into your browser."] = "链接已选中：按 |cffFFD100Ctrl+C|r 复制，然后粘贴到浏览器中。"
L["The list ignores the mouse: no tooltip, no right-click settings, no dragging."] = "列表忽略鼠标：没有提示、没有右键设置、无法拖动。"
L["The list ignores the mouse: no tooltip, no right-click settings, no dragging. Clicks land on whatever is behind it. In Combat: only during fights, so it's yours again between them."] = "列表忽略鼠标：无提示、无右键设置、无法拖动。点击会落到其后面的内容上。“战斗中”：仅在战斗期间，因此战斗间隙你又能正常操作。"
L["The list of new spells and ranks, in your own chat window."] = "在你自己的聊天窗口中列出新法术与等级。"
L["The loadout bar's buttons. ShamanPower Minimal draws them as flat boxes."] = "配装条的按钮。ShamanPower Minimal 将其绘制为扁平方块。"
L["The loadouts in Everywhere also show in the flyout and the Loadout List here."] = "“所有区域”中的配装也会显示在此处的弹出列表和配装列表中。"
L["The logo's colors on duration bars, borders and flyout tabs. Green, yellow and red charges and timers. Navy panels. Your icons stay the same. This preset never changes."] = "标志配色用于持续时间条、边框与飞出菜单标签。绿、黄、红三色的层数与计时。深蓝色面板。你的图标保持不变。此预设永不改变。"
L["The logo's element colors everywhere, WoW's own green, yellow and red for charges and timers, navy panels."] = "处处使用标志的元素色，层数与计时沿用 WoW 自带的绿、黄、红，深蓝色面板。"
L["The main totem button's tooltip shows the spell again."] = "主图腾按钮的提示框重新显示该法术。"
L["The main-hand and off-hand imbue buttons. ShamanPower Minimal draws them as flat boxes."] = "主手与副手附魔按钮。ShamanPower Minimal 将其绘制为扁平方块。"
L["The most rows it shows at once (headings count). More scroll with the mouse wheel."] = "一次最多显示的行数（包含标题行）。更多内容可用鼠标滚轮滚动。"
L["The names under a cell."] = "格子下方的名称。"
L["The new rank is used once the fight ends."] = "新的等级会在战斗结束后生效。"
L["The number a cooldown counts down with changes color as it runs: the first color while more than half is left, the"] = "冷却倒计时数字会随剩余时间变色：剩余超过一半时使用第一种颜色，"
L["The number of charges left in the corner of the shield button. Turn it off to show only the charge bar."] = "护盾按钮角落显示的剩余层数。关闭后只显示层数条。"
L["The number on a totem's button while its cooldown runs: on the totem bar, its flyouts and Totem Rows."] = "图腾冷却期间其按钮上的数字：适用于图腾条、其弹出菜单和图腾行。"
L["The number on the Air slot is how many melee have Windfury; each dot is one of them, in their class color when in range and red when not."] = "空气槽位上的数字表示有多少近战拥有风怒；每个圆点代表其中一人，在范围内显示职业色，不在范围内为红色。"
L["The number stays on while the icon and the charge bar are both off, so the display never goes blank."] = "图标与层数条都关闭时，数字会保持开启，因此显示不会完全空白。"
L["The number that counts a spell's cooldown down on its icon (Combined Shocks too) changes color as it runs: the Cooldown"] = "图标上为法术冷却倒计时的数字（合并震击也包含）会随倒计时变色：冷却"
L["The numbers that count who is in range of each totem."] = "统计每个图腾范围内人数的数字。"
L["The open world"] = "开放世界"
L["The opposite of Party Buff Tracker, which is about YOUR totems reaching THEM."] = "与小队增益追踪相反，后者关注的是你的图腾是否覆盖到他们。"
L["The optional range overlay shows non-shamans whether OTHER shamans' party buffs are in range."] = "可选的覆盖层向非萨满显示其他萨满的小队增益是否在范围内。"
L["The options below are for "] = "以下选项用于 "
L["The order Drop All drops your totems in, one per click, and which ones it leaves out. The same setting as each"] = "“全部插放”插下你图腾的顺序（每次点击一个），以及会跳过哪些。与每个"
L["The out-of-mana glow's own shape. Until you pick one it uses this icon's Glow Shape."] = "法力不足光晕专用的形状。未选择前使用此图标的光晕形状。"
L["The outline of a line while no totem of that element is down."] = "该元素没有图腾插下时线条外框的颜色。"
L["The panel behind the buttons. Its background color changes with how many assigned totems are down."] = "按钮后面的面板。其背景颜色会随已插下的已分配图腾数量变化。"
L["The panel behind the cooldown buttons. It has one background color."] = "冷却按钮后面的面板。它只有一种背景颜色。"
L["The panel's color while every totem you have assigned is down."] = "你指定的所有图腾均已插放时面板的颜色。"
L["The panel's color while none of your assigned totems are down."] = "指定的图腾均未插放时面板的颜色。"
L["The panel's color while some of your assigned totems are down."] = "部分指定的图腾已插放时面板的颜色。"
L["The panel's color. The same as Background on Appearance > Themes > Cooldown Bar > Frame Background and Border."] = "面板的颜色。与 外观 > 主题 > 冷却条 > 边框背景与边框 中的“背景”相同。"
L["The party buff counters' background and border. The ShamanPower themes use navy."] = "小队增益计数器的背景与边框。ShamanPower 主题使用深蓝色。"
L["The party dots and Totem Coverage's dots. Also on Party Buff Tracker."] = "小队圆点与图腾覆盖的圆点。也应用于小队增益追踪。"
L["The party dots in class colors. Class Colors picks the set: Use Theme's follows the Class Colors cards at the top."] = "使用职业颜色的小队圆点。职业颜色决定所用配色：“使用主题的”会跟随顶部的职业颜色卡片。"
L["The people who support ShamanPower on Patreon."] = "在 Patreon 上支持 ShamanPower 的人们。"
L["The popped-out icons. ShamanPower Minimal draws them as flat boxes."] = "弹出显示的图标。ShamanPower Minimal 将其绘制为扁平方块。"
L["The preview is paused during combat so the real display keeps working. It returns when combat ends."] = "战斗中预览会暂停，以确保实际显示正常工作。战斗结束后恢复。"
L["The preview is paused while you move things with Unlock UI. Click Done to show it again."] = "使用“解锁界面”移动元素时预览会暂停。点击“完成”即可重新显示。"
L["The preview updates as you change these settings."] = "更改这些设置时预览会更新。"
L["The profile used while you're "] = "在你是"
L["The progress bars on the cooldown bar and the weapon imbue bars."] = "冷却条和武器附魔条上的进度条。"
L["The pulse countdown text needs at least 14."] = "脉冲倒计时文字至少需要 14。"
L["The pulse flash and the ready and alert glows. Also on Totem Bar > Duration Bars and Ready Reminders."] = "脉冲闪烁以及就绪与提醒光晕。也应用于“图腾条 > 持续时间条”和“就绪提醒”。"
L["The pulse flash is off: Totem Bar > Duration Bars > Pulse Flash Opacity is at 0%."] = "脉冲闪烁已关闭：图腾条 > 持续时间条 > 脉冲闪烁不透明度为 0%。"
L["The pulse time is drawn by the pulse bar. Set Pulse Bar Position to something other than None first."] = "脉冲时间由脉冲条绘制。请先将“脉冲条位置”设置为“无”以外的值。"
L["The pulse wipe on the icons and the pulse bar: white, the element color or logo blue. Pulse Bar Color on Totem Bar > Duration Bars can still change it."] = "图标上的脉冲擦除与脉冲条：白色、元素色或标志蓝色。图腾条 > 持续时间条中的“脉冲条颜色”仍可更改。"
L["The quick setup"] = "快速设置"
L["The raid needs "] = "团队需要 "
L["The range tracker's background and border. The ShamanPower themes use navy."] = "范围追踪器的背景与边框。ShamanPower 主题使用深蓝色。"
L["The rank the bar, its flyout, Drop All, Quick Totems and the SP_ macros cast. A lower rank costs less mana."] = "图腾条、弹出菜单、全部插放、快捷图腾与 SP_ 宏所施放的等级。较低等级消耗更少法力。"
L["The reactive alerts. The ShamanPower themes color each one by the element of the totem that answers it."] = "应急提醒。ShamanPower 主题按应对它的图腾元素为每条提醒上色。"
L["The ready check panel's background and border."] = "就绪检查面板的背景与边框。"
L["The remaining seconds on the totem. Off = just the swipe."] = "图腾上的剩余秒数。关闭 = 仅显示扫过效果。"
L["The reminder's border. Standard keeps the color you picked on Ready Reminders."] = "提醒的边框。标准主题保留你在就绪提醒中所选的颜色。"
L["The row this icon sits on. Not On A Row: off your screen until you put it on one (pick one here, or drag the icon onto a row under Spells)."] = "此图标所在的行。“不在行中”：移出屏幕，直到你把它放到某行（在此选择一行，或在“技能”下把图标拖到某行）。"
L["The same as a click on it."] = "与点击它相同。"
L["The same as a click on its icon. Its settings stay as they are."] = "与点击其图标相同。其设置保持不变。"
L["The same hues, brightness evened out a little for ShamanPower's navy panels."] = "相同色相，亮度稍作均衡，更贴合 ShamanPower 的深蓝面板。"
L["The same hues, evened out more: priest white and rogue yellow calmer, shaman and warlock brighter."] = "相同色相，进一步均衡：牧师白色与盗贼黄色更柔和，萨满与术士更明亮。"
L["The same setting as this shield's sound in Expiring Alerts: each shield has its own."] = "与“到期提醒”中此护盾的音效为同一设置：每个护盾各自独立。"
L["The same setting as this shield's sound on Shield Charges: each shield has its own."] = "与“护盾层数”页中此护盾的音效是同一设置：每个护盾各有独立设置。"
L["The same value as Totem Bar Auto-Hide's Faded Opacity. It also sets how faint every display faded by Out Of The Way is."] = "与图腾条自动隐藏的“淡化不透明度”取值相同。它也决定所有因“让路”而淡化的显示器的淡化程度。"
L["The second spot: the right corner (the bottom one on a bar that runs up and down)."] = "第二个位置：右角（纵向排列的图腾条上为下方）。"
L["The seconds left, like 1.2."] = "剩余秒数，如 1.2。"
L["The seconds left, on the icon."] = "图标上显示剩余秒数。"
L["The seconds the buff has left."] = "增益剩余的秒数。"
L["The seconds your debuff has left, on its icon."] = "图标上显示你的减益剩余秒数。"
L["The settings have a new look"] = "设置界面焕然一新"
L["The setup tour, the new settings window and more"] = "设置向导、新的设置窗口以及更多"
L["The setup window hides while you drag things into place."] = "拖动摆放时，设置窗口会隐藏。"
L["The setup window hides while you move Totem Range Tracker. Click Done on the bar at the top when you are finished."] = "移动图腾范围追踪时设置窗口会隐藏。完成后点击顶部条上的“完成”。"
L["The setup window hides while you move your Totem Bar, Cooldown Bar"] = "移动图腾条、冷却条时设置窗口会隐藏"
L["The shaman who casts "] = "负责施放 "
L["The shape of "] = "以下对象的形状："
L["The shape of the dots. The same setting as Dot Shape on the Coverage tab and on Appearance > Themes."] = "圆点的形状。与“覆盖”选项卡及“外观 > 主题”中的“圆点形状”是同一项设置。"
L["The shape of the dots. The same setting as Dot Shape on the Dots & Counters tab and on Appearance > Themes."] = "圆点的形状。与“圆点与计数器”选项卡及“外观 > 主题”中的“圆点形状”是同一项设置。"
L["The shape of the flash around the button at each pulse. The same setting as Glow Shape on Appearance > Themes and Ready Reminders (it also shapes the other alert glows)."] = "每次脉动时按钮周围闪光的形状。与外观 > 主题和就绪提醒中的“发光形状”为同一设置（它也会影响其他提醒的发光）。"
L["The shield button plays a blue effect when your shield fades out of combat. In combat, it pulses red while you have no shield (at 100% Cooldown Bar opacity)."] = "战斗外护盾消失时，护盾按钮播放蓝色效果。战斗中，没有护盾时它会红色脉冲（冷却条不透明度 100% 时）。"
L["The shield button plays this effect in blue when your shield fades."] = "护盾消失时，护盾按钮以蓝色播放此效果。"
L["The shield button. ShamanPower Minimal draws it as a flat box in the shield's color."] = "护盾按钮。ShamanPower Minimal 以护盾颜色将其绘制为扁平方块。"
L["The shield colors everywhere a part has Shield Colors (Use Theme's)."] = "在所有设有“护盾颜色（使用主题的）”的部分使用这些护盾颜色。"
L["The shield count and bar in combat (WoW: Forever)."] = "战斗中的护盾计数与条（WoW: Forever）。"
L["The shield icon. ShamanPower Minimal draws it as a flat box."] = "护盾图标。ShamanPower Minimal 将其绘制为扁平方块。"
L["The shield line on the Compact style: full, low and last charge."] = "紧凑样式上的护盾线：满层、低层与最后一层。"
L["The shield's and the imbue's time left on the bar change color as they run out: the Buff Timers colors on"] = "条上护盾与附魔的剩余时间会随时间流逝而变色：使用“外观 > 颜色与边框”中的“增益计时器”颜色"
L["The shield's and the imbue's time left on the cooldown bar (the same switch as Cooldown Bar > Color the Shield and Imbue Timers)."] = "冷却条上护盾与附魔的剩余时间（与 冷却条 > 为护盾与附魔计时着色 是同一开关）。"
L["The shield's icon with the charge count on it. Grayed out while no shield is up."] = "护盾图标上叠加层数。无护盾时变灰。"
L["The shield's icon, with the number on it."] = "护盾图标，上面带数字。"
L["The shield's time stays out of sight while there is plenty left, and shows the moment it is running out (Running Out At)."] = "护盾剩余充足时隐藏时间，到即将结束的时刻（“即将结束于”）才显示。"
L["The shock the icon shows while your Flame Shock is on that enemy."] = "你的烈焰震击在该敌人身上时，图标显示的震击。"
L["The size of every cooldown number and time left, in one place. Auto keeps each one's usual size."] = "集中设置所有冷却数字与剩余时间的大小。“自动”保持各自原有大小。"
L["The size of its debuff and totem name text."] = "其减益名称和图腾名称文字的大小。"
L["The size of the word WINDFURY!. Its font and outline: Appearance > Fonts & Textures > Windfury Proc."] = "WINDFURY! 字样的字号。字体与描边见 外观 > 字体与材质 > 风怒触发。"
L["The size of this shield's charges: number, icon and charge bar. In Unlock UI, the mouse wheel over its box does the same."] = "此护盾层数的大小：数字、图标与层数条。在“解锁界面”中，在其框体上滚动鼠标滚轮效果相同。"
L["The sound it plays on a proc"] = "触发时播放的音效"
L["The space between the cooldown bar's buttons, in pixels, so glows have room. The same as Button Spacing on Appearance > Cooldown Bar."] = "冷却条按钮之间的间距（像素），为发光留出空间。与外观 > 冷却条中的“按钮间距”相同。"
L["The space between the grid's lines, in steps of 4."] = "网格线之间的间距，以 4 为步进。"
L["The space between the totem bar's buttons, in pixels, so glows have room. The same as Button Spacing on Appearance > Totem Bar."] = "图腾条按钮之间的间距（像素），以便光晕有足够空间。与外观 > 图腾条中的“按钮间距”相同。"
L["The spell icons. ShamanPower Minimal draws them as flat boxes: element spells in their element, others in the logo blue."] = "技能图标。ShamanPower Minimal 将其绘制为扁平方块：元素技能用其元素色，其他用标志蓝色。"
L["The spell's name under the flash."] = "闪烁下方的法术名称。"
L["The strip of charges under the shield button."] = "护盾按钮下方的层数横条。"
L["The sweep and the number while a totem is on cooldown."] = "图腾处于冷却时的扫过效果和数字。"
L["The sweep that shows a totem's next pulse (Tremor, Poison Cleansing ...) and Totem Plates' pulse bar."] = "显示图腾下次脉冲的扫过效果（战栗、清毒术……）以及图腾姓名板的脉冲条。"
L["The swipe settings below show how long your totems have left. "] = "下方的扫描设置会显示你的图腾还剩多久。 "
L["The tank got feared - drop Tremor Totem"] = "坦克被恐惧了 - 快插下战栗图腾"
L["The text alert still shows it.|r"] = "文字提醒仍会显示它。|r"
L["The texture for every bar, unless an area below picks its own."] = "所有条形的材质，除非下方某个区域选择了自己的材质。"
L["The texture for the Cooldown Bar's Shield Charge Bar. Set separately from Bar Texture. Each shield's charges on"] = "冷却条的护盾层数条所用材质。与条材质分开设置。每个护盾的层数显示在"
L["The texture of every bar ShamanPower draws, unless a part picks its own."] = "ShamanPower 绘制的所有条所用的材质，除非某部分单独选择了自己的。"
L["The texture of the charge bar and of the cooldown bar's Shield Charge Bar: its own, it never follows Bar Texture. The same setting as Shield Charge Bars on Appearance > Fonts & Textures."] = "层数条以及冷却条上护盾层数条的材质：它们使用各自的材质，永不跟随“条材质”。与外观 > 字体与材质中的“护盾层数条”为同一设置。"
L["The texture that fills the totem bar's panel (the box behind the totem buttons)."] = "填充图腾条面板（图腾按钮后面的方框）的材质。"
L["The texture that fills the totem bar's panel, the box behind the totem buttons."] = "填充图腾条面板（图腾按钮后方的方框）的材质。"
L["The theme's color."] = "主题的颜色。"
L["The thin line along the top of the Party Strip, in the element color of the buff it watches."] = "小队条顶部的细线，使用所监视增益的元素色。"
L["The time left on Frame Buff Indicators' icons on your party and raid frames."] = "小队与团队框体上框体增益指示图标的剩余时间。"
L["The time left on a buff, a shield, an imbue or a totem changes color as it runs out: the first color while more than half"] = "增益、护盾、附魔或图腾的剩余时间会随耗尽而变色：剩余超过一半时使用第一种颜色，"
L["The time left on the cooldown bar's items. The same setting as the cooldown bar's Time Text Size;"] = "冷却条上各物品的剩余时间。与冷却条的“时间文字大小”为同一设置；"
L["The time left on the duration bars: white, the element color or WoW gold."] = "持续时间条上剩余的时间：白色、元素色或魔兽金色。"
L["The time left on the totem bar's duration bars. The same setting as Time Left Text Size on Totem Bar > Duration Bars;"] = "图腾条持续时间条上的剩余时间。与“图腾条 > 持续时间条”中的“剩余时间文字大小”为同一设置；"
L["The time left, in the middle of the icon."] = "图标中央显示剩余时间。"
L["The time on a button that is running out turns red (gold on a cooldown that is almost ready). On a button"] = "即将结束的按钮上的时间会变红（冷却即将就绪时变金）。在按钮上"
L["The time on the button turns gold over its last seconds (Almost Ready At)."] = "按钮在最后几秒（“即将就绪于”）时间变为金色。"
L["The time on the button turns red while it is running out. On a button that turns red, the time stays white so you can read it."] = "按钮即将结束时，时间变为红色。在本身就会变红的按钮上，时间保持白色以便看清。"
L["The time to a totem's next pulse. The same setting as Pulse Time Text Size on Totem Bar > Duration Bars;"] = "距图腾下次脉冲的时间。与“图腾条 > 持续时间条”中的“脉冲时间文字大小”为同一设置；"
L["The time turns WoW's gold for the buff's last seconds. Never: it stays white."] = "增益最后几秒时间会变为魔兽金色。“永不”：保持白色。"
L["The time-left bar of each weapon imbue. The ShamanPower themes use the element palette."] = "每个武器附魔的剩余时间条。ShamanPower 主题使用元素调色板。"
L["The time-left bar of your shield and Earth Shield."] = "你的护盾与大地之盾的剩余时间条。"
L["The timer bars as they run low. The ShamanPower themes use WoW's green, yellow and red."] = "计时条即将耗尽时的显示。ShamanPower 主题使用魔兽的绿、黄、红。"
L["The totem bar's background and border. The ShamanPower themes use navy."] = "图腾条的背景与边框。ShamanPower 主题使用深蓝色。"
L["The totem bar's buttons, its flyouts, pop-outs and Drop All (ShamanPower Minimal's boxes too). Also on Appearance > Totem Bar."] = "图腾条的按钮、飞出菜单、弹出图标以及“全部插放”（ShamanPower 极简的方块同样适用）。也应用于“外观 > 图腾条”。"
L["The totem bar's panel is tinted by how many of your assigned totems are down: all of them, some of them, or none."] = "图腾条面板会根据你已分配图腾中已插下的数量着色：全部、部分或无。"
L["The totem bar's size, texture, border and layout, the assignments window's size, and both bars' positions. Asks first."] = "图腾条的大小、材质、边框和布局，分配窗口的大小，以及两条的位置。会先询问确认。"
L["The totem bar, the cooldown bar and ShamanPower's panels. Also on Appearance > Colors & Borders (Panel Edge Style) and the Cooldown Bar page."] = "图腾条、冷却条以及 ShamanPower 的面板。也应用于“外观 > 颜色与边框（面板边缘样式）”和“冷却条”页面。"
L["The totem bar: its buttons and the totems in their flyouts, its style and clicks, duration bars, effects and macros."] = "图腾条：其按钮与飞出菜单中的图腾、样式与点击方式、持续时间条、特效与宏。"
L["The totem buttons. ShamanPower Minimal draws them as flat element boxes."] = "图腾按钮。ShamanPower Minimal 将其绘制为扁平的元素方块。"
L["The totem icon on each alert. ShamanPower Minimal draws it as a flat element box."] = "每条提醒上的图腾图标。ShamanPower Minimal 将其绘制为扁平的元素方块。"
L["The totem icon on the Party Strip. ShamanPower Minimal draws it as a flat box."] = "小队条上的图腾图标。ShamanPower Minimal 将其绘制为扁平方块。"
L["The totem pins on the minimap. ShamanPower Minimal draws them as flat boxes (too small for letters: the one-color icon)."] = "小地图上的图腾标记。ShamanPower Minimal 将其绘制为扁平方块（太小放不下字母：使用单色图标）。"
L["The totem plate icons. ShamanPower Minimal draws them as flat boxes."] = "图腾姓名板图标。ShamanPower Minimal 将其绘制为扁平方块。"
L["The totem rings and pins on the minimap."] = "小地图上的图腾环与标记。"
L["The totem to drop, like "] = "要插下的图腾，如 "
L["The totem's icon at the start of the strip. It is grayed out while you have no such totem down."] = "条起始处的图腾图标。当你没有插下该图腾时它会变灰。"
L["The totem's short name under its icon."] = "图标下方的图腾简称。"
L["The totems in each flyout. ShamanPower Minimal draws them as flat element boxes."] = "每个弹出菜单中的图腾。ShamanPower Minimal 将其绘制为扁平的元素方块。"
L["The tracked totems. ShamanPower Minimal draws them as flat boxes."] = "被追踪的图腾。ShamanPower Minimal 将其绘制为扁平方块。"
L["The tracker's background, border and charge count."] = "追踪器的背景、边框与层数计数。"
L["The whole overlay's opacity: its panel, title and icons. Each totem also has its own Opacity in its right-click menu."] = "整个遮罩的透明度：其面板、标题与图标。每个图腾也可在其右键菜单中单独设置透明度。"
L["Their size, as a share of the totem button: at half (50%), two fit across it."] = "大小，以图腾按钮为基准：一半（50%）时，两个并排正好占满。"
L["Theme"] = "主题"
L["Theme Options"] = "主题选项"
L["Theme code"] = "主题代码"
L["Themes"] = "主题"
L["Themes change how ShamanPower looks and nothing else. Pick one, then change any part below."] = "主题只改变 ShamanPower 的外观，不影响其他。选择一个，然后修改下方任意部分。"
L["There is a LOT more in Settings"] = "设置里还有一大堆功能"
L["There is more in Settings"] = "设置里还有更多功能"
L["There is no room beside icons in Grid."] = "网格布局中图标旁边没有空间。"
L["These are this alert's own settings: paste them on another alert."] = "这些是此提醒自己的设置：请粘贴到其他提醒上。"
L["These are this shield's own settings: paste them on another shield."] = "这些是此护盾自身的设置：可将它们粘贴到另一个护盾上。"
L["These buttons also change settings outside this tab. Positions stay where they are."] = "这些按钮还会更改此标签页之外的设置。位置保持不变。"
L["These cooldowns are estimated from the call, not from a confirmed cast."] = "这些冷却时间是根据召唤估算的，而非确认施放后的结果。"
L["These looks are Blizzard's own Maelstrom picture alone. Size and Opacity still apply; pick another Look for the icon's settings."] = "这些外观仅显示暴雪自带的漩涡图片。大小与不透明度仍然有效；选择其他外观可调整图标的设置。"
L["These resets affect more than this tab. Positions are not changed."] = "这些重置会影响本标签页之外的部分。位置不会改变。"
L["These settings also change how the flyouts open."] = "这些设置也会改变弹出栏的展开方式。"
L["These seven totems reach the whole raid. "] = "这七个图腾可覆盖整个团队。 "
L["These spells are on no row, so they are off your screen. |cff3FA9F5DRAG|r one onto a row, or |cff3FA9F5CLICK|r it to put it on the last row. |cff3FA9F5RIGHT-CLICK|r it for its settings."] = "这些技能不在任何行上，因此已移出屏幕。|cff3FA9F5拖动|r 技能到某行，或 |cff3FA9F5点击|r 将其放到最后一行。|cff3FA9F5右键|r 可打开其设置。"
L["These use the colored-border settings on Colors & Borders. Cooldown flyout borders also need the cooldown bar's icon borders."] = "这些会使用“颜色与边框”中的彩色边框设置。冷却弹出栏的边框还需要冷却条的图标边框。"
L["Thick Black"] = "粗黑边"
L["Thick Outline"] = "粗描边"
L["Thin Black"] = "细黑边"
L["Third totem button position"] = "第三个图腾按钮的位置"
L["Third totem to drop"] = "第三个插下的图腾"
L["This alert still uses its original shared settings."] = "此提醒仍在使用最初的共享设置。"
L["This allows you to adjust the overall size of the ShamanPower Buttons"] = "可调整 ShamanPower 按钮的整体大小"
L["This allows you to adjust the overall size of the Totem Assignments Panel"] = "可调整“图腾分配”面板的整体大小"
L["This feature is unavailable, so there is no preview."] = "此功能不可用，因此没有预览。"
L["This icon is on no row. Put it on one (On Row, above) and this copies its settings to that row."] = "此图标不在任何行上。先把它放到某一行（上方“行”），此项即可将其设置复制到该行。"
L["This icon is on no row. Put it on one (On Row, in this icon's menu) and this copies to that row."] = "此图标不在任何行上。先把它放到某一行（此图标菜单中的“行”），此项即可复制到该行。"
L["This icon's effect has no glow, so there is no glow look to set. Pick Glow or Glow + Pulse under "] = "此图标的效果没有光晕，因此没有可设置的光晕外观。请在 "
L["This icon's shape: Square, Flat (the picture's own border removed), Rounded or Circle. Use Shared Shape: the shape every icon shares, set on Appearance > Themes."] = "此图标的形状：方形、扁平（去掉图片自带边框）、圆角或圆形。“使用共享形状”：所有图标共用的形状，在“外观 > 主题”中设置。"
L["This loadout's "] = "此配装的 "
L["This look is the five-part bar alone. Size sets its width; its height is under Stacks > Bar Height."] = "此外观仅显示五段式条。大小决定宽度；高度在“层数 > 条高度”中设置。"
L["This look is the stack count alone. Size sets how big the number is; Opacity still applies."] = "此样式只显示层数。大小决定数字的大小，不透明度仍然生效。"
L["This preview hit an error - please report the message printed in chat."] = "此预览出错——请反馈聊天框中输出的信息。"
L["This row's own settings: its spacing, direction, spot and name."] = "此行自身的设置：间距、方向、位置与名称。"
L["This shield's charge bar and orbs (Shield Icon Orbs keep their icons). Any color you like."] = "此护盾的层数条与宝珠（护盾图标宝珠保留其图标）。任意颜色均可。"
L["This shield's charges already have their usual color."] = "此护盾的层数已使用其惯用颜色。"
L["This shield's charges back to their usual color."] = "此护盾的层数会恢复为通常颜色。"
L["This shield's glow shape (an unset one follows Appearance > Themes' Glow Shape)."] = "此护盾的发光形状（未设置时跟随“外观 > 主题”的发光形状）。"
L["This small WeakAura, installed by the |cffE6EAF0rogues, warriors and paladins|r in your group, quietly tells your addon they have Windfury. "] = "这个小型 WeakAura 由你队伍中的|cffE6EAF0盗贼、战士和圣骑士|r安装，会悄悄告知你的插件他们拥有风怒。 "
L["This totem's own icon size on its plate. The page's Icon Size for the rest."] = "此图腾在其姓名板上的独立图标大小。其余图腾使用本页的图标大小。"
L["This totem's own size in the coverage list while Place Each Totem Freely is on. The other totems keep theirs."] = "在“自由摆放每个图腾”开启时，此图腾在覆盖列表中的独立大小。其他图腾保持各自设置。"
L["This tour skips the features that only shamans can use. Here is what ShamanPower does for you:"] = "本次导览会跳过只有萨满才能使用的功能。以下是 ShamanPower 为你提供的内容："
L["This walkthrough only covered the essentials. The full settings window has far more:"] = "本导览只涵盖了核心内容。完整的设置窗口还有更多："
L["This zone is a:"] = "此区域属于："
L["Three shamans, three Earth Shields. Watch charges get used up, a shield drop off, and its shaman put it back."] = "三个萨满，三个大地之盾。观察层数被消耗、护盾消失，以及对应萨满重新补上。"
L["Tick the specs this icon is for. When you respec into another one it hides by itself, and comes back when"] = "勾选此图标适用的专精。洗点到别的专精时它会自动隐藏，"
