L["Turn it on or off in each kind of place: the open world, dungeons, raids, Battlegrounds and Arenas."] = "在每类场所中开启或关闭它：野外、地下城、团队副本、战场和竞技场。"
L["Turn it on to see the cycle."] = "开启后可查看循环。"
L["Turn loadouts on or off: the loadout bar, the Loadout List and switching when you enter a group's place."] = "开启或关闭配装：包括配装条、配装列表，以及进入队伍所在场所时自动切换。"
L["Turn on Call Flyout on Drop All (just under the Calls) to put your bar on another Call."] = "开启“全部插放时弹出召唤菜单”（就在召唤下方），即可把你的条放到另一个召唤上。"
