L["Turn on Place Each Totem Freely under Behavior to set this totem's size."] = "请在“行为”中开启“自由放置每个图腾”以设置此图腾的大小。"
L["Turn on ShamanPower [Raid Cooldowns] in the AddOns list, then type /reload."] = "请在插件列表中开启 ShamanPower [Raid Cooldowns]（团队冷却），然后输入 /reload。"
L["Turn on Shield Icon to change them."] = "开启“护盾图标”后才能更改它们。"
L["Turn on Show Numbers for Cooldowns"] = "开启冷却数字显示"
L["Turn on Warn When It's Missing to use this. "] = "请先开启“缺失时警告”才能使用此项。 "
L["Turn on colored borders, then choose their thickness and whether the cooldown bar gets them too."] = "开启彩色边框，然后选择其粗细以及冷却条是否也启用。"
