L["Turn one of these on or off by itself in a place or against a boss: in a raid, a dungeon,"] = "在某个地点或针对某个 Boss 单独开启或关闭其中一项：在团队、地下城，"
L["Turn the Cooldown Bar on or off."] = "开启或关闭冷却条。"
L["Turn the Party Buff Tracker on or off: its dots and counters, Coverage and the Party Strip."] = "开启或关闭小队增益追踪：它的圆点与计数、覆盖以及小队条。"
L["Turn the controller bar on or off."] = "开启或关闭手柄条。"
L["Turn the on-screen shield charge numbers on or off."] = "开启或关闭屏幕上的护盾层数数字。"
L["Turn the on-screen shield charges on or off. Off remembers which shields were on; On brings those back."] = "开启或关闭屏幕上的护盾层数。关闭时会记住哪些护盾曾开启；开启时恢复它们。"
L["Turn the totem bar off entirely - for shamans who keybind their totems and only want the cooldown bar. The cooldown bar keeps working on its own."] = "完全关闭图腾条——适合为图腾设置了按键、只需要冷却条的萨满。冷却条会独立继续工作。"
L["Turn this on and ShamanPower sets up WoW's Cooldown Manager to watch them for you, "] = "开启此项后，ShamanPower 会设置 WoW 的冷却管理器为你监视它们，"
L["Turning this on does not make the alerts cast totems."] = "开启此项不会让提醒施放图腾。"
L["Turns Red While Missing"] = "缺失时变红"
L["Turns off every window, bar, icon and nameplate ShamanPower has on this character. It keeps quietly telling your group's shamans whether your weapon has Windfury, so their ShamanPower can show it."] = "关闭 ShamanPower 在此角色上的所有窗口、条、图标和姓名板。它仍会悄然告知队伍中的萨满你的武器是否有风怒，以便他们的 ShamanPower 显示。"
L["Turns on WoW's own cooldown numbers (Options > Action Bars). They then show on your action bars as well."] = "开启魔兽自带的冷却数字（选项 > 动作条）。之后你的动作条上也会显示。"
L["Turns on WoW's own friendly player nameplates and the Minions option under them, so your totems have a nameplate for their icon. Only when you click this, and only out of combat. You can turn them off again in WoW's Options > Gameplay > Nameplates."] = "开启 WoW 自带的友方玩家姓名板及其下的“随从”选项，让你的图腾有姓名板可供显示图标。仅在你点击此项时生效，且仅限战斗外。你可以在 WoW 的选项 > 游戏 > 姓名板中再次关闭。"
L["Turns red"] = "变红"
L["Twist Totem"] = "轮换图腾"
L["Twist totem"] = "轮换图腾"
L["Twisting"] = "图腾轮换"
