L["Under a cell, list only the people who do not have the buff. Off: everyone it watches, in class color when they have it."] = "在格子下方仅列出没有该增益的人。关闭：列出所有被监视者，拥有增益时显示其职业颜色。"
L["Under each alert's totem name, show the key that casts that totem, like Shift-2."] = "在每个提醒的图腾名字下方，显示施放该图腾的按键，例如 Shift-2。"
L["Under each totem, a dot per party member instead of the list of names, like the totem bar's dots: class color with the buff, red without."] = "在每个图腾下方，以每位小队成员一个圆点代替名字列表，类似图腾条上的圆点：有增益时为职业颜色，没有时为红色。"
L["Under the target frame"] = "目标框体下方"
