L["Unlock Bar (move)"] = "解锁条（移动）"
L["Unlock Position"] = "解锁位置"
L["Unlock Positions"] = "解锁位置"
L["Unlock UI"] = "解锁界面"
L["Unlock UI on it: drag it where you want it, then Done. Turn Windfury Proc on first."] = "对它开启「解锁界面」：拖到想要的位置，再点完成。请先启用风怒触发。"
L["Unlock UI with a box for each icon: drag it where you want it, then press Done to come back here."] = "解锁界面，每个图标对应一个框：将它拖到想要的位置，然后点击“完成”返回此处。"
L["Unlock UI with a box for each row: drag it where you want it, then press Done to come back here."] = "解锁界面，每行对应一个框：将它拖到想要的位置，然后点击“完成”返回此处。"
L["Unlock UI with a box for the grid: drag it where you want it, then press Done to come back here."] = "解锁界面，网格对应一个框：将它拖到想要的位置，然后点击“完成”返回此处。"
L["Unlock UI with just the Ready Flash's box: drag it where you want it, then press Done to come back here."] = "只解锁就绪闪烁的框：将它拖到想要的位置，然后点击“完成”返回此处。"
L["Unlocks just Purge's box: drag it where you want it, then press Done to come back here."] = "仅解锁净化的框：将其拖到想要的位置，然后按“完成”返回此处。"
L["Unlocks just the list: drag its box where you want it, then press Done to come back here."] = "仅解锁该列表：将其边框拖到想要的位置，然后按“完成”返回此处。"
L["Unlocks just your debuffs' box: drag it where you want it, then press Done to come back here."] = "仅解锁你的减益框：将其拖到想要的位置，然后按“完成”返回此处。"
L["Unlocks only the Cooldown Bar: drag its box where you want it, then press Done. It can't be done in a fight."] = "仅解锁冷却条：把它的框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only the Earth Shield Tracker: drag its box where you want it, then press Done. It can't be done in a fight."] = "仅解锁大地之盾追踪：把它的框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only the Expiring Alerts: drag their box where you want it, then press Done. It can't be done in a fight."] = "仅解锁到期提醒：把它的框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only the Raid Cooldowns callers: drag its box where you want it, then press Done. It can't be done in a fight."] = "仅解锁团队冷却召唤者：把它的框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only the Reactive Totems alerts: drag each box where you want it, then press Done. It can't be done in a fight."] = "仅解锁应急图腾提醒：将每个方框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only the Ready Check list: drag its box where you want it, then press Done. It can't be done in a fight."] = "仅解锁就绪检查列表：将其方框拖到所需位置，然后点击完成。战斗中无法执行。"
L["Unlocks only the Totem Bar: drag its box where you want it, then press Done. It can't be done in a fight."] = "仅解锁图腾条：将其边框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only the Totem Range Tracker: drag its box where you want it, then press Done. It can't be done in a fight."] = "仅解锁图腾范围追踪：把它的框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only the Tremor Reminder: drag its box where you want it, then press Done. It can't be done in a fight."] = "仅解锁战栗图腾提醒：把它的框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only the controller bar: drag its box where you want it, then press Done. It can't be done in a fight. Turn on the Controller switch first."] = "仅解锁手柄条：将其方框拖到所需位置，然后点击完成。战斗中无法执行。请先开启手柄开关。"
L["Unlocks only the rows: drag each row's box where you want it, then press Done. Right-click a row's box to come back here. It can't be done in a fight."] = "仅解锁各行：把每一行的框拖到想要的位置，然后按“完成”。右键点击行的框可回到此处。战斗中无法操作。"
L["Unlocks only this row's box: drag it where you want it, then press Done."] = "仅解锁此行框体：将其拖到所需位置，然后点击“完成”。"
L["Unlocks only this row: drag its box where you want it, then press Done. It can't be done in a fight."] = "仅解锁此行：把它的框拖到想要的位置，然后按“完成”。战斗中无法操作。"
L["Unlocks only your cooldowns' own frame: drag its box where you want it, then press Done. It can't be done in a fight. Turn on the Controller switch first."] = "仅解锁冷却的独立框架：将其方框拖到所需位置，然后点击完成。战斗中无法执行。请先开启手柄开关。"
L["Up to two small buttons at each element's corners, each dropping a totem of that element in one click. Pick"] = "每个元素的角上最多两个小按钮，单击即可插下该元素的一个图腾。在上方图腾的右键菜单里挑选"
