L["Welcome"] = "欢迎"
L["Welcome to ShamanPower"] = "欢迎使用 ShamanPower"
L["Welcome to WoW: Forever. Some spells are not available here, and a few features work differently."] = "欢迎来到 WoW: Forever。部分技能在此不可用，少数功能的表现也有所不同。"
L["What Drop All and Call of the Elements leave out while this loadout is in use."] = "此配装使用期间，“全部插放”和“元素的召唤”会排除哪些内容。"
L["What You See: each shield's charges as they look on your screen, with its own settings. Click one to watch it use its charges."] = "所见即所得：每个护盾的层数按其在屏幕上的样子显示，并各自拥有设置。点击其中一个可观看其消耗层数。"
L["What a right-click on a totem in the Totem Assignments window does. Previous Totem: it changes to the totem"] = "在“图腾分配”窗口中右键点击图腾的作用。“上一个图腾”：将其切换为图腾"
L["What changed in each version, newest first."] = "各版本的改动内容，最新在前。"
L["What changed in each version, newest first. Click a version to open or close it."] = "各版本的更新内容，最新的在前。点击版本可展开或收起。"
L["What gets out of the way. Each is its own switch: turn one off and it stays on screen."] = "哪些内容会避让。每项都有独立开关：关闭某个开关后，它就会留在屏幕上。"
L["What it does at 5 stacks, while they last: a glow, a pulse, both, or nothing. On Wings and Fill the emblem itself glows or pulses."] = "5 层期间的表现：光晕、脉冲、两者都有，或无。在“双翼”与“填充”外观下，徽记本身会发光或脉冲。"
L["What it shows: the proc's icon, the word WINDFURY!, or both"] = "显示内容：触发的图标、WINDFURY! 字样，或两者都要"
L["What spec are you leveling as?"] = "你在用什么专精升级？"
L["What spec do you play?"] = "你玩什么专精？"
L["What the alert shows when its totem has no key: nothing, or No Key Bound as a reminder to bind one."] = "当图腾没有按键时提醒显示什么：不显示，或显示“未绑定按键”以提醒你绑定。"
L["What the button shows. Next Totem: the icon of the totem it drops next (Call of the Elements when it casts that)."] = "按钮显示的内容。下一个图腾：它接下来要插下的图腾图标（施放元素的召唤时则为该法术）。"
L["What the developer needs to help you: your settings and versions, nothing personal."] = "开发者帮助你所需的信息：你的设置和版本，不涉及任何个人隐私。"
L["What the icon does "] = "图标的作用 "
L["What the icon does at that moment: a glow (its shape and color are under Appearance), a pulse, both, or nothing."] = "图标在该时刻的表现：光晕（形状与颜色在“外观”中）、脉冲、两者都有，或无。"
L["What the icon does the moment its cooldown is reset (a dodge or parry as a tank). The burst is the Proc Glow ring, the word is RESET over the icon."] = "冷却被重置的瞬间图标的表现（例如坦克闪避或招架）。迸发为触发光晕环，文字为图标上方的 RESET。"
L["What the icon does while you don't have the mana for it: a glow, a pulse, both, or nothing."] = "法力不足时图标的表现：光晕、脉冲、两者都有，或无。"
L["What this shield's icon, or its charge bar, does at 0 charges, or with no shield up: a glow, a pulse, both, or nothing."] = "层数为 0 或未开启护盾时，此护盾的图标或层数条的表现：发光、脉冲、两者兼有，或什么都不做。"
