L["Wheel up: previous totem"] = "滚轮上：上一个图腾"
L["When"] = "时机"
L["When Almost Ready, Keep Until Used"] = "即将就绪时，保留至使用"
L["When Almost Ready, Then Hide Once Ready"] = "接近就绪时显示，就绪后隐藏"
L["When Earth Shield counts as running out, for Running Out. It also counts on its last 2 charges."] = "大地之盾从何时起算作即将结束，用于“即将结束”。剩余最后 2 层时也算。"
L["When Hide Out of Combat applies: Hide takes the cooldown bar away, Fade dims it to the Faded Opacity so you can still see and click it."] = "当“战斗外隐藏”生效时：隐藏会移走冷却条，淡出会将其降至“淡出透明度”，以便你仍能看到并点击它。"
L["When It Procs"] = "触发时"
