L["When a Cooldown Is Ready"] = "冷却就绪时"
L["When a Totem Expires"] = "图腾到期时"
L["When a cooldown counts as almost ready (0: only once it is ready, so Cooldown Almost Ready never plays)."] = "冷却从何时算作即将就绪（0：仅在就绪时，因此“冷却即将就绪”永不播放）。"
L["When a cooldown on the bar is ready again, its button plays the style below in gold."] = "条上的冷却重新就绪时，其按钮会以金色播放下方样式。"
L["When a ready check starts, ShamanPower lists what you are missing: your shield, a weapon imbue"] = "就绪检查开始时，ShamanPower 会列出你缺少的内容：你的护盾、武器附魔"
L["When a shield or weapon imbue counts as running out. A shield also counts as running out on its last charge."] = "护盾或武器附魔从何时算作即将结束。护盾在最后一层时也算作即将结束。"
L["When a temporary "] = "当你插下的临时 "
L["When a temporary totem you dropped (like Grounding, Tremor or Mana Tide) ends, that element's button"] = "当你插下的临时图腾（如根基、战栗或法力之潮）结束时，该元素的按钮"
L["When a temporary totem you dropped ends, the element's button lights up until you drop your usual"] = "当你插下的临时图腾结束时，该元素的按钮会亮起，直到你插下常用"
L["When a totem is destroyed, add a line to your own chat window. Only you see it. Works in combat on WoW: Forever too."] = "图腾被摧毁时，在你自己的聊天窗口添加一行。只有你能看到。在 WoW: Forever 上战斗中同样有效。"
L["When a totem is destroyed, say so in party, raid or instance chat so everyone sees it."] = "图腾被摧毁时，在小队、团队或副本聊天中告知，让所有人都能看到。"
L["When a totem is destroyed, show big raid-warning-style text at the top of your screen. Drawn only on your screen; nothing is sent."] = "图腾被摧毁时，在屏幕顶部显示类似团队警告的大字。仅在你的屏幕上绘制，不会发送任何内容。"
L["When a totem is killed before its time, its button plays the style below in red. Your own right-click dismiss, Totemic Call and dying do not count."] = "图腾提前被击杀时，其按钮会以红色播放下方样式。你自己右键取消、图腾召唤以及死亡不计入。"
L["When a totem of this element is destroyed (When One Is Destroyed), and with When One Expires"] = "当此元素的图腾被摧毁时（开启“被摧毁时”时），以及开启“到期时”"
L["When a totem runs out, its button plays the style below in white."] = "图腾到期消失时，其按钮会以白色播放下方样式。"
L["When a weapon imbue drops off (it ran out, or the weapon was swapped), the imbue button plays the style below in blue."] = "武器附魔消失时（到期或更换武器），附魔按钮会以蓝色播放下方样式。"
L["When it counts as almost ready, for Show and for the Cooldown Almost Ready effect. At 0 seconds the Cooldown"] = "何时算作即将就绪，用于“显示”与“冷却即将就绪”效果。为 0 秒时，冷却"
L["When it counts as running out, for Show and for the Running Out effect."] = "何时算作即将结束，用于“显示”与“即将结束”效果。"
L["When it ends, Put Your Usual Totem Back (below) asks for your usual "] = "它结束时，下方的“放回常用图腾”会要求你使用常用的 "
L["When more than one alert shows at once, the second and third stack above the first instead of below it."] = "当同时显示多个提醒时，第二个和第三个会堆叠在第一个上方，而不是下方。"
L["When one of the hide rules above applies: Hide takes the totem bar away, Fade dims it to the Faded Opacity so you can still see and click it."] = "当上述任一隐藏规则生效时：隐藏会移走图腾条，淡出会将其降至“淡出透明度”，以便你仍能看到并点击它。"
L["When the Totem Bar Shows"] = "图腾条显示时机"
L["When the alert shows."] = "提醒出现时。"
