L["When the imbue drops off (it ran out, or you swapped weapons), the button plays this in blue."] = "附魔消失时（耗尽或更换武器），按钮会以蓝色播放此特效。"
L["When the imbue on your "] = "当你的 "
L["When the whole party is getting a totem's buff, its cell disappears; it comes back as soon as someone is out of range."] = "当整个小队都获得某图腾的增益时，它的格子会消失；一旦有人离开范围就会重新出现。"
L["When this shield is gone from you (its last charge used, run out, canceled or replaced). In fights too."] = "当此护盾从你身上消失时（最后一层被消耗、耗尽、取消或被替换）。战斗中同样有效。"
L["When this shield is gone from you. In a fight the game hides your shields from addons,"] = "当此护盾从你身上消失时。战斗中游戏不会向插件显示你的护盾，"
L["When this shield's charges are on screen. Gray: its icon or number grayed out while it's not up."] = "此护盾的层数何时显示在屏幕上。灰色：未生效时其图标或数字变灰。"
L["When this totem ends (while it counts as temporary), its"] = "此图腾结束（当其被计为临时图腾）时，其"
L["When this totem is killed before its time, its button plays the style below in red. Your own right-click dismiss, Totemic Call and dying do not count."] = "此图腾提前被摧毁时，其按钮会以红色播放下方样式。你自己右键取消、图腾召回以及死亡不计入。"
L["When this totem runs out, its button plays the style below in white."] = "此图腾自然结束时，其按钮会以白色播放下方样式。"
L["When this weapon's imbue fades. How loud: the page's Volume."] = "当此武器的附魔消退时。音量：本页的音量设置。"
L["When you come back to life (someone resurrects you, you use Reincarnation, or you release and run back),"] = "当你复活时（他人复活你、你使用复生，或释放灵魂后跑回尸体），"
L["When you drop a different totem than assigned, show it on the main button and your assigned totem in the corner. By default, the dropped totem appears above the button. Turning this on turns Compact Style off."] = "当你插下与分配不同的图腾时，在主按钮上显示它，并在角落显示你分配的图腾。默认情况下，已插下的图腾显示在按钮上方。开启此项会关闭紧凑样式。"
L["When you enter this group's place, switch to its first loadout once (a fight first: when it ends)."] = "当你进入该分组的区域时，切换到它的第一个配装一次（若正在战斗，则在战斗结束时切换）。"
L["When you level up, ShamanPower lists the shaman spells and ranks now waiting at your trainer. Only you see it."] = "当你升级时，ShamanPower 会列出训练师处可学的新萨满法术和等级。只有你自己能看到。"
L["When your Earth Shield is gone from the player you put it on (its last charge used or run out), with their name."] = "当你放在目标玩家身上的大地之盾消失时（最后一层被消耗或耗尽）提醒，并显示其名字。"
L["When your Earth Shield is gone from the player you put it on. The same setting as Earth Shield's sound in Expiring Alerts."] = "当你施加的大地之盾从目标玩家身上消失时。与“到期提醒”中大地之盾的音效为同一设置。"
L["When your Earth Shield's charges are on screen. It's up while it is on someone (the player you put it on)."] = "你的大地之盾层数何时显示在屏幕上。当它覆盖在某人身上（你施放的目标）时就会显示。"
L["When your Flame Shock on that enemy has this many seconds left, the icon shows Flame Shock again,"] = "当该敌人身上你的烈焰震击剩余这么多秒时，图标会重新显示烈焰震击，"
L["Whenever your totem"] = "每当你的图腾"
L["Whenever your totem assignments change, the four totems in Call of the Elements are updated to match (out of"] = "每当你的图腾分配变化时，“元素的召唤”中的四个图腾都会随之更新（不包含"
L["Where"] = "何处"
L["Where "] = "设置 "
L["Where Flame Shock, Frost Shock and Stormstrike show while they are on your target: a spot you place"] = "当烈焰震击、冰霜震击和风暴打击存在于你的目标身上时显示的位置：你放置的一个点"
L["Where Purge shows: a spot you place on your screen (Move Purge on this page), on your target's"] = "净化的显示位置：你在屏幕上放置的位置（本页的“移动净化”）、你目标的"
L["Where Your Debuffs Show"] = "减益显示位置"
L["Where a row that is not full sits: packed to the left, centered, or packed to the right. Left keeps every icon still as new ones join; Center and Right shift the row to make room."] = "未填满的行如何摆放：靠左、居中或靠右。靠左时新增图标不会挪动已有图标；居中与靠右会移动整行以腾出空间。"
L["Where is this group for?"] = "这个分组适用于哪里？"
L["Where on the frame it sits: a corner, an edge or the middle. WoW's own buffs sit at the bottom right."] = "在框体上的位置：角落、边或正中。WoW 自带的增益在右下角。"
L["Where the bar sits: under, over or beside the icon or number. Vertical bars fill from the bottom."] = "条的位置：图标或数字的下方、上方或旁边。垂直条从底部开始填充。"
L["Where the buff shows while it's on you. Replace Spell Icon: the buff's own picture takes this icon's place while it's on. It stays on screen while this icon hides between casts, except as an edge or a replacement (they need the icon) and in a grid (there a hidden icon's place goes to the next icon; Separate Position still stays). In a grid its own icon goes Separate Position, since next to this icon is the next icon. Off: nothing changes."] = "增益在你身上时显示于何处。“替换技能图标”：增益自带图片会顶替此图标显示。此图标在两次施放之间隐藏时，增益仍留在屏幕上，但“边框”与“替换”除外（它们需要该图标），网格布局中也除外（此时隐藏图标的位置会被下一个图标占用；“独立位置”仍然保留）。在网格中，增益的独立图标会使用“独立位置”，因为此图标旁边就是下一个图标。关闭：不做任何改变。"
L["Where the buff's own icon goes: next to this icon, or Separate Position, anywhere on your screen (Move This Buff places it). In a separate position it shows even with this icon hidden."] = "增益独立图标的位置：此图标旁边，或屏幕任意处的“独立位置”（由“移动此增益”放置）。处于独立位置时，即使此图标隐藏也会显示。"
L["Where the color starts returning as the cooldown runs out."] = "冷却结束时颜色从何处开始回填。"
L["Where the dots sit on each totem icon. Rows suit a horizontal layout; columns suit a vertical one."] = "圆点在每个图腾图标上的位置。行适合水平布局；列适合垂直布局。"
L["Where the flyout opens while the bar is horizontal."] = "条为水平时，飞出菜单的展开位置。"
L["Where the gradient starts on "] = "渐变开始绘制的位置："
L["Where the gradient starts on screen."] = "渐变在屏幕上的起始位置。"
L["Where the gradient starts on the cooldown bar's progress bars. Along the Bar follows each bar. Shown when Bar Gradient (Totem Bar > Duration Bars or Appearance > Themes) is not Flat."] = "冷却条进度条上渐变的起始位置。“沿条”会跟随各条的方向。当“条渐变”（图腾条 > 持续时间条 或 外观 > 主题）不是“扁平”时显示。"
L["Where the gradient starts. Along the Bar follows each bar: left to right, or bottom to top on a vertical bar. The others are the same on every bar."] = "渐变的起始位置。“沿条”会跟随各条：水平条从左到右，垂直条从下到上。其他选项在所有条上一致。"
L["Where the gradient starts. Along the Bar follows each bar: left to right, or bottom to top on a vertical bar. The others are the same on every bar. The same setting as on Appearance > Themes."] = "渐变的起始方向。“沿条”会跟随每条的方向：从左到右，垂直条上则从下到上；其他选项在所有条上一致。与“外观 > 主题”中的设置为同一项。"
L["Where the gradient starts: from the top edge down by default, or from the bottom, the left or the right."] = "渐变的起始位置：默认从上边缘向下，也可从下、左或右开始。"
L["Where the gradient starts: from the top edge down by default, or from the bottom, the left or the right. The same setting as on Appearance > Themes."] = "渐变的起始方向：默认从顶部边缘向下，也可从底部、左侧或右侧开始。与“外观 > 主题”中的设置为同一项。"
L["Where the gray (Grays Out) or color (Fills Back In) starts."] = "灰色（变灰）或颜色（回填）开始的位置。"
L["Where the gray (Grays Out) or color (Fills Back In) starts. With Clock Sweep, this only changes weapon imbues, which keep Vertical - Grays Out."] = "灰色（变灰）或颜色（回填）的起始位置。使用时钟扫过时，这只影响武器附魔，它们保持“垂直 - 变灰”。"
L["Where the gray (Grays Out) or color (Fills Back In) starts: From The Top or From The Bottom."] = "灰色（“逐渐变灰”）或彩色（“逐渐恢复”）的起点：从顶部或从底部。"
L["Where the gray (Grays Out) or the color (Fills Back In) starts."] = "灰色（变灰）或颜色（回填）开始的位置。"
L["Where the gray starts for Grays Out, or the color starts for Fills Back In."] = "“变灰”时灰色开始的位置，或“回填”时颜色开始的位置。"
L["Where the icon sits on the totem's nameplate: above the totem (as before), or to its left or right."] = "图标在图腾姓名板上的位置：图腾上方（与之前相同），或其左侧或右侧。"
L["Where the indicator for a dropped, non-assigned totem"] = "已插下但未分配的图腾指示器"
L["Where the number sits on the icon."] = "数字在图标上的位置。"
L["Where the number sits on the icon: large in the center, or smaller in the bottom-right corner."] = "数字在图标上的位置：居中的大字，或右下角的小字。"
L["Where the overlay may be up, whether it opened by itself or you opened it."] = "覆盖层可在哪些场合显示，无论是自动打开还是你手动打开。"
L["Where the party dots sit on each totem button. Rows suit a horizontal bar; columns suit a vertical bar."] = "小队圆点显示在每个图腾按钮上的位置。横向排列适合水平图腾条，纵向排列适合垂直图腾条。"
L["Where this spell's flash plays: the shared spot, or a spot of its own (Unlock UI opens with its box; drop it where you want it)."] = "此技能闪烁的显示位置：共享位置，或独立位置（会以它的框打开解锁界面；把它放到想要的位置）。"
L["Where this totem button's flyout opens."] = "此图腾按钮的弹出菜单打开位置。"
L["Where this totem's flyout opens."] = "此图腾弹出列表的展开方向。"
L["Where to display the range counter numbers"] = "范围计数器数字的显示位置"
L["Where to show the remaining duration time"] = "剩余持续时间的显示位置"
L["Where to show the remaining totem duration time"] = "显示图腾剩余持续时间的位置"
L["Where to show the time until next pulse"] = "显示距下次脉冲剩余时间的位置"
L["Where your debuffs sit on a nameplate: your target's, and every enemy's for the spells with Show On"] = "你的减益在姓名板上的位置：目标姓名板，以及启用了“显示于”的法术对应的每个敌人姓名板"
L["Which bar you play with: one of the four looks of ShamanPower's bar, every totem laid out in a grid"] = "你使用哪种条：ShamanPower 图腾条的四种外观之一，所有图腾以网格排列"
L["Which button sits in position "] = "哪个按钮位于第 "
L["Which corner of this icon the buff sits in."] = "增益显示在此图标的哪个角落。"
L["Which effect each item plays, and when: right-click the item, then Effects."] = "每个项目播放哪个效果以及何时播放：右键点击该项目，然后选择“效果”。"
L["Which features you use, so the developer knows what matters. Nothing personal."] = "你使用了哪些功能，以便开发者了解重点。不涉及任何个人隐私。"
L["Which key the buttons show when a spell is bound in two places. Action Bar Key First: the key from your action bars, else ShamanPower's own. ShamanPower Key First: ShamanPower's own binding, else the action bar key. ShamanPower Key Only: only ShamanPower's own bindings (the flyout icons, which have none, then show no key)."] = "当一个法术在两处绑定了按键时，按钮显示哪一个。优先动作条按键：使用动作条上的按键，否则使用 ShamanPower 自身的。优先 ShamanPower 按键：使用 ShamanPower 自身的绑定，否则使用动作条按键。仅 ShamanPower 按键：只显示 ShamanPower 自身的绑定（弹出菜单图标没有绑定，因此不显示按键）。"
L["Which totems count as temporary (Tremor, Grounding, Mana Tide...): right-click a totem on Totem Bar > Bar,"] = "哪些图腾算作临时图腾（战栗、根基、法力之潮……）：在“图腾条 > 条”中右键点击图腾，"
L["Which totems get the pulse bar and the pulse flash: right-click a totem on Totem Bar > Bar, then Pulse Bar"] = "哪些图腾显示脉动条和脉动闪光：在图腾条 > 条中右键点击图腾，然后选择“脉动条”"
L["While Flame Shock Is Active"] = "烈焰震击激活时"
L["While Flyout Requires Right-Click is on: right-click opens the flyout and shift+right-click pulls just that totem back. With Swap Left and Right Click on, it is left-click and shift+left-click."] = "当“弹出菜单需右键打开”开启时：右击打开弹出菜单，Shift+右击只收回该图腾。开启“交换左右键”后，则为左击和 Shift+左击。"
L["While Holding"] = "持续期间"
L["While Imbue Is Missing"] = "缺少附魔时"
L["While It's On You"] = "持续期间"
L["While Shield Is Active"] = "护盾生效时"
L["While Shield Is Missing"] = "护盾缺失期间"
L["While Totem Is Down"] = "图腾插下期间"
L["While You Have Stacks"] = "拥有层数时"
L["While You Have Stacks: from the first stack until you spend them. Only At 5 Stacks: only when your next spell is instant. Always: 0 stacks too, dimmed."] = "拥有层数时：从第一层到层数耗尽。仅在 5 层时：只在下一次施法为瞬发时。始终：0 层也显示，变暗。"
L["While a weapon imbue is gone, the button turns red until you imbue again (with two weapons: either hand)."] = "武器附魔消失期间，按钮会变红，直到你重新附魔（双武器：任一只手）。"
L["While a weapon imbue is gone, the button's edges glow red until you imbue again (with two weapons: either hand)."] = "武器附魔消失期间，按钮边缘会发红光，直到你重新附魔（双武器：任一只手）。"
L["While the controller bar shows, your normal totem bar hides: they are the same buttons. Your totem keys and the controller bar keep working while it is hidden. It hides and comes back out of a fight only."] = "手柄条显示时，常规图腾条会隐藏：它们是同一组按钮。隐藏期间你的图腾按键与手柄条仍可正常使用。隐藏与恢复仅在非战斗时生效。"
L["While you don't have the mana for it, the icon takes the color below. While your target is out of range, the Out of Range look shows instead."] = "法力不足时图标变为下方颜色。目标超出范围时，则改为显示“超出范围”外观。"
