L["While you or a party member is feared, charmed or horrified."] = "当你或小队成员被恐惧、魅惑或惊骇时。"
L["While you use ShamanPower's bar, keep Blizzard's own totem bar hidden so you do not get two. It still shows in Edit Mode. Turn this off to keep both."] = "使用 ShamanPower 的图腾条时，保持 Blizzard 自带图腾条隐藏，以免出现两条。编辑模式下仍会显示。关闭此项可保留两者。"
L["While you're targeting an enemy without your "] = "当你选中的敌人身上没有你的 "
L["While your Flame Shock is on an enemy, its Flame Shock icon shows "] = "当你的烈焰震击在敌人身上时，其烈焰震击图标会改为显示 "
L["While your cooldowns show in the controller look, your normal cooldown bar hides: they are the same buttons. Your cooldown keys and these slots keep working while it is hidden. It hides and comes back out of a fight only."] = "当冷却以手柄外观显示时，常规冷却条会隐藏：它们是同一组按钮。隐藏期间你的冷却按键与这些栏位仍可正常使用。隐藏与恢复仅在非战斗时生效。"
L["While your shield is gone, the button turns red until you cast it again."] = "护盾消失期间，按钮会变红，直到你再次施放。"
L["While your shield is gone, the button's edges glow red until you cast it again."] = "护盾消失期间，按钮边缘会发红光，直到你再次施放。"
L["While your shield or a weapon imbue is gone, its button turns red until you cast it again (with two weapons: either hand)."] = "当你的护盾或武器附魔消失时，其按钮会变红，直到你重新施放（双武器时：任意一只手）。"
L["While your shield or a weapon imbue is gone, the button's edges glow red until you cast it again (with two weapons: either hand). With Proc Glow as your Glow Shape, that plays round the button too."] = "当你的护盾或武器附魔消失时，按钮边缘会发出红光，直到你重新施放（双武器时：任意一只手）。若“发光形状”为“触发发光”，该效果也会环绕按钮播放。"
