L["Wings, Fill and Charge Bar Only are three icons wide, so they sit on a spot of their own, never on a row. Not On A Row: off your screen (drag it down to Not On A Row, or back up, on the Spells row too)."] = "“双翼”“填充”与“仅层数条”宽达三个图标，因此占据独立位置，不会出现在行中。“不在行中”：移出屏幕（可把它拖到“不在行中”，或拖回上方，技能行同样如此）。"
L["With Rounded or Circle icons, borders (Element-Colored Borders, Ready Reminders' border) follow the shape. Turn this on to keep them square. One setting for every bar (and on Appearance > Themes)."] = "使用圆角或圆形图标时，边框（元素色边框、就绪提醒的边框）会跟随该形状。开启此项可保持方形。所有条共用一项设置（外观 > 主题中也有）。"
L["With Rounded or Circle icons, borders (the element-colored borders, Ready Reminders' border) follow the shape. Turn this on to keep them square. One setting for every bar. The same setting as Keep Borders Square on Appearance > Themes and on the Cooldown Bar page."] = "使用圆角或圆形图标时，边框（元素色边框、就绪提醒的边框）会跟随形状。开启此项可保持为方形。所有条共用一项设置。与外观 > 主题页和冷却条页面中的“保持边框为方形”为同一设置。"
L["With more than one totem, each line starts with its totem's icon so you can tell them apart. An"] = "有多个图腾时，每行以其图腾图标开头，便于区分。一个"
