L["WoW's Cooldown Manager isn't available on this character or realm, so ShamanPower can't tell when your Lightning Shield or Water Shield falls off during a fight. Out of a fight it still can, and every other shield feature works as usual."] = "此角色或服务器无法使用 WoW 的冷却管理器，因此 ShamanPower 无法在战斗中判断你的闪电之盾或水之盾何时消失。非战斗时仍可判断，其他护盾功能也照常工作。"
