L["\n\226\128\162 Adds Maelstrom Weapon to your ShamanPower layout in Cooldown Manager"] = "\n\226\128\162 把漩涡武器加入你在冷却管理器中的 ShamanPower 布局"
L["\n\226\128\162 Adds a ShamanPower layout to Cooldown Manager that tracks Lightning Shield, Water Shield and Maelstrom Weapon"] = "\n\226\128\162 在冷却管理器中添加一个 ShamanPower 布局，追踪闪电之盾、水之护盾与漩涡武器"
L["\n\226\128\162 Adds a ShamanPower layout to Cooldown Manager that tracks only Lightning Shield and Water Shield"] = "\n\226\128\162 为冷却管理器添加一个 ShamanPower 布局，仅追踪闪电之盾和水之盾"
L["\n\226\128\162 Hides WoW's own Maelstrom Weapon icon, so you don't see it twice"] = "\n\226\128\162 隐藏 WoW 自带的漩涡武器图标，避免重复显示"
L["\n\226\128\162 Hides WoW's own shield icon, so you don't see it twice"] = "\n\226\128\162 隐藏 WoW 自带的护盾图标，避免你看到两次"
L["\n\226\128\162 Makes sure WoW's Tracked Buffs bar isn't hidden in Edit Mode"] = "\n\226\128\162 确保 WoW 的“已追踪增益”条在编辑模式下不会被隐藏"
L["\n\226\128\162 Reloads your UI"] = "\n\226\128\162 重新加载你的界面"
L["\n\226\128\162 Turns on WoW's Cooldown Manager if it's off"] = "\n\226\128\162 在未开启时开启 WoW 的冷却管理器"
L["\n\nIn a fight it shows the moment your shield is gone once ShamanPower's Cooldown Manager setup is done (Shield Charges > Set Up The Cooldown Manager). Without it, it shows when the fight ends."] = "\n\n完成 ShamanPower 的冷却管理器设置后（护盾层数 > 设置冷却管理器），战斗中护盾一消失就会显示。未完成设置时，则在战斗结束后显示。"
L["\n\nInside dungeons and raids, WoW: Forever hides mob names, so there only boss fights bring it up."] = "\n\n在副本与团队中，WoW: Forever 会隐藏怪物名称，所以那里只有 Boss 战才会触发。"
L["\n\nPrefer the old look? Turn on Use the Old Settings Look in General, or press Use the Old Look below."] = "\n\n更喜欢旧外观？在“通用”中开启“使用旧版设置外观”，或点击下方的“使用旧外观”。"
L["\n\nThe |cff3FA9F5Set It Up|r Button does this once for you:"] = "\n\n|cff3FA9F5一键设置|r按钮会为你执行一次以下操作："
L["\n\nThis is the heads-up before a fear lands. Reactive Totems is the other way around: it reacts after someone is already feared, poisoned or diseased."] = "\n\n这是恐惧落地之前的提前提醒。应急图腾正好相反：它是在有人已经被恐惧、中毒或染病之后才反应。"
L["\n\nTurn on |cff00ff00ShamanPower [Totem Plates]|r in the AddOns list to use this feature.\n"] = "\n\n在插件列表中开启 |cff00ff00ShamanPower [Totem Plates]|r 即可使用此功能。\n"
L["\n\nTurn on |cff00ff00ShamanPower [Tremor Reminder]|r in the AddOns list to use this feature.\n"] = "\n\n请在插件列表中开启 |cff00ff00ShamanPower [战栗图腾提醒]|r 以使用此功能。\n"
L["\n\nYour other Cooldown Manager layouts stay saved."] = "\n\n你的其他冷却管理器布局仍会保留。"
L["\n\n|cffffa040Reload to use the new flyout style.|r"] = "\n\n|cffffa040重新加载以使用新的弹出菜单样式。|r"
