L["|cff3FA9F5CLICK|r a spell to show or hide it. |cff3FA9F5RIGHT-CLICK|r it to set it up: when and where it shows, how it"] = "|cff3FA9F5点击|r 法术可显示或隐藏它。|cff3FA9F5右键|r 点击可进行设置：显示时机与位置、它的"
L["|cff3FA9F5CLICK|r a totem to pick another for its Call, or a Call to put your bar on it (the green"] = "|cff3FA9F5点击|r 图腾可为其召唤另选一个，或点击召唤把你的条放上去（绿色的"
L["|cff3FA9F5CLICK|r a totem to show or hide it in its flyout. |cff3FA9F5RIGHT-CLICK|r it for its settings."] = "|cff3FA9F5点击|r 图腾可将其在弹出菜单中显示或隐藏。|cff3FA9F5右键|r 打开其设置。"
L["|cff3FA9F5CLICK|r a totem to show or hide it on the strip. A blue corner: it's on the strip. |cff3FA9F5Dark|r: you"] = "|cff3FA9F5点击|r图腾可在条上显示或隐藏它。蓝色角标：它已在条上。|cff3FA9F5暗色|r：你"
L["|cff3FA9F5CLICK|r an alert to turn it on or off. |cff3FA9F5RIGHT-CLICK|r it for its settings:"] = "|cff3FA9F5点击|r 提醒可开启或关闭。|cff3FA9F5右键点击|r 可打开其设置："
L["|cff3FA9F5CLICK|r an item to show or hide it on the bar. |cff3FA9F5RIGHT-CLICK|r it for its settings."] = "|cff3FA9F5点击|r 项目可在条上显示或隐藏。|cff3FA9F5右键点击|r 可打开其设置。"
L["|cff3FA9F5DRAG|r a spell onto a row, between rows, or down to Not On A Row to take it off your screen. |cff3FA9F5CLICK|r a spell to show or hide it."] = "|cff3FA9F5拖动|r 技能到某行、行与行之间，或拖到“不在行中”以移出屏幕。|cff3FA9F5点击|r 技能可显示或隐藏。"
L["|cff3FA9F5Out of the way|r "] = "|cff3FA9F5避让|r "
L["|cff3FA9F5RIGHT-CLICK|r Drop All for its drop order and Blizzard Totem Sets. You use Blizzard's"] = "|cff3FA9F5右键|r“全部插放”可设置插放顺序与暴雪图腾组。你使用的是暴雪的"
L["|cff3FA9F5RIGHT-CLICK|r a totem for its settings. Blizzard's Totem Bar shows its own flyouts,"] = "|cff3FA9F5右键|r 图腾可打开其设置。暴雪图腾条会显示自己的弹出菜单，"
L["|cff3FA9F5ShamanPower's own bar: just hover.|r By default, hovering any totem opens its flyout, in combat too, with no arrow to click (Totem Bar > Clicks can change that). Left-click drops that totem, right-click makes it the assigned one."] = "|cff3FA9F5ShamanPower 自己的条：只需悬停。|r 默认情况下，悬停任意图腾即可打开其飞出菜单，战斗中也是如此，无需点击箭头（图腾条 > 点击 可更改）。左键点击插下该图腾，右键点击将其设为分配图腾。"
L["|cff3FA9F5WHAT'S IN IT|r\n"] = "|cff3FA9F5包含哪些内容|r\n"
L["|cff40ff40in|r"] = "|cff40ff40内|r"
L["|cff40ff40on|r"] = "|cff40ff40开|r"
L["|cff5865F2Join the ShamanPower Discord|r for help, bug reports, ideas and early builds."] = "|cff5865F2加入 ShamanPower Discord|r 获取帮助、报告问题、提出建议并获取抢先版本。"
L["|cff69CCF0Mages|r"] = "|cff69CCF0法师|r"
L["|cff8090a0off|r"] = "|cff8090a0关|r"
L["|cff87CEEBAir Totems|r"] = "|cff87CEEB风图腾|r"
L["|cff888888Compact style draws duration and pulse itself, so the Duration Bars page and the totem cooldown sweep do not apply while it is on. Button Spacing sets the gap between lines. Party dots and the range counter sit at the far end of each line.|r"] = "|cff888888紧凑样式自行绘制持续时间与脉冲，因此开启期间“持续时间条”页面和图腾冷却扫过不适用。按钮间距设置行与行之间的间隙。小队圆点与范围计数位于每行的最末端。|r"
L["|cff888888Must have Dialog sound at 100% for this slider to work.|r"] = "|cff888888对话音量需为 100%，此滑块才会生效。|r"
L["|cff888888Only show these players in the Earth Shield flyout. Roles use the built-in group roles (raid Main Tanks count as Tanks). Selections combine: a player shows if their role OR class is picked. Nothing selected = everyone. Your assigned target is always shown.|r"] = "|cff888888只在大地之盾弹出栏中显示这些玩家。角色使用内置的队伍角色（团队主坦克视为坦克）。选择会合并：只要玩家的角色或职业被选中就会显示。未选择任何项 = 所有人。你指定的目标始终显示。|r"
L["|cff888888Recalls all active totems|r"] = "|cff888888召回所有已激活的图腾|r"
L["|cff888888Set WoW's Dialog volume to 100% to use this volume slider.|r"] = "|cff888888将 WoW 的对话音量设为 100% 才能使用此音量滑块。|r"
L["|cff888888Single Totem: the button shows whatever totem is down, one per slot, but your assignments never change. A click always drops your assigned totem, and the button goes back to it the moment the dropped totem is gone. Right-click a totem in the flyout to change the assignment.|r"] = "|cff888888单一图腾：按钮显示当前插下的任意图腾，每个槽位一个，但你的分配永不改变。点击始终插下你分配的图腾，已插下的图腾一消失，按钮便恢复为它。右键点击弹出栏中的图腾以更改分配。|r"
L["|cff888888When enabled: Middle-click any totem button, cooldown bar item"] = "|cff888888启用后：中键点击任意图腾按钮、冷却条项目"
L["|cff888888empty|r"] = "|cff888888空|r"
L["|cff8A94A6No one|r"] = "|cff8A94A6无人|r"
L["|cff8A94A6None|r"] = "|cff8A94A6无|r"
L["|cff8B4513Earth Totems|r"] = "|cff8B4513地图腾|r"
L["|cff9482C9Warlocks|r"] = "|cff9482C9术士|r"
L["|cff9aa4b1Move each row where you want it with Unlock UI.|r"] = "|cff9aa4b1用“解锁界面”将每一行移到你想要的位置。|r"
L["|cffABD473Hunters|r"] = "|cffABD473猎人|r"
L["|cffC79C6EWarriors|r"] = "|cffC79C6E战士|r"
L["|cffF58CBAPaladins|r"] = "|cffF58CBA圣骑士|r"
L["|cffFF4500Fire Totems|r"] = "|cffFF4500火图腾|r"
L["|cffFF7D0ADruids|r"] = "|cffFF7D0A德鲁伊|r"
L["|cffFFB000Friendly totems do NOT show inside dungeons or raids|r (the game hides those nameplates there). Enemy totems work everywhere."] = "|cffFFB000友方图腾不会在地下城或团队副本中显示|r（游戏在那里隐藏了这些姓名板）。敌方图腾在所有地方都有效。"
L["|cffFFB000Inside dungeons and raids the game hides which totem is which|r, so no icons show there, enemy or friendly: you see WoW's own nameplates instead."] = "|cffFFB000在地下城和团队副本中，游戏会隐藏图腾的具体种类|r，因此那里不显示图标，无论敌方还是友方：你看到的将是 WoW 自带的姓名板。"
L["|cffFFB000THIS IS FOR YOUR MELEE - NOT FOR YOU|r"] = "|cffFFB000这是发给你的近战的——不是给你自己的|r"
L["|cffFFD100PRACTICE|r - "] = "|cffFFD100练习|r - "
L["|cffFFD100PRACTICE|r request from "] = "|cffFFD100练习|r 请求来自 "
L["|cffFFF569Rogues|r"] = "|cffFFF569潜行者|r"
L["|cffa0a0a0Played on ShamanPower's own totem buttons: not with the Compact, Grid or Blizzard's Totem Bar styles.|r"] = "|cffa0a0a0在 ShamanPower 自带的图腾按钮上播放：紧凑、网格或暴雪图腾条样式下不播放。|r"
L["|cffa0a0a0Shows on ShamanPower's own totem buttons and Compact lines, and on your usual totem in its"] = "|cffa0a0a0显示在 ShamanPower 自己的图腾按钮与紧凑样式线条上，以及你的常用图腾所在的"
L["|cffff5050out|r"] = "|cffff5050外|r"
L["|cffffa040Air is set to Empty, so Drop All already skips it. This setting applies once you assign an Air totem.|r"] = "|cffffa040空气已设为“空”，因此全部插放会跳过它。此设置在你分配空气图腾后生效。|r"
L["|cffffa040Alerts work in combat. They show the player's name, the debuff's icon and the time left, not the debuff's name. The Fear alert is for you only, while you are feared, charmed or asleep. Sounds only play out of combat.|r"] = "|cffffa040提醒在战斗中有效。它们显示玩家名字、减益图标和剩余时间，而不显示减益名称。恐惧提醒仅针对你自己，在你被恐惧、魅惑或睡眠时触发。音效仅在战斗外播放。|r"
L["|cffffa040At 0 seconds the Cooldown Almost Ready effect never plays. Raise Seconds Before a Cooldown Is Ready to see it.|r"] = "|cffffa040设为 0 秒时“冷却即将就绪”效果永不播放。请提高“冷却就绪前的秒数”以查看该效果。|r"
L["|cffffa040Automatic replies may not work in dungeons and raids. Announcements stop while the game blocks chat.|r"] = "|cffffa040自动回复在地下城和团队中可能无效。游戏屏蔽聊天期间通告会停止。|r"
L["|cffffa040Blizzard controls the layout, visibility and flyouts. ShamanPower adds icon styles, duration bars, text, "] = "|cffffa040暴雪控制布局、可见性和弹出菜单。ShamanPower 添加图标样式、持续时间条、文字、 "
L["|cffffa040Blizzard's Totem Bar is on. It has no ShamanPower panel, so these are not shown.|r"] = "|cffffa040Blizzard 图腾条已开启。它没有 ShamanPower 面板，因此不显示这些内容。|r"
L["|cffffa040Blizzard's bar keeps its own layout: move it with Edit Mode. Size is relative to Blizzard's normal size.|r"] = "|cffffa040Blizzard 的条保持其自身布局：用编辑模式移动它。大小相对于 Blizzard 的常规尺寸。|r"
L["|cffffa040Blizzard's totem sets: each loadout can be put on Call of the Ancestors (learned at level 30) or Call of the Spirits (level 40) in its menu (right-click it > Blizzard Totem Set), once your character knows one of them. Call of the Elements follows your assignments while Call of the Elements Follows My Assignments is on.|r"] = "|cffffa040Blizzard 的图腾组合：每个配装可在其菜单中（右键点击 > Blizzard 图腾组合）放到先祖的召唤（30 级学习）或灵魂的召唤（40 级）上，前提是你的角色已学会其中之一。开启“元素的召唤跟随我的分配”时，元素的召唤会跟随你的分配。|r"
L["|cffffa040Both displays are turned off, so scale, opacity, lock and the hide options have nothing to act on.|r"] = "|cffffa040两个显示都已关闭，因此缩放、不透明度、锁定和隐藏选项均不起作用。|r"
L["|cffffa040Caller buttons only appear in a group, and only when you are an assigned caller (or raid lead / assist). Solo there is nothing on screen for the button settings to change. /spraid opens the assignments.|r"] = "|cffffa040召唤按钮仅当处于队伍或团队中、且你是指定的召唤者（或团队领袖/助理）时才显示。单独一人时，按钮设置没有任何可改之处。/spraid 可打开分配界面。|r"
L["|cffffa040Compact style draws its own duration and pulse. This page does not change its lines"] = "|cffffa040紧凑样式自行绘制持续时间和脉冲。此页面不会改变其线条"
L["|cffffa040Counters keep their last positions. Use Move to place them.|r"] = "|cffffa040计数会保留上次的位置。使用“移动”来放置它们。|r"
L["|cffffa040Dropped Totems has no panel, so these are not shown while it is on.|r"] = "|cffffa040已插下图腾没有面板，因此开启期间不显示这些内容。|r"
L["|cffffa040Earth is set to Empty, so Drop All already skips it. This setting applies once you assign an Earth totem.|r"] = "|cffffa040大地已设为“空”，因此全部插放会跳过它。此设置在你分配大地图腾后生效。|r"
L["|cffffa040Expiring Alerts is off, including Test Alerts.|r"] = "|cffffa040“到期提醒”已关闭，包括测试提醒。|r"
L["|cffffa040Fire is set to Empty, so Drop All already skips it. This setting applies once you assign a Fire totem.|r"] = "|cffffa040火焰已设为“空”，因此全部插放会跳过它。此设置在你分配火焰图腾后生效。|r"
L["|cffffa040Hide Background and Border is on, so the panel's texture and colors are not shown.|r"] = "|cffffa040“隐藏背景与边框”已开启，因此不显示面板的材质与颜色。|r"
L["|cffffa040Hide When No Totems is on: when your temporary totem was the only totem down, the bar"] = "|cffffa040已开启“无图腾时隐藏”：当你的临时图腾是唯一插下的图腾时，图腾条"
L["|cffffa040Pick a totem above to show the strip.|r"] = "|cffffa040请在上方选择一个图腾以显示条带。|r"
L["|cffffa040Quick Totems show on the Normal, TotemTimers, Single Totem and Dynamic (PvP) styles, with Totem Rows"] = "|cffffa040快捷图腾只显示在普通、TotemTimers、单图腾和动态（PvP）样式下，且需关闭图腾行。"
L["|cffffa040Raid Cooldowns is not loaded. These settings will not work and may not save. Turn on ShamanPower [Raid Cooldowns] in the AddOns list, then type /reload.|r"] = "|cffffa040未加载团队冷却。这些设置不会生效，也可能无法保存。请在插件列表中开启 ShamanPower [Raid Cooldowns]（团队冷却），然后输入 /reload。|r"
L["|cffffa040The Grid style has no panel, so these are not shown while it is on.|r"] = "|cffffa040网格样式没有面板，因此开启期间不显示这些内容。|r"
L["|cffffa040The dots show who has each totem's buff, including in combat and instances. A red dot means that player is missing the buff. The number counter is an estimate in combat.|r"] = "|cffffa040圆点显示谁拥有每个图腾的增益，包括在战斗和副本中。红点表示该玩家缺少该增益。数字计数器在战斗中为估算值。|r"
L["|cffffa040The range overlay is hidden right now. It shows by itself only for a non-shaman grouped with a shaman; click this page's power dot or type /sprange to show it while you adjust these.|r"] = "|cffffa040范围覆盖层当前处于隐藏状态。它只在非萨满与萨满同队时自动显示；要一边调整这些设置一边看效果，点击本页的开关圆点，或输入 /sprange。|r"
L["|cffffa040The text alert shows in Expiring Alerts, which is turned off right now. Turn Expiring Alerts"] = "|cffffa040文字提醒显示在“到期提醒”中，但该模块当前已关闭。请开启“到期提醒”"
L["|cffffa040The totems you picked show on the strip once you learn them.|r"] = "|cffffa040学会你所选的图腾后，它们会显示在条带上。|r"
L["|cffffa040Totem Range Tracker is not loaded. Turn on ShamanPower [Totem Range]"] = "|cffffa040图腾范围追踪未加载。请开启 ShamanPower [Totem Range]"
L["|cffffa040Totem flyouts are turned off (Settings > Bars > Totem Bar > Bar),"] = "|cffffa040图腾弹出菜单已关闭（设置 > 条 > 图腾条 > 条），"
L["|cffffa040Totem flyouts are turned off (Show Totem Flyouts), so a click on a totem has no effect until you"] = "|cffffa040图腾弹出菜单已关闭（“显示图腾弹出菜单”），因此点击图腾不会产生任何效果，直到你"
L["|cffffa040Tremor Reminder is disabled, so these settings only show up in Test Alert.|r"] = "|cffffa040“战栗图腾提醒”已禁用，因此这些设置仅在测试提醒中显示。|r"
L["|cffffa040Turn on Reactive Totems to use the settings below.|r"] = "|cffffa040开启“应急图腾”后，下方设置才会生效。|r"
L["|cffffa040Water is set to Empty, so Drop All already skips it. This setting applies once you assign a Water totem.|r"] = "|cffffa040水已设为“空”，因此全部插放会跳过它。此设置在你分配水图腾后生效。|r"
L["|cffffa040Windfury: each party member's own ShamanPower (or the Windfury WeakAura) reports it. Anyone who doesn't report it shows a gray question mark.|r"] = "|cffffa040风怒：由每位队员自己的 ShamanPower（或风怒 WeakAura）上报。未上报的成员会显示灰色问号。|r"
L["|cffffcc00Right-click:|r Assign as ES target"] = "|cffffcc00右键：|r 指定为大地之盾目标"
L["|cffffcc00Right-click:|r Cast "] = "|cffffcc00右键：|r 施放 "
L["|cffffcc00Right-click:|r Cast totem"] = "|cffffcc00右键点击：|r 施放图腾"
L["|cffffcc00Right-click:|r Set as assigned totem"] = "|cffffcc00右键点击：|r 设为已分配图腾"
L["|cffffd100Blizzard's Totem Bar|r: keep the game's own bar and get ShamanPower's timers, bars and dots on its slots. Its flyouts open only from the little arrow above each slot, one click before you can pick a totem."] = "|cffffd100Blizzard 的图腾条|r：保留游戏自带的条，并在其槽位上获得 ShamanPower 的计时器、条和圆点。它的飞出菜单只能通过每个槽位上方的箭头打开，需先点击一次才能选择图腾。"
L["|cffffd100Compact|r: no icons - each slot is a colored line that drains with the totem and refills with each pulse."] = "|cffffd100紧凑|r：没有图标——每个槽位是一条彩色线条，随图腾消耗而减少，每次脉冲时回充。"
L["|cffffd100Dropped Totems|r: only the totems you have down, centered as a group, each with its bar, time and pulse. No flyouts, no clicks; your keybinds still cast."] = "|cffffd100已插放图腾|r：只显示你已插下的图腾，作为一组居中排列，每个都有其条、时间和脉冲。没有飞出菜单，也不响应点击；你的按键仍可施放。"
L["|cffffd100Dynamic|r: the bar is simply whatever you last dropped. Great for PvP."] = "|cffffd100动态|r：图腾条就是你最后插下的内容。非常适合 PvP。"
L["|cffffd100Grid|r: all your totems in rows, together or in a separate group for each element."] = "|cffffd100网格|r：所有图腾分行排列，可合并或按元素分成各自一组。"
L["|cffffd100Normal|r: assigned totems stay put; a different dropped totem pops up above its slot."] = "|cffffd100普通|r：已分配图腾固定不动；插下的不同图腾会弹在对应槽位上方。"
L["|cffffd100Show every totem in rows|r (under the cards, with any style but Grid): each element's totems also in a row of their own that you place anywhere."] = "|cffffd100以行显示所有图腾|r（卡片下方，除网格外的任何样式）：每个元素的图腾也会各自成行，可放置在任何位置。"
L["|cffffd100Single Totem|r: the button shows the totem you dropped, but a click always drops your assigned one, and it goes back to it the moment the dropped totem is gone. Also great for PvP."] = "|cffffd100单图腾|r：按钮显示你插下的图腾，但点击始终插下你分配的图腾，插下的图腾消失后立即恢复为分配图腾。也非常适合 PvP。"
L["|cffffd100TotemTimers Style|r: the dropped totem becomes the big icon, assigned shrinks to the corner."] = "|cffffd100TotemTimers 样式|r：插下的图腾成为大图标，已分配图腾缩小到角落。"
L["|cffffd200>|r  Get help setting ShamanPower up\n"] = "|cffffd200>|r  获取 ShamanPower 设置帮助\n"
L["|cffffd200>|r  Report bugs straight to the developer\n"] = "|cffffd200>|r  直接向开发者报告错误\n"
L["|cffffd200>|r  Suggest new features and vote on ideas\n"] = "|cffffd200>|r  建议新功能并为想法投票\n"
